INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C1','kor',4,2,'u3',2,'이 단원에서 배울 두 가지 — 토의로 문제의 해결 방법을 찾기 · 그 방법을 의견과 이유가 드러나게 제안하는 글로 알리기',ARRAY['[4국01-06][4국03-03]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C2','kor',4,2,'u3',2,'토의 — 혼자서는 풀기 어려운 문제를 여럿이 의견을 모아 해결 방법을 찾는 것(교실 앞문 문턱)',ARRAY['[4국01-06]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C3','kor',4,2,'u3',2,'토의에 알맞은 일 — 여러 의견이 나올 수 있고 모두와 관련 있는 일 — 답이 하나로 정해진 일이나 나 혼자만의 일은 토의할 까닭이 없음',ARRAY['[4국01-06]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C4','kor',4,2,'u3',2,'토의할 때 바른 태도 — 손을 들고 내 차례에 말하기 · 나와 다른 의견도 끝까지 듣기 — 끼어들거나 목소리 큰 친구의 의견을 그대로 따르지 않음',ARRAY['[4국01-06]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C5','kor',4,2,'u3',2,'제안과 제안하는 글 — 제안은 어떤 일에 대해 의견을 내놓는 것 — 제안하는 내용을 담아 쓴 글이 제안하는 글',ARRAY['[4국01-06][4국03-03]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C6','kor',4,2,'u3',2,'토의와 제안하는 글의 관계 — 둘 다 문제를 해결하는 방법 — 토의로 정한 것을 글로 제안할 수도 있고, 상황에 따라 알맞은 방법을 고름(언제나 글부터도, 글은 필요 없음도 아님)',ARRAY['[4국01-06][4국03-03]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C7','kor',4,2,'u3',2,'글쓴이의 의견 찾기 — 「……하면 어떨까요?」처럼 바라는 것을 내놓는 문장에서 의견을 찾음 — 문제 상황이나 좋아지는 점과 구별',ARRAY['[4국01-06][4국03-03]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C8','kor',4,2,'u3',2,'토의 절차 — 주제 정하기(풀 문제 고르기) → 의견 마련하기(의견과 이유 준비) → 의견 모으기(묻고 따지기) → 의견 결정하기(기준으로 정하기)',ARRAY['[4국01-06]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C9','kor',4,2,'u3',2,'주제를 정할 때 — 여러 문제 가운데 어느 것이 더 급한지 까닭을 들어 이야기한 뒤 정함',ARRAY['[4국01-06]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C10','kor',4,2,'u3',2,'토의할 때 주의할 점 — 우리가 해결할 수 있는 주제인지 살핌 · 내 의견의 단점도 생각 · 끝까지 듣고 알맞은지 따짐 · 기준을 세워 견주어 정함 · 말할 기회를 고르게 · 주제에서 벗어나지 않게',ARRAY['[4국01-06]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C11','kor',4,2,'u3',2,'질문하면 좋은 점 — 친구의 생각을 더 정확히 알고, 의견이 주제에 알맞은지 함께 따지고, 답을 생각하는 사이에 의견이 더 나아짐(테이프로 덮기)',ARRAY['[4국01-06]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C12','kor',4,2,'u3',2,'상대의 기분을 헤아린 질문 — 의견의 좋은 점을 먼저 인정하고 궁금한 점을 구체적으로 물음 — 내가 그 친구라면 기꺼이 답하고 싶은 질문',ARRAY['[4국01-06]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C13','kor',4,2,'u3',2,'말투와 내용 둘 다 — 공손한 말투는 필요하지만 질문은 의견이 문제를 해결하는지 따지는 데 도움이 되어야 함(스티커 색 ✗) — 질문 수를 채우는 것도 목적이 아님',ARRAY['[4국01-06]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C14','kor',4,2,'u3',2,'더 나은 의견을 만드는 질문 갈래 — 결과(무엇이 달라질까요?) · 어려움(곤란한 점은 없을까요?) · 실천 방법(언제, 누가, 어떻게?)',ARRAY['[4국01-06]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C15','kor',4,2,'u3',4,'모둠 토의 주제 고르기 — 우리 모두와 관련 있고, 여러 의견이 나올 수 있고, 우리가 해결에 나설 수 있는 문제(현관 바닥 · 음수대 줄)',ARRAY['[4국01-06]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C16','kor',4,2,'u3',4,'문제가 생긴 까닭과 영향 — 까닭은 「왜 그런가」(젖은 우산과 신발의 물이 고임), 영향은 그 때문에 생기는 일(미끄러져 다칠 수 있음·현관이 붐빔)',ARRAY['[4국01-06]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C17','kor',4,2,'u3',4,'의견을 마련할 때 스스로 묻기 — 문제 해결에 도움이 되는가 · 우리가 실천할 수 있는가 · 이유가 알맞은가 · 단점도 생각했는가',ARRAY['[4국01-06]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C18','kor',4,2,'u3',4,'쉬운 의견과 알맞은 의견 — 쉽게 할 수 있어도 문제를 해결하지 못하면 알맞은 의견이 아님(솔비) — 쉬운지와 해결되는지를 함께 따지고, 쉬운 의견을 모두 버리는 것도 아님',ARRAY['[4국01-06]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C19','kor',4,2,'u3',4,'모둠 친구 의견에 할 질문 — 실천 방법이나 어려움을 존중하는 말로 물음 — 의견과 상관없는 것을 묻거나 깎아내리지 않음',ARRAY['[4국01-06]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C20','kor',4,2,'u3',4,'질문에 답하며 자라는 의견 — 질문에 답하면서 의견이 더 구체적으로 다듬어짐(두 사람씩 요일 · 발판 두 장) — 의견을 고쳐도 지는 것이 아님',ARRAY['[4국01-06]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C21','kor',4,2,'u3',4,'의견을 결정하는 방법 — 해결에 도움이 되는지, 실천할 수 있는지 기준에 비추어 견줌 — 합치든 하나를 고르든 같은 기준으로 따짐(넷을 모두 합치면 언제나 좋다 ✗)',ARRAY['[4국01-06]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C22','kor',4,2,'u3',4,'우리 힘으로 못 하는 일 — 발판처럼 우리 힘만으로 할 수 없는 일은 바꿀 수 있는 곳에 제안하기로 함 — 제안하는 글로 이어짐',ARRAY['[4국01-06]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C23','kor',4,2,'u3',4,'구체적인 실천 계획 — 언제 · 누가 · 무엇을 할지 분명하게(비 오는 날 등교 시간에 두 사람씩 요일을 나누어) — 「열심히 노력한다」는 계획이 아님',ARRAY['[4국01-06]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C24','kor',4,2,'u3',4,'토의 참여 점검 — 주제에 알맞은 의견과 이유 · 궁금한 점이나 어려움 묻기 · 끝까지 듣기 · 결정이 내 의견과 달라도 함께 실천',ARRAY['[4국01-06]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C25','kor',4,2,'u3',6,'누구에게 제안할까 — 그 일을 정하거나 바꿀 수 있는 사람에게 제안함(교실을 어떻게 쓸지 정하는 방과 후 담당 선생님)',ARRAY['[4국03-03]']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C26','kor',4,2,'u3',6,'문제 상황 찾기 — 누가 어디에서 어떤 불편을 겪는지 찾음(기다릴 곳이 없어 복도 바닥에 앉아 있고 부딪치기도 함)',ARRAY['[4국03-03]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C27','kor',4,2,'u3',6,'제안하는 글의 짜임 — 문제 상황(무엇이 불편한가) · 제안하는 내용(무엇을 바라는가) · 제안하는 이유(그러면 무엇이 좋은가)',ARRAY['[4국03-03]']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C28','kor',4,2,'u3',6,'막기만 하는 말과 제안 — 「복도에 앉지 마세요」처럼 「~하세요」로 끝나도 막기만 하고 해결 방법과 이유가 없으면 제안하는 글로는 부족함',ARRAY['[4국03-03]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C29','kor',4,2,'u3',6,'쓰기 전에 생각할 내용 — 제안하는 내용이 드러나는 제목 · 누구에게 쓸지 · 문제 상황을 보여 줄 그림이나 사진 · 글을 어떻게 전할지',ARRAY['[4국03-03]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C30','kor',4,2,'u3',6,'제안하는 글을 쓰면 좋은 점 — 문제와 해결 방법이 또렷하게 정리됨 · 만나기 어려운 분께도 차분히 전함 · 읽은 사람도 관심을 두고 함께 나섬 — 언제나 받아들여지는 것도, 불만을 쏟는 글도 아님',ARRAY['[4국03-03]']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C31','kor',4,2,'u3',6,'상황에 맞는 방법 고르기 — 짝이 지우개를 말없이 가져다 쓰는 것처럼 두 사람 사이의 일은 직접 차분히 말하는 것이 알맞음 — 제안하는 글은 여러 방법 가운데 하나',ARRAY['[4국03-03]']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C32','kor',4,2,'u3',7,'제안하는 글을 쓰는 과정 — 문제 상황 파악하기 → 누구에게 제안할지 생각하기 → 제안하는 내용을 정하고 이유 설명하기 → 제안하는 글 쓰기',ARRAY['[4국03-03]']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C33','kor',4,2,'u3',7,'앞 단계로 되돌아가기 — 쓰다가 이유가 약한 것을 알면 앞 단계로 돌아가 다시 생각해도 됨 — 차례는 길잡이',ARRAY['[4국03-03]']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C34','kor',4,2,'u3',7,'제안할 대상 정하기 — 안내판을 달고 고치는 일을 정할 수 있는 시청 담당자처럼, 제안을 받아 실제로 바꿀 수 있는 곳 — 대상을 분명히 하면 제안이 구체적이 됨',ARRAY['[4국03-03]']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C35','kor',4,2,'u3',7,'알맞은 제안 내용 — 문제를 바로 해결하면서 실제로 할 수 있는 제안(눈높이 안내판 · 큰 글자) — 해결은 되지만 실천이 어렵거나(하루 종일 안내하는 사람) 문제에서 멀어진 제안(버스 없애기)은 알맞지 않음',ARRAY['[4국03-03]']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C36','kor',4,2,'u3',7,'알맞은 이유 — 제안대로 하면 여러 사람에게 무엇이 좋아지는지 보여 주는 이유 — 「왜냐하면」을 썼다고 알맞은 것도, 내 불편만 말하는 것도 아님',ARRAY['[4국03-03]']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C37','kor',4,2,'u3',7,'문제 상황과 제목 — 문제 상황은 겪은 일로 구체적으로 쓰고, 제목은 무엇을 제안하는지 드러나게 붙임(다 쓰고 나서 붙여도 됨)',ARRAY['[4국03-03]']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C38','kor',4,2,'u3',7,'제안과 이유의 표현 — 제안 — 「……면 좋겠습니다」 「……면 어떨까요?」 「……합시다」 · 이유 — 「왜냐하면 ……때문입니다」 「……면 ……할 수 있습니다」 — 외우지 않고 문장에 어울리는 것을 고름',ARRAY['[4국03-03]']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C39','kor',4,2,'u3',7,'예의 있게 제안하기 — 읽는 사람이 받아들이고 싶어지게 예의 있게 씀 — 불만을 쏟거나(생각이 없나 봐요) 억지로 요구하지 않음(무조건 고쳐 놓으세요)',ARRAY['[4국03-03]']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C40','kor',4,2,'u3',7,'받아들여지지 않을 때 — 제안은 받아들여질 때도, 까닭이 있어 받아들여지지 않을 때도 있음 — 그 까닭을 살펴 제안을 고치거나 다른 방법을 찾음',ARRAY['[4국03-03]']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C41','kor',4,2,'u3',9,'제안하는 내용과 이유의 짝 — 「무엇을 바라는가」(낮은 반납함을 하나 더)와 「그러면 무엇이 좋은가」(동생들도 스스로 돌려줌)를 짝지어 찾음',ARRAY['[4국03-03]']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C42','kor',4,2,'u3',9,'제안하는 글로 풀기 알맞은 문제 — 많은 사람이 겪고, 바꿀 수 있는 분께 해결 방법을 제안할 수 있는 문제 — 날씨처럼 바꿀 수 없는 일이나 두 사람 사이의 속상한 일과 구별',ARRAY['[4국03-03]']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C43','kor',4,2,'u3',9,'이유에는 좋아지는 점과 확인한 사실 — 여러 사람에게 좋아지는 점과 여쭈어 확인한 사실이 이유가 됨 — 내 취향이나 확인하지 않은 짐작(다른 학교에도 다 있을 것 같다)은 이유로 약하고, 사실처럼 쓰지 않음',ARRAY['[4국03-03]']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C44','kor',4,2,'u3',9,'개요 짜기 — 쓸 내용을 처음 · 가운데 · 끝으로 나누어 핵심 낱말로 짧게 적어 차례를 정함 — 글 전체를 미리 다 쓰지 않음',ARRAY['[4국03-03]']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C45','kor',4,2,'u3',9,'문장의 짜임 — 누가/무엇이 + 어찌하다(우리는 손을 씻습니다) · 어떠하다(물이 차갑습니다) · 무엇이다(이곳은 수돗가입니다)',ARRAY['[4국04-03]']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C46','kor',4,2,'u3',9,'어색한 문장 고치기 — 「누가/무엇이」와 뒷부분이 서로 어울리게 고침(수돗가는 손을 씻는 곳입니다 · 우리는 비누로 손을 깨끗이 씻습니다)',ARRAY['[4국04-03][4국03-01]']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C47','kor',4,2,'u3',9,'「무엇이」 칸에 오는 것 — 「누가/무엇이」 칸에는 사람만이 아니라 물건도 옴 — 비누 걸이가(무엇이) + 튼튼합니다(어떠하다)',ARRAY['[4국04-03]']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C48','kor',4,2,'u3',9,'점검하고 고쳐 쓰기 — 누구에게 제안하는지 · 문제 상황을 구체적으로 · 내용과 이유 · 소리 내어 읽어 어색한 문장 · 제목을 살펴 고침 — 친구의 제안이 더 좋으면 받아들여 다듬어도 됨',ARRAY['[4국03-03][4국03-01]']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C49','kor',4,2,'u3',9,'글을 전하는 방법 — 읽을 사람에 맞게 전함 — 교장 선생님께는 직접 드리고, 이웃에게는 허락을 받아 게시판에, 시청에는 누리집 제안 게시판에',ARRAY['[4국03-03]']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C50','kor',4,2,'u3',11,'질문 쪽지 — 친구 의견 곁에 붙이는 질문 쪽지는 실천할 때의 어려움이나 단점을 존중하는 말로 물어 의견을 더 나아지게 함 — 글씨·글쓴이를 묻거나 이상하다고 하지 않음',ARRAY['[4국01-06][4국03-03]']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C51','kor',4,2,'u3',11,'해결은 바라는 모습을 이루는 것 — 「놀잇감을 모두 치우자」는 다툼을 없애지만 「함께 즐겁게 놀자」는 바람까지 없앰 — 문제만 없애는 것이 아니라 바라는 모습을 이루어야 해결',ARRAY['[4국01-06][4국03-03]']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C52','kor',4,2,'u3',11,'안건 발표의 짜임 — 문제 상황(응원 도구가 한 번 쓰고 버려짐) → 제안하는 내용(나눔 상자) → 제안하는 이유(쓰레기가 줄고 준비 시간을 아낌)로 이어 말함',ARRAY['[4국01-06][4국03-03]']::text[],52) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C53','kor',4,2,'u3',11,'안건 고르기 — 전교 학생 자치회에는 많은 학생과 관련 있고, 실천할 수 있으며, 이유에 공감을 얻은 제안을 냄 — 목소리 크기나 우리 반만의 좋은 점으로 고르지 않음',ARRAY['[4국01-06][4국03-03]']::text[],53) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C54','kor',4,2,'u3',11,'한 낱말이 되면 붙여 쓰기 — 두 낱말이 만나 하나의 낱말이 되면 붙여 씀 — 정리를 하다 → 정리하다 · 겁을 먹다 → 겁먹다 · 마음을 먹다 → 마음먹다',ARRAY['[4국04-03]']::text[],54) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C55','kor',4,2,'u3',11,'이어져도 띄어 쓰는 말 — 「밥 먹다 · 물 마시다」처럼 하나의 낱말이 된 것이 아니면 띄어 씀 — 헷갈리면 사전을 찾음',ARRAY['[4국04-03]']::text[],55) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C56','kor',4,2,'u3',11,'낱말 사이의 관계 — 뜻이 비슷한 관계(무섭다-두렵다) · 뜻이 반대인 관계(넓다-좁다) · 뜻을 포함하는 관계(악기 ⊃ 피아노)',ARRAY['[4국04-03]']::text[],56) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C57','kor',4,2,'u3',11,'반대말은 쓰임에 따라 — 같은 「벗다」라도 무엇을 벗는지에 따라 반대말이 입다 · 쓰다 · 신다 · 끼다로 달라짐 — 반대말이 하나뿐인 것은 아님',ARRAY['[4국04-03]']::text[],57) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C58','kor',4,2,'u3',11,'겹받침 ㄺ 바르게 쓰기 — 맑다 · 굵다 · 흙길 · 닭장 — ㄹ과 ㄱ을 받침 칸 안에 나란히, 한쪽이 너무 크지 않게 씀',ARRAY['기초 다지기(띄어쓰기·낱말 관계·글씨 — 성취기준 번호 확인 필요)']::text[],58) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X01','kor',4,'u3',ARRAY['K4-2-u3-C2']::text[],'토의를 여럿이 모여 아무 이야기나 나누는 것이나 한 사람이 정해 알려 주는 것으로 여긴다','여럿이 해결 방법을 찾아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X02','kor',4,'u3',ARRAY['K4-2-u3-C3','K4-2-u3-C15']::text[],'답이 하나로 정해진 일이나 나 혼자만의 일도 토의할 일로 고른다','여러 의견 · 모두와 관련') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X03','kor',4,'u3',ARRAY['K4-2-u3-C4','K4-2-u3-C24']::text[],'토의할 때 다른 의견에 끼어들거나 목소리 큰 친구의 의견을 그대로 따르는 것을 바른 태도로 여긴다','차례 · 끝까지 듣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X04','kor',4,'u3',ARRAY['K4-2-u3-C6','K4-2-u3-C31']::text[],'문제가 생기면 언제나 제안하는 글부터 써야 한다고 여긴다','상황에 맞는 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X05','kor',4,'u3',ARRAY['K4-2-u3-C6']::text[],'토의를 했으면 제안하는 글은 필요 없다고 여기거나 토의와 제안하는 글을 서로 관계없는 것으로 여긴다','토의로 정한 것을 글로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X06','kor',4,'u3',ARRAY['K4-2-u3-C7','K4-2-u3-C41']::text[],'글쓴이의 의견(제안하는 내용)을 문제 상황이나 좋아지는 점, 글에 없는 내용과 헷갈린다','무엇을 바라는가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X07','kor',4,'u3',ARRAY['K4-2-u3-C8']::text[],'토의 절차의 차례나 단계마다 하는 일을 엇갈리게 안다','고르기 → 준비 → 따지기 → 정하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X08','kor',4,'u3',ARRAY['K4-2-u3-C9']::text[],'토의 주제를 어느 것이 더 급한지 따지지 않고 먼저 나온 것이나 손든 수로만 정한다','더 급한 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X09','kor',4,'u3',ARRAY['K4-2-u3-C10','K4-2-u3-C15']::text[],'우리가 해결에 나설 수 없을 만큼 큰 문제를 토의 주제로 고른다(방학 한 달 늘리기·학교 새로 짓기)','우리가 풀 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X10','kor',4,'u3',ARRAY['K4-2-u3-C10','K4-2-u3-C17']::text[],'내 의견의 단점은 생각하지 않고 「이것만 하면 끝」이라고 여긴다','단점도 생각해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X11','kor',4,'u3',ARRAY['K4-2-u3-C11']::text[],'토의에서 질문은 상대가 의견을 포기하게 만들거나 시간을 늘리는 것이라고 여긴다','의견을 다듬어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X12','kor',4,'u3',ARRAY['K4-2-u3-C12','K4-2-u3-C19','K4-2-u3-C50']::text[],'상대의 기분을 헤아리지 않고 틀렸다고 먼저 말하거나 깎아내리며 묻는 질문을 괜찮다고 여긴다','좋은 점 먼저 · 구체적으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X13','kor',4,'u3',ARRAY['K4-2-u3-C13']::text[],'「좋은 의견이에요」 같은 존중하는 말만 붙이면 무엇을 묻든 좋은 질문이라고 여긴다','말투와 내용 둘 다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X14','kor',4,'u3',ARRAY['K4-2-u3-C13','K4-2-u3-C51']::text[],'질문은 많을수록 좋다고 여겨 궁금한 것이 없어도 수를 채우거나, 질문을 많이 받은 의견이 좋은 의견이라고 여긴다','개수보다 쓸모') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X15','kor',4,'u3',ARRAY['K4-2-u3-C14']::text[],'결과 · 어려움 · 실천 방법을 묻는 질문을 엇갈리게 안다','달라질까 · 곤란할까 · 언제 누가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X16','kor',4,'u3',ARRAY['K4-2-u3-C16']::text[],'문제가 생긴 까닭과 그 때문에 생긴 영향을 헷갈린다','왜 그런가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X17','kor',4,'u3',ARRAY['K4-2-u3-C17','K4-2-u3-C18']::text[],'가장 쉽게 할 수 있는 의견이 언제나 가장 좋은 의견이라고 여긴다','해결되는지도 따져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X18','kor',4,'u3',ARRAY['K4-2-u3-C18']::text[],'쉬운 의견은 해결에 도움이 되더라도 모두 버려야 한다고 여긴다','쉬운지와 해결되는지 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X19','kor',4,'u3',ARRAY['K4-2-u3-C21']::text[],'여러 의견을 모두 합치면 언제나 가장 좋은 의견이 된다고 여긴다','합친 것도 기준으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X20','kor',4,'u3',ARRAY['K4-2-u3-C21']::text[],'기준 없이 가위바위보나 빨리 정하는 것으로 의견을 결정한다','기준에 비추어 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X21','kor',4,'u3',ARRAY['K4-2-u3-C23']::text[],'실천 계획을 「열심히 노력한다」·「언젠가 해 본다」처럼 막연하게 세운다','언제 · 누가 · 무엇을') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X22','kor',4,'u3',ARRAY['K4-2-u3-C22']::text[],'우리 힘만으로 할 수 없는 일을 억지로 우리끼리 하려 하거나 그냥 포기한다','바꿀 수 있는 곳에 제안') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X23','kor',4,'u3',ARRAY['K4-2-u3-C20']::text[],'질문을 받고 의견을 고치면 진 것이라고 여기거나 질문 때문에 의견이 나빠진다고 여긴다','답하며 의견이 자라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X24','kor',4,'u3',ARRAY['K4-2-u3-C25','K4-2-u3-C34']::text[],'제안할 대상을 그 일을 정하거나 바꿀 수 없는 사람으로 고른다','바꿀 수 있는 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X25','kor',4,'u3',ARRAY['K4-2-u3-C26']::text[],'문제 상황을 글이나 그림과 상관없는 것으로 찾는다','누가 어디서 어떤 불편?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X26','kor',4,'u3',ARRAY['K4-2-u3-C27','K4-2-u3-C52']::text[],'문제 상황 · 제안하는 내용 · 제안하는 이유를 엇갈리게 짝짓는다','불편 → 바람 → 좋아지는 점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X27','kor',4,'u3',ARRAY['K4-2-u3-C28']::text[],'「~하세요」로 끝나면 해결 방법이 없어도 제안하는 글이라고 여긴다','해결 방법이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X28','kor',4,'u3',ARRAY['K4-2-u3-C28']::text[],'짧게 막기만 하는 말일수록 좋은 제안이라고 여긴다','방법과 이유까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X29','kor',4,'u3',ARRAY['K4-2-u3-C29']::text[],'제안하는 글을 쓰기 전에 생각할 내용(제목·대상·그림이나 사진·전할 방법)을 모르거나 상관없는 것을 고른다','제목 · 누구 · 사진 · 전하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X30','kor',4,'u3',ARRAY['K4-2-u3-C30','K4-2-u3-C40']::text[],'글로 제안하면 언제나 받아들여진다고 여긴다','받아들여지지 않을 때도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X31','kor',4,'u3',ARRAY['K4-2-u3-C30','K4-2-u3-C39']::text[],'제안하는 글을 속상한 마음이나 불만을 마음껏 쏟아 내는 글로 여긴다','해결 방법을 내놓아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X32','kor',4,'u3',ARRAY['K4-2-u3-C32']::text[],'제안하는 글을 쓰는 과정의 차례를 엇갈리게 안다','문제 → 누구 → 내용·이유 → 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X33','kor',4,'u3',ARRAY['K4-2-u3-C33']::text[],'쓰는 과정은 차례대로만 가야 하고 앞 단계로 되돌아가면 안 된다고 여긴다','차례는 길잡이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X34','kor',4,'u3',ARRAY['K4-2-u3-C35']::text[],'문제만 해결되면 실천하기 어려운 제안도 알맞다고 여긴다(하루 종일 안내하는 사람 세우기)','실제로 할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X35','kor',4,'u3',ARRAY['K4-2-u3-C35','K4-2-u3-C41']::text[],'문제에서 멀어지거나 문제를 키우는 제안을 고른다(버스를 없애기·건물을 새로 짓기)','이 문제를 바로 푸나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X36','kor',4,'u3',ARRAY['K4-2-u3-C36']::text[],'「왜냐하면 ……때문입니다」만 쓰면 무엇이든 알맞은 이유가 된다고 여긴다','무엇이 좋아지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X37','kor',4,'u3',ARRAY['K4-2-u3-C36','K4-2-u3-C43']::text[],'내가 겪은 불편이나 내 취향만으로 제안하는 이유를 든다','여러 사람에게 좋아지는 점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X38','kor',4,'u3',ARRAY['K4-2-u3-C43']::text[],'확인하지 않은 짐작을 사실처럼 이유로 쓴다','확인한 사실인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X39','kor',4,'u3',ARRAY['K4-2-u3-C39']::text[],'「무조건」·「당장」처럼 억지로 요구하거나 상대를 탓하는 표현을 제안하는 글에 쓴다','예의 있게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X40','kor',4,'u3',ARRAY['K4-2-u3-C38']::text[],'제안 표현은 외워서 어느 문장에나 똑같이 넣어야 한다고 여기거나 제안 표현과 이유 표현을 엇갈리게 안다','어울리는 것을 골라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X41','kor',4,'u3',ARRAY['K4-2-u3-C40']::text[],'제안이 받아들여지지 않으면 포기하거나 같은 글을 날마다 다시 보낸다','까닭을 살펴 고쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X42','kor',4,'u3',ARRAY['K4-2-u3-C37','K4-2-u3-C48']::text[],'문제 상황을 막연하게 쓰거나, 제목을 제안 내용과 상관없이 붙인다','겪은 일 · 제안이 드러나는 제목') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X43','kor',4,'u3',ARRAY['K4-2-u3-C42']::text[],'제안하는 글로 풀 문제로 날씨처럼 바꿀 수 없는 일이나 두 사람 사이의 속상한 일을 고른다','누구에게 제안하면 바뀌나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X44','kor',4,'u3',ARRAY['K4-2-u3-C44']::text[],'개요에 글 전체를 미리 다 쓰거나 개요 없이 떠오르는 대로 쓴다','핵심 낱말로 짧게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X45','kor',4,'u3',ARRAY['K4-2-u3-C45']::text[],'어찌하다 · 어떠하다 · 무엇이다 문장의 짜임을 엇갈리게 안다','움직임 · 모습 · 무엇') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X46','kor',4,'u3',ARRAY['K4-2-u3-C46']::text[],'「누가/무엇이」와 뒷부분이 어울리지 않는 문장을 그대로 두거나 엉뚱하게 고친다','소리 내어 읽어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X47','kor',4,'u3',ARRAY['K4-2-u3-C47']::text[],'「누가/무엇이」 칸에는 사람만 올 수 있다고 여기거나 짧으면 문장이 아니라고 여긴다','물건도 「무엇이」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X48','kor',4,'u3',ARRAY['K4-2-u3-C49']::text[],'글을 전하는 방법을 읽을 사람과 상관없이 정한다','누구에게 어떻게?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X49','kor',4,'u3',ARRAY['K4-2-u3-C51']::text[],'다툼이나 문제만 없어지면 원래 바라던 것까지 없어져도 해결이라고 여긴다','바라는 모습을 이루나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X50','kor',4,'u3',ARRAY['K4-2-u3-C53']::text[],'안건을 발표 목소리 크기나 우리 반에만 좋은 점으로 고른다','많은 학생 · 공감') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X51','kor',4,'u3',ARRAY['K4-2-u3-C55']::text[],'두 낱말이 이어지면 언제나 붙여 써야 한다고 여긴다(밥먹고·물마시고)','한 낱말이 됐나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X52','kor',4,'u3',ARRAY['K4-2-u3-C54']::text[],'하나의 낱말이 된 말을 띄어 쓴다(정리 하고·겁 먹고)','한 낱말은 붙여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X53','kor',4,'u3',ARRAY['K4-2-u3-C56']::text[],'뜻이 비슷한 · 반대인 · 포함하는 관계를 엇갈리게 안다','비슷 · 반대 · 포함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X54','kor',4,'u3',ARRAY['K4-2-u3-C57']::text[],'한 낱말의 반대말은 하나뿐이라고 여긴다','무엇을 벗나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X55','kor',4,'u3',ARRAY['K4-2-u3-C58']::text[],'겹받침 ㄺ을 받침 하나로 쓰거나 다른 받침으로 쓴다(막다·말다·흑길)','ㄹ과 ㄱ을 나란히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X56','kor',4,'u3',ARRAY['K4-2-u3-C1']::text[],'이 단원에서 배울 내용을 단원과 상관없는 것으로 여긴다','토의 · 제안하는 글') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X57','kor',4,'u3',ARRAY['K4-2-u3-C5','K4-2-u3-C25']::text[],'제안을 명령하거나 불평하는 것으로 여긴다','의견을 내놓는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X58','kor',4,'u3',ARRAY['K4-2-u3-C24']::text[],'모둠에서 결정한 의견이 내 의견과 다르면 따르지 않아도 된다고 여긴다','함께 실천해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X59','kor',4,'u3',ARRAY['K4-2-u3-C13','K4-2-u3-C14']::text[],'토의에서 질문을 친구가 대답하기 어려워할 만한 것이나 단순한 사실·낱말의 뜻을 묻는 것으로 여기고, 필요 없는데도 질문을 의무적으로 만들어 낸다','이 질문이 더 나은 의견을 만드는 데 도움이 될까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X60','kor',4,'u3',ARRAY['K4-2-u3-C10','K4-2-u3-C24']::text[],'의견이 토의 주제에 알맞은지 판단하지 않고, 친한 친구가 낸 의견이니 좋다고 하거나 누가 냈는지로 좋고 나쁨을 정한다','누가 냈나보다 주제에 알맞은가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X61','kor',4,'u3',ARRAY['K4-2-u3-C21']::text[],'모둠에서 의견을 결정할 때에는 반드시 한 가지 의견만 골라야 하고, 여러 의견을 모아 새로운 의견을 만들면 안 된다고 여긴다','여러 의견의 좋은 점을 모을 수도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X62','kor',4,'u3',ARRAY['K4-2-u3-C27','K4-2-u3-C41']::text[],'제안하는 글은 언제나 제안 하나와 이유 하나로만, 정해진 꼴 그대로 써야 한다고 여긴다(제안이 여럿이면 제안마다 이유를 쓰거나 공통 이유를 쓸 수 있음)','제안이 여럿이면 이유는?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X63','kor',4,'u3',ARRAY['K4-2-u3-C37','K4-2-u3-C48']::text[],'제안하는 글의 처음에 제안하는 사람(소속과 이름)을 밝히지 않아도 된다고 여겨, 누가 제안했는지 알 수 없게 쓴다','누가 제안했는지 알면 무엇이 좋을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X64','kor',4,'u3',ARRAY['K4-2-u3-C17','K4-2-u3-C15']::text[],'의견이 토의 주제(해결할 문제)와 관련 있는지 살피지 않고, 재미있거나 모두가 즐겁게 참여할 수 있으면 알맞은 의견이라고 여긴다','이 의견이 주제의 문제를 푸나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_basic#1','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C1',1,'mc','auto','『국어』 115쪽 「무엇을 배울까요」예요. 이 단원의 두 소단원에서 배울 내용을 바르게 묶은 것은 무엇인가요?',ARRAY['K4-2-u3-X56']::text[],false,'{"seq":1,"concept":"K4-2-u3-C1","difficulty":1,"kind":"mc","stem":"『국어』 115쪽 「무엇을 배울까요」예요. 이 단원의 두 소단원에서 배울 내용을 바르게 묶은 것은 무엇인가요?","options":[{"t":"문제 해결을 위한 토의 하기 · 제안하는 글 쓰기","correct":true},{"t":"높임 표현 알기 · 대화 예절 지키기","mis":"K4-2-u3-X56"},{"t":"이야기 흐름 알기 · 인물의 마음 짐작하기","mis":"K4-2-u3-X56"},{"t":"시 읽기 · 감각적 표현 찾기","mis":"K4-2-u3-X56"}],"explanation":["소단원 1은 토의하는 방법과 문제 해결을 위한 토의예요.","소단원 2는 제안하는 글에 대해 알고 직접 써 보는 거예요.","두 가지 모두 문제를 해결하는 방법이에요."],"asset":{"type":"passage","lines":["소단원 1 — ① 토의하는 방법 알기 ② 일상생활의 문제 해결을 위한 토의 하기","소단원 2 — ① 제안하는 글에 대해 알기 ② 제안하는 글을 쓰는 방법 알기","③ 의견과 이유가 드러나게 제안하는 글 쓰기"],"title":"『국어』 115쪽 무엇을 배울까요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_basic#2','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C3',1,'mc','auto','다음 가운데 여럿이 의견을 모아 토의로 정하기에 알맞은 일은 무엇인가요?',ARRAY['K4-2-u3-X02']::text[],false,'{"seq":2,"concept":"K4-2-u3-C3","difficulty":1,"kind":"mc","stem":"다음 가운데 여럿이 의견을 모아 토의로 정하기에 알맞은 일은 무엇인가요?","options":[{"t":"학급에서 다 함께 할 놀이와 그 놀이 규칙 정하기","correct":true},{"t":"내가 오늘 입을 옷 고르기","mis":"K4-2-u3-X02"},{"t":"3 더하기 4의 답 구하기","mis":"K4-2-u3-X02"},{"t":"내 일기장에 쓸 낱말 고르기","mis":"K4-2-u3-X02"}],"explanation":["토의는 여러 사람과 관련 있고 여러 의견이 나올 수 있는 일을 정할 때 해요.","친구들끼리 놀이나 놀이 규칙을 정하는 것도 토의예요.","답이 정해진 일이나 나 혼자의 일은 토의할 까닭이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_basic#3','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C8',1,'match','auto','『국어』 116쪽 1번이에요. 토의 절차와 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u3-C8","difficulty":1,"kind":"match","stem":"『국어』 116쪽 1번이에요. 토의 절차와 알맞은 설명을 이으세요.","pairs":[{"l":"토의 주제 정하기","r":"우리 모두와 관련 있고 우리가 해결할 수 있는 문제를 주제로 정한다"},{"l":"의견 마련하기","r":"주제에 알맞은 의견과 그 의견을 뒷받침하는 이유를 마련한다"},{"l":"의견 모으기","r":"친구들과 의견을 나누며 서로의 의견이 적절한지 생각해 본다"},{"l":"의견 결정하기","r":"기준에 따라 주제에 가장 적절한 의견을 결정한다"}],"mis":"K4-2-u3-X07","explanation":["토의는 주제 정하기부터 시작해요.","의견을 마련한 뒤 모아서 서로 따져 봐요.","마지막에 기준에 따라 가장 알맞은 의견을 결정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_basic#4','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C4',1,'ox','auto','『국어』 114쪽 1번이에요. 토의할 때에는 사회자에게 말할 기회를 얻어 말하고, 친구의 의견을 존중하며 경청해야 해요.',ARRAY['K4-2-u3-X03']::text[],false,'{"seq":4,"concept":"K4-2-u3-C4","difficulty":1,"kind":"ox","stem":"『국어』 114쪽 1번이에요. 토의할 때에는 사회자에게 말할 기회를 얻어 말하고, 친구의 의견을 존중하며 경청해야 해요.","answer":"O","reason_options":[{"t":"차례를 지켜 말하고 나와 다른 의견도 끝까지 들어야 토의가 잘 이루어져요.","correct":true},{"t":"좋은 생각이 떠오르면 친구의 말이 끝나기 전이라도 바로 끼어들어 말해요.","mis":"K4-2-u3-X03"}],"mis":"K4-2-u3-X03","explanation":["토의에서는 사회자에게 기회를 얻어 말해요.","친구의 의견이 나와 달라도 존중하며 들어요.","끼어들면 친구의 의견을 제대로 들을 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_basic#5','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C9',2,'mc','auto','「우현이네 학급 토의 시간」에서 사회자는 손을 든 사람 수로 토의 주제를 정했어요. 실제로 토의 주제를 정할 때 함께 이야기하면 좋은 것은 무엇인가요?',ARRAY['K4-2-u3-X08','K4-2-u3-X03','K4-2-u3-X02']::text[],false,'{"seq":5,"concept":"K4-2-u3-C9","difficulty":2,"kind":"mc","stem":"「우현이네 학급 토의 시간」에서 사회자는 손을 든 사람 수로 토의 주제를 정했어요. 실제로 토의 주제를 정할 때 함께 이야기하면 좋은 것은 무엇인가요?","options":[{"t":"두 문제 가운데 어느 것이 더 시급하게 해결해야 할 문제인지","correct":true},{"t":"어느 친구가 먼저 말했는지","mis":"K4-2-u3-X08"},{"t":"어느 친구의 목소리가 더 컸는지","mis":"K4-2-u3-X03"},{"t":"두 문제 모두 토의하지 않아도 되는지","mis":"K4-2-u3-X02"}],"explanation":["우현이는 주인 없는 물건, 규빈이는 복도에서 뛰는 문제를 말했어요.","어느 문제가 더 급한지 까닭을 들어 이야기하면 좋아요.","먼저 말했거나 목소리가 크다고 주제가 되는 것은 아니에요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"“우리 교실이나 학교 주변에서 일어나는 문제나 여럿이 의견을 모아야 하는 일이 있을까요?”"},{"who":"정우현","text":"“학교 운동장이나 강당에 물건이 오랫동안 그대로 있는 경우가 많습니다. 이런 물건의 주인을 찾아 줄 수 있는 방법을 이야기해 보면 좋겠습니다.”"},{"who":"김규빈","text":"“복도에서 뛰어다니는 친구들이 있어 불편할 때가 있습니다. 복도에서 뛰어다니는 친구와 부딪쳐서 다친 친구들도 봤습니다.”"},{"who":"사회자","text":"“원하는 토의 주제에 손을 들어 주십시오. …… 오늘은 ‘친구들이 복도에서 뛰어다니는 문제를 어떻게 해결할까?’에 대하여 토의하겠습니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_basic#6','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C10',2,'blank','auto','『국어』 121쪽 4번 장면 ㉮예요. 「토의 주제를 정할 때에는 우리가 (     )할 수 있는 주제를 정한다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u3-X10','K4-2-u3-X60','K4-2-u3-X20']::text[],false,'{"seq":6,"concept":"K4-2-u3-C10","difficulty":2,"kind":"blank","stem":"『국어』 121쪽 4번 장면 ㉮예요. 「토의 주제를 정할 때에는 우리가 (     )할 수 있는 주제를 정한다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"해결","correct":true},{"t":"단점","mis":"K4-2-u3-X10"},{"t":"판단","mis":"K4-2-u3-X60"},{"t":"기준","mis":"K4-2-u3-X20"}],"explanation":["쉬는 시간을 늘리는 일은 우리가 정할 수 있는 일이 아니에요.","그래서 친구가 “가능한 일일까?” 하고 생각했어요.","토의 주제는 우리가 해결할 수 있는 것으로 정해요."],"asset":{"type":"passage","lines":["㉮ “쉬는 시간을 늘리는 방법에 대하여 이야기해 보면 어떨까요?”","(생각) 우리가 쉬는 시간을 늘리는 게 가능한 일일까?","㉯ “내 의견은 정말 완벽해! 장점밖에 없어.”","㉰ “제 의견은…….”","(생각) 토의 주제와 맞지 않지만 친한 친구가 낸 의견이니 좋다고 해야겠어.","㉱ “무조건 실천하기 쉬운 의견을 고릅시다.”","보기: 단점 · 판단 · 기준 · 해결"],"title":"『국어』 121쪽 4번 — 토의할 때 주의할 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_basic#7','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C11',2,'mc','auto','『국어』 122쪽 5번이에요. 토의할 때 질문하면 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X11','K4-2-u3-X14']::text[],false,'{"seq":7,"concept":"K4-2-u3-C11","difficulty":2,"kind":"mc","stem":"『국어』 122쪽 5번이에요. 토의할 때 질문하면 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"질문에 대한 답을 들으며 친구의 의견을 더 잘 파악할 수 있다","correct":true},{"t":"친구가 자기 의견을 포기하게 만들 수 있다","mis":"K4-2-u3-X11"},{"t":"토의 시간을 길게 늘릴 수 있다","mis":"K4-2-u3-X11"},{"t":"질문을 많이 할수록 칭찬을 받는다","mis":"K4-2-u3-X14"}],"explanation":["질문하면 친구가 왜 그런 의견을 냈는지 더 잘 알 수 있어요.","의견과 이유가 주제에 알맞은지도 확인할 수 있어요.","질문은 친구를 이기려는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_basic#8','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C12',2,'mc','auto','『국어』 120쪽 3번 (3)이에요. 민준이와 윤희의 질문 가운데에서 상대의 기분을 고려한 질문은 누구의 것이고, 왜 그런가요?',ARRAY['K4-2-u3-X12','K4-2-u3-X13','K4-2-u3-X14']::text[],false,'{"seq":8,"concept":"K4-2-u3-C12","difficulty":2,"kind":"mc","stem":"『국어』 120쪽 3번 (3)이에요. 민준이와 윤희의 질문 가운데에서 상대의 기분을 고려한 질문은 누구의 것이고, 왜 그런가요?","options":[{"t":"윤희 — “좋은 의견입니다.” 하고 먼저 공감한 뒤에 질문했다","correct":true},{"t":"민준 — 의견의 단점을 곧바로 물었다","mis":"K4-2-u3-X12"},{"t":"두 질문 모두 상대의 기분과 상관없다","mis":"K4-2-u3-X13"},{"t":"누구의 질문이든 질문 수만 많으면 된다","mis":"K4-2-u3-X14"}],"explanation":["윤희는 “좋은 의견입니다.”라고 먼저 말했어요.","친구의 의견에 공감한 뒤 궁금한 점을 물었어요.","이렇게 물으면 친구가 기분 좋게 답할 수 있어요."],"asset":{"type":"speech","turns":[{"who":"김규빈","text":"“복도 가운데에 표지판을 놓아두면 좋겠습니다. 왜냐하면 표지판이 복도 가운데에 있으면 옆으로 피해 한쪽으로만 다니게 할 수 있기 때문입니다.”"},{"who":"박민준","text":"“그런데 복도 가운데에 표지판이 있으면 거기에 부딪히는 친구도 있지 않을까요?”"},{"who":"정우현","text":"“복도 벽에 뛰어다니지 말라는 안내문을 붙이면 좋겠습니다. 왜냐하면 학생들이 안내문을 보면서 다시 한번 뛰어다니면 안 된다고 생각할 수 있기 때문입니다.”"},{"who":"최윤희","text":"“좋은 의견입니다. 그런데 안내문을 벽에 붙여 놓으면 복도를 다닐 때 잘 안 보일 수도 있지 않을까요?”"},{"who":"정우현","text":"“안내문을 조금 입체적으로 만들어 보면 어떨까요? 그러면 복도를 다닐 때 잘 볼 수 있을 것 같습니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_basic#9','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C13',2,'ox','auto','『국어』 122쪽 6번이에요. 「친구가 대답하기 어려워할 만한 내용을 질문해야 토의가 잘 이루어질 수 있겠어.」는 알맞은 반응이에요.',ARRAY['K4-2-u3-X59']::text[],false,'{"seq":9,"concept":"K4-2-u3-C13","difficulty":2,"kind":"ox","stem":"『국어』 122쪽 6번이에요. 「친구가 대답하기 어려워할 만한 내용을 질문해야 토의가 잘 이루어질 수 있겠어.」는 알맞은 반응이에요.","answer":"X","reason_options":[{"t":"질문은 친구의 의견과 이유를 더 잘 알고 더 나은 의견을 만들려고 하는 거예요.","correct":true},{"t":"대답하기 어려운 질문을 할수록 토의를 잘하는 거예요.","mis":"K4-2-u3-X59"}],"mis":"K4-2-u3-X59","explanation":["수희는 궁금하거나 더 알고 싶은 부분을 물으라고 했어요.","친구를 곤란하게 하려는 질문은 도움이 되지 않아요.","그래서 이 반응에는 ○ 표를 하지 않아요."],"asset":{"type":"speech","turns":[{"who":"주헌","text":"“토의할 때에는 어떻게 질문하는 게 좋을까?”"},{"who":"수희","text":"“친구가 말한 내용 가운데에서 궁금하거나 더 알고 싶은 부분을 물어야 해.”"},{"who":"주헌","text":"“그러면 의견뿐만 아니라 의견을 낸 이유에 대해서도 물어도 돼?”"},{"who":"수희","text":"“맞아! 그리고 질문할 때에는 친구의 기분이 나쁘지 않게 배려하며 말해야 해.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_basic#10','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C14',3,'mc','auto','「우현이네 학급 토의 시간」에서 의견을 실천했을 때의 단점을 물은 질문은 무엇인가요?',ARRAY['K4-2-u3-X59','K4-2-u3-X15']::text[],false,'{"seq":10,"concept":"K4-2-u3-C14","difficulty":3,"kind":"mc","stem":"「우현이네 학급 토의 시간」에서 의견을 실천했을 때의 단점을 물은 질문은 무엇인가요?","options":[{"t":"“그런데 복도 가운데에 표지판이 있으면 거기에 부딪히는 친구도 있지 않을까요?”","correct":true},{"t":"“표지판은 무슨 색인가요?”","mis":"K4-2-u3-X59"},{"t":"“표지판을 놓으면 어떤 결과가 나타날까요?”","mis":"K4-2-u3-X15"},{"t":"“표지판은 언제 누가 놓으면 좋을까요?”","mis":"K4-2-u3-X15"}],"explanation":["민준이는 표지판에 부딪힐 수 있다는 점을 물었어요.","이것은 의견을 실천했을 때 생길 수 있는 단점이에요.","결과·단점·실천 방법을 묻는 질문은 의견을 더 낫게 만들어요."],"asset":{"type":"speech","turns":[{"who":"김규빈","text":"“복도 가운데에 표지판을 놓아두면 좋겠습니다. 왜냐하면 표지판이 복도 가운데에 있으면 옆으로 피해 한쪽으로만 다니게 할 수 있기 때문입니다.”"},{"who":"박민준","text":"“그런데 복도 가운데에 표지판이 있으면 거기에 부딪히는 친구도 있지 않을까요?”"},{"who":"정우현","text":"“복도 벽에 뛰어다니지 말라는 안내문을 붙이면 좋겠습니다. 왜냐하면 학생들이 안내문을 보면서 다시 한번 뛰어다니면 안 된다고 생각할 수 있기 때문입니다.”"},{"who":"최윤희","text":"“좋은 의견입니다. 그런데 안내문을 벽에 붙여 놓으면 복도를 다닐 때 잘 안 보일 수도 있지 않을까요?”"},{"who":"정우현","text":"“안내문을 조금 입체적으로 만들어 보면 어떨까요? 그러면 복도를 다닐 때 잘 볼 수 있을 것 같습니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_challenge#1','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C7',2,'mc','auto','『국어』 115쪽 3번 글이에요. 글쓴이 임다솜의 의견은 무엇인가요?',ARRAY['K4-2-u3-X06']::text[],false,'{"seq":1,"concept":"K4-2-u3-C7","difficulty":2,"kind":"mc","stem":"『국어』 115쪽 3번 글이에요. 글쓴이 임다솜의 의견은 무엇인가요?","options":[{"t":"규칙을 정해서 꼭 필요할 때만 휴대 전화를 사용하자","correct":true},{"t":"등하굣길에 휴대 전화를 사용하는 친구가 많다","mis":"K4-2-u3-X06"},{"t":"주변을 신경 쓰지 못해 사고가 날 수 있다","mis":"K4-2-u3-X06"},{"t":"휴대 전화를 학교에 아예 가져오지 말자","mis":"K4-2-u3-X06"}],"explanation":["‘……사용합시다!’처럼 바라는 것을 내놓는 문장에 의견이 있어요.","휴대 전화를 쓰는 친구가 많다는 것은 문제 상황이에요.","사고가 날 수 있다는 것은 문제 때문에 생기는 일이에요."],"asset":{"type":"passage","lines":["○○초등학교 학생 여러분, 안녕하세요? 저는 4학년 임다솜이라고 합니다.","요즘 친구들과 함께 있을 때나 등하굣길에 휴대 전화를 사용하는 친구가 많습니다.","그런데 휴대 전화를 너무 많이 사용하면 친구들끼리 이야기하는 시간이 줄고,","주변을 신경 쓰지 못해 사고가 날 수 있습니다.","규칙을 정해서 꼭 필요할 때만 휴대 전화를 사용합시다!","그러면 휴대 전화 화면을 보는 대신에 친구와 대화할 수 있고,","걸을 때도 주변을 살피며 안전하게 이동할 수 있습니다.","더 즐겁고 안전한 학교생활을 위해 함께 노력하면 좋겠습니다. 감사합니다."],"title":"「휴대 전화는 꼭 필요할 때만 사용합시다」 — 『국어』 115쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_challenge#2','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C6',2,'mc','auto','『국어』 114쪽 2번 대화예요. 친구들이 제안하는 글을 쓰려는 까닭은 무엇인가요?',ARRAY['K4-2-u3-X05','K4-2-u3-X04']::text[],false,'{"seq":2,"concept":"K4-2-u3-C6","difficulty":2,"kind":"mc","stem":"『국어』 114쪽 2번 대화예요. 친구들이 제안하는 글을 쓰려는 까닭은 무엇인가요?","options":[{"t":"토의에서 결정한 내용을 우리 학교 학생들에게도 알리려고","correct":true},{"t":"토의를 다시 하지 않으려고","mis":"K4-2-u3-X05"},{"t":"토의에서 결정한 내용을 비밀로 하려고","mis":"K4-2-u3-X05"},{"t":"문제가 생기면 언제나 글부터 써야 해서","mis":"K4-2-u3-X04"}],"explanation":["친구들은 지난번 토의에서 결정한 내용을 알리고 싶어 해요.","학교 신문이나 학교 누리집에 제안하는 글을 쓰자고 했어요.","토의와 제안하는 글은 이렇게 이어질 수 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“지난번 토의에서 결정한 내용을 우리 학교 학생들에게도 알리자.”"},{"who":"친구 2","text":"“학교 신문에 제안하는 글을 써서 알리면 어떨까?”"},{"who":"친구 3","text":"“오늘도 등굣길에 휴대 전화를 보면서 길을 건너는 학생을 봤어.”"},{"who":"친구 4","text":"“선생님과 상의해 학교 누리집에 올려도 좋을 것 같아.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_challenge#3','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C6',3,'error','auto','세 친구가 토의와 제안하는 글에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X04','K4-2-u3-X05']::text[],false,'{"seq":3,"concept":"K4-2-u3-C6","difficulty":3,"kind":"error","stem":"세 친구가 토의와 제안하는 글에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"연서: 문제가 생기면 토의는 건너뛰고 무조건 제안하는 글부터 써야 해.","correct":true,"mis_target":"K4-2-u3-X04"},{"t":"도윤: 토의에서 결정한 내용을 많은 사람에게 알리려고 제안하는 글을 쓸 수도 있어.","mis":"K4-2-u3-X05"},{"t":"하은: 토의, 안내문, 캠페인처럼 여러 방법 가운데 상황에 맞는 것을 고르면 돼.","mis":"K4-2-u3-X04"}],"explanation":["토의와 제안하는 글 모두 문제를 해결하려고 고를 수 있는 방법이에요.","토의에서 결정한 내용을 제안하는 글로 알릴 수도 있어요.","무조건 제안하는 글부터 써야 하는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_challenge#4','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C5',3,'mc','auto','임다솜이 115쪽 글에서 한 일처럼, 어떤 일에 대해 의견을 내놓는 것을 가리키는 말과 그 뜻을 바르게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u3-X57']::text[],false,'{"seq":4,"concept":"K4-2-u3-C5","difficulty":3,"kind":"mc","stem":"임다솜이 115쪽 글에서 한 일처럼, 어떤 일에 대해 의견을 내놓는 것을 가리키는 말과 그 뜻을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"제안 — 어떤 일에 대해 의견을 내놓는 것","correct":true},{"t":"명령 — 무조건 하라고 시키는 것","mis":"K4-2-u3-X57"},{"t":"불평 — 마음에 들지 않는 점만 늘어놓는 것","mis":"K4-2-u3-X57"},{"t":"금지 — 규칙으로 하지 못하게 막는 것","mis":"K4-2-u3-X57"}],"explanation":["임다솜은 휴대 전화 사용 규칙을 정하자는 의견을 내놓았어요.","이렇게 의견을 내놓는 것을 제안이라고 해요.","제안은 시키거나 막기만 하는 것과 달라요."],"asset":{"type":"passage","lines":["○○초등학교 학생 여러분, 안녕하세요? 저는 4학년 임다솜이라고 합니다.","요즘 친구들과 함께 있을 때나 등하굣길에 휴대 전화를 사용하는 친구가 많습니다.","그런데 휴대 전화를 너무 많이 사용하면 친구들끼리 이야기하는 시간이 줄고,","주변을 신경 쓰지 못해 사고가 날 수 있습니다.","규칙을 정해서 꼭 필요할 때만 휴대 전화를 사용합시다!","그러면 휴대 전화 화면을 보는 대신에 친구와 대화할 수 있고,","걸을 때도 주변을 살피며 안전하게 이동할 수 있습니다.","더 즐겁고 안전한 학교생활을 위해 함께 노력하면 좋겠습니다. 감사합니다."],"title":"「휴대 전화는 꼭 필요할 때만 사용합시다」 — 『국어』 115쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_challenge#5','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C10',3,'mc','auto','『국어』 121쪽 4번 장면 ㉰예요. 마음속으로 생각하는 친구가 고쳐야 할 점은 무엇인가요?',ARRAY['K4-2-u3-X60','K4-2-u3-X12']::text[],false,'{"seq":5,"concept":"K4-2-u3-C10","difficulty":3,"kind":"mc","stem":"『국어』 121쪽 4번 장면 ㉰예요. 마음속으로 생각하는 친구가 고쳐야 할 점은 무엇인가요?","options":[{"t":"누가 낸 의견인지가 아니라 토의 주제에 알맞은 의견인지 판단하며 듣는다","correct":true},{"t":"친한 친구의 의견은 끝까지 편들어 준다","mis":"K4-2-u3-X60"},{"t":"주제에 맞지 않는 의견을 낸 친구에게 다시는 말하지 말라고 한다","mis":"K4-2-u3-X12"},{"t":"잘 모르는 친구의 의견만 따져 본다","mis":"K4-2-u3-X60"}],"explanation":["이 친구는 주제와 맞지 않아도 친한 친구의 의견이라 좋다고 하려 해요.","의견을 모을 때에는 주제에 알맞은지 판단하며 들어야 해요.","친한지 아닌지는 의견을 고르는 기준이 아니에요."],"asset":{"type":"passage","lines":["㉮ “쉬는 시간을 늘리는 방법에 대하여 이야기해 보면 어떨까요?”","(생각) 우리가 쉬는 시간을 늘리는 게 가능한 일일까?","㉯ “내 의견은 정말 완벽해! 장점밖에 없어.”","㉰ “제 의견은…….”","(생각) 토의 주제와 맞지 않지만 친한 친구가 낸 의견이니 좋다고 해야겠어.","㉱ “무조건 실천하기 쉬운 의견을 고릅시다.”","보기: 단점 · 판단 · 기준 · 해결"],"title":"『국어』 121쪽 4번 — 토의할 때 주의할 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_challenge#6','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C10',3,'mc','auto','『국어』 121쪽 4번 장면 ㉱의 말 「무조건 실천하기 쉬운 의견을 고릅시다.」를 바르게 고친 것은 무엇인가요?',ARRAY['K4-2-u3-X08','K4-2-u3-X20','K4-2-u3-X18']::text[],false,'{"seq":6,"concept":"K4-2-u3-C10","difficulty":3,"kind":"mc","stem":"『국어』 121쪽 4번 장면 ㉱의 말 「무조건 실천하기 쉬운 의견을 고릅시다.」를 바르게 고친 것은 무엇인가요?","options":[{"t":"해결에 도움이 되는지, 실천할 수 있는지 같은 여러 기준에 가장 알맞은 의견을 고릅시다.","correct":true},{"t":"가장 먼저 나온 의견을 고릅시다.","mis":"K4-2-u3-X08"},{"t":"가위바위보로 빠르게 고릅시다.","mis":"K4-2-u3-X20"},{"t":"실천하기 쉬운 의견은 모두 빼고 고릅시다.","mis":"K4-2-u3-X18"}],"explanation":["쉽기만 하고 문제를 풀지 못하면 알맞은 의견이 아니에요.","의견을 결정할 때에는 여러 가지 기준을 세워 견주어요.","쉬운 의견을 무조건 빼는 것도 알맞지 않아요."],"asset":{"type":"passage","lines":["㉮ “쉬는 시간을 늘리는 방법에 대하여 이야기해 보면 어떨까요?”","(생각) 우리가 쉬는 시간을 늘리는 게 가능한 일일까?","㉯ “내 의견은 정말 완벽해! 장점밖에 없어.”","㉰ “제 의견은…….”","(생각) 토의 주제와 맞지 않지만 친한 친구가 낸 의견이니 좋다고 해야겠어.","㉱ “무조건 실천하기 쉬운 의견을 고릅시다.”","보기: 단점 · 판단 · 기준 · 해결"],"title":"『국어』 121쪽 4번 — 토의할 때 주의할 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_challenge#7','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C11',3,'mc','auto','「우현이네 학급 토의 시간」에서 윤희의 질문을 받은 뒤 우현이의 의견은 어떻게 되었나요?',ARRAY['K4-2-u3-X11','K4-2-u3-X23']::text[],false,'{"seq":7,"concept":"K4-2-u3-C11","difficulty":3,"kind":"mc","stem":"「우현이네 학급 토의 시간」에서 윤희의 질문을 받은 뒤 우현이의 의견은 어떻게 되었나요?","options":[{"t":"벽에 붙이는 안내문을 입체적으로 만들자는, 더 잘 보이는 의견으로 다듬어졌다","correct":true},{"t":"우현이가 자기 의견을 포기했다","mis":"K4-2-u3-X11"},{"t":"질문 때문에 의견이 처음보다 나빠졌다","mis":"K4-2-u3-X23"},{"t":"윤희의 의견으로 바뀌었다","mis":"K4-2-u3-X11"}],"explanation":["윤희는 안내문이 잘 안 보일 수 있다고 물었어요.","우현이는 안내문을 입체적으로 만들자고 답했어요.","질문 덕분에 의견이 더 구체적이고 나아졌어요."],"asset":{"type":"speech","turns":[{"who":"김규빈","text":"“복도 가운데에 표지판을 놓아두면 좋겠습니다. 왜냐하면 표지판이 복도 가운데에 있으면 옆으로 피해 한쪽으로만 다니게 할 수 있기 때문입니다.”"},{"who":"박민준","text":"“그런데 복도 가운데에 표지판이 있으면 거기에 부딪히는 친구도 있지 않을까요?”"},{"who":"정우현","text":"“복도 벽에 뛰어다니지 말라는 안내문을 붙이면 좋겠습니다. 왜냐하면 학생들이 안내문을 보면서 다시 한번 뛰어다니면 안 된다고 생각할 수 있기 때문입니다.”"},{"who":"최윤희","text":"“좋은 의견입니다. 그런데 안내문을 벽에 붙여 놓으면 복도를 다닐 때 잘 안 보일 수도 있지 않을까요?”"},{"who":"정우현","text":"“안내문을 조금 입체적으로 만들어 보면 어떨까요? 그러면 복도를 다닐 때 잘 볼 수 있을 것 같습니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_challenge#8','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C14',4,'essay','teacher','『국어』 123쪽 7번이에요. 짝의 의견에 대해 의견을 실천했을 때의 결과, 단점, 구체적인 실천 방법을 묻는 질문을 하나씩 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u3-C14","difficulty":4,"kind":"essay","stem":"『국어』 123쪽 7번이에요. 짝의 의견에 대해 의견을 실천했을 때의 결과, 단점, 구체적인 실천 방법을 묻는 질문을 하나씩 쓰세요.","answer_guide":{"answer":"예: 결과 — 복도 안전 지킴이를 정하면 무엇이 달라질까요? / 단점 — 지킴이가 경고하면 기분 나빠하는 친구가 있지 않을까요? / 실천 방법 — 지킴이는 어떻게 뽑고 언제 활동하면 좋을까요?","scoring_points":["결과(달라지는 점·장점)를 묻는 질문을 썼는가","단점이나 생길 수 있는 문제를 묻는 질문을 썼는가","언제·누가·어떻게 실천할지 묻는 질문을 썼는가"]},"explanation":["토의의 질문은 더 나은 의견을 만들려고 해요.","단순한 사실이나 낱말 뜻보다 결과·단점·실천 방법을 물어요.","질문할 때에는 친구의 기분을 배려하는 말을 함께 써요."],"asset":{"type":"speech","turns":[{"who":"짝 의견","text":"“복도 안전 지킴이를 정하면 좋겠습니다.”"},{"who":"그 이유","text":"“복도에서 뛰어다니는 친구가 있으면 경고하거나 멈추게 할 수 있기 때문입니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_challenge#9','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C13',4,'mc','auto','다음 의견과 이유에 대해 의견과 이유가 적절한지 확인하는 질문으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X13','K4-2-u3-X59','K4-2-u3-X14']::text[],false,'{"seq":9,"concept":"K4-2-u3-C13","difficulty":4,"kind":"mc","stem":"다음 의견과 이유에 대해 의견과 이유가 적절한지 확인하는 질문으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“교실에서 피구를 하면 위험하지 않을까요? 교실 말고 다른 장소에서 하면 어떨까요?”","correct":true},{"t":"“좋은 의견이에요. 그런데 피구공은 무슨 색인가요?”","mis":"K4-2-u3-X13"},{"t":"“피구라는 낱말은 무슨 뜻인가요?”","mis":"K4-2-u3-X59"},{"t":"“질문 수를 채워야 하니 열 개만 더 물어볼게요.”","mis":"K4-2-u3-X14"}],"explanation":["교실은 좁아서 피구를 하면 다칠 수 있어요.","이 질문은 의견이 알맞은지 따져 보게 해요.","공손한 말을 붙여도 내용이 의견과 상관없으면 좋은 질문이 아니에요."],"asset":{"type":"speech","turns":[{"who":"토의 주제","text":"학급의 날에 무엇을 하면 좋을까요?"},{"who":"의견","text":"“학급의 날에 교실에서 피구를 하면 좋겠습니다.”"},{"who":"이유","text":"“피구는 우리 학급 친구들이 가장 좋아하는 활동이기 때문입니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L02_challenge#10','kor',4,2,'u3','L02','tb_g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C12',4,'essay','teacher','「우현이네 학급 토의 시간」에서 민준이가 한 질문을 윤희처럼 상대의 기분을 고려한 질문으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u3-C12","difficulty":4,"kind":"essay","stem":"「우현이네 학급 토의 시간」에서 민준이가 한 질문을 윤희처럼 상대의 기분을 고려한 질문으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 규빈 학생의 의견처럼 표지판을 놓으면 한쪽으로 다니게 할 수 있어 좋겠습니다. 그런데 복도 가운데에 표지판이 있으면 거기에 부딪히는 친구도 있지 않을까요?","scoring_points":["먼저 친구의 의견을 존중하거나 공감하는 말을 썼는가","표지판에 부딪힐 수 있다는 궁금한 점(단점)을 그대로 물었는가","공손한 말투로 썼는가"]},"explanation":["윤희는 “좋은 의견입니다.”라고 공감한 뒤 질문했어요.","민준이의 질문 내용은 의견을 따져 보는 좋은 내용이에요.","내용은 살리고 말투에 존중을 더하면 돼요."],"asset":{"type":"speech","turns":[{"who":"김규빈","text":"“복도 가운데에 표지판을 놓아두면 좋겠습니다. 왜냐하면 표지판이 복도 가운데에 있으면 옆으로 피해 한쪽으로만 다니게 할 수 있기 때문입니다.”"},{"who":"박민준","text":"“그런데 복도 가운데에 표지판이 있으면 거기에 부딪히는 친구도 있지 않을까요?”"},{"who":"정우현","text":"“복도 벽에 뛰어다니지 말라는 안내문을 붙이면 좋겠습니다. 왜냐하면 학생들이 안내문을 보면서 다시 한번 뛰어다니면 안 된다고 생각할 수 있기 때문입니다.”"},{"who":"최윤희","text":"“좋은 의견입니다. 그런데 안내문을 벽에 붙여 놓으면 복도를 다닐 때 잘 안 보일 수도 있지 않을까요?”"},{"who":"정우현","text":"“안내문을 조금 입체적으로 만들어 보면 어떨까요? 그러면 복도를 다닐 때 잘 볼 수 있을 것 같습니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_basic#1','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C15',1,'mc','auto','『국어』 124쪽 (1)이에요. 그림 ㉮에서 볼 수 있는 문제 상황은 무엇인가요?',ARRAY['K4-2-u3-X25']::text[],false,'{"seq":1,"concept":"K4-2-u3-C15","difficulty":1,"kind":"mc","stem":"『국어』 124쪽 (1)이에요. 그림 ㉮에서 볼 수 있는 문제 상황은 무엇인가요?","options":[{"t":"주인이 찾아가지 않은 물건이 분실물 보관함에 잔뜩 쌓여 있다","correct":true},{"t":"복도 바닥에 쓰레기가 떨어져 있다","mis":"K4-2-u3-X25"},{"t":"놀이터 기구에 낙서가 되어 있다","mis":"K4-2-u3-X25"},{"t":"교실 창문이 깨져 있다","mis":"K4-2-u3-X25"}],"explanation":["그림 ㉮에는 ‘분실물 찾아가세요.’라는 글이 붙어 있어요.","가방, 물병, 신발이 주인을 기다리며 쌓여 있어요.","복도 쓰레기는 ㉯, 놀이터 낙서는 ㉰의 문제 상황이에요."],"asset":{"type":"passage","lines":["㉮ [그림] ‘분실물 찾아가세요.’ — 가방·물병·신발·필통이 보관함에 잔뜩 쌓여 있다.","㉯ [그림] 복도 바닥 곳곳에 휴지와 과자 껍질 같은 쓰레기가 떨어져 있다.","㉰ [그림] 놀이터 미끄럼틀과 시소에 낙서가 가득하다."],"title":"『국어』 124쪽 — 학교나 학교 주변의 문제 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_basic#2','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C15',1,'mc','auto','『국어』 124쪽 (2)예요. 그림 ㉮의 문제 상황으로 토의 주제를 만들 때 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X09','K4-2-u3-X02']::text[],false,'{"seq":2,"concept":"K4-2-u3-C15","difficulty":1,"kind":"mc","stem":"『국어』 124쪽 (2)예요. 그림 ㉮의 문제 상황으로 토의 주제를 만들 때 가장 알맞은 것은 무엇인가요?","options":[{"t":"이름이 쓰여 있지 않은 물건의 주인을 어떻게 찾아 주면 좋을까?","correct":true},{"t":"우리 학교 건물을 새로 지으려면 어떻게 할까?","mis":"K4-2-u3-X09"},{"t":"내 필통을 무슨 색으로 살까?","mis":"K4-2-u3-X02"},{"t":"분실물 보관함은 몇 칸일까?","mis":"K4-2-u3-X02"}],"explanation":["토의 주제는 모두와 관련 있고 여러 의견이 나올 수 있어야 해요.","우리가 해결할 수 있는 문제여야 해요.","물건 주인을 찾아 주는 방법은 여러 의견이 나올 수 있어요."],"asset":{"type":"passage","lines":["㉮ [그림] ‘분실물 찾아가세요.’ — 가방·물병·신발·필통이 보관함에 잔뜩 쌓여 있다.","㉯ [그림] 복도 바닥 곳곳에 휴지와 과자 껍질 같은 쓰레기가 떨어져 있다.","㉰ [그림] 놀이터 미끄럼틀과 시소에 낙서가 가득하다."],"title":"『국어』 124쪽 — 학교나 학교 주변의 문제 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_basic#3','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C16',1,'mc','auto','『국어』 125쪽 (1)이에요. 다음 가운데 ‘문제가 우리에게 주는 영향’에 해당하는 것은 무엇인가요?',ARRAY['K4-2-u3-X16']::text[],false,'{"seq":3,"concept":"K4-2-u3-C16","difficulty":1,"kind":"mc","stem":"『국어』 125쪽 (1)이에요. 다음 가운데 ‘문제가 우리에게 주는 영향’에 해당하는 것은 무엇인가요?","options":[{"t":"물건 주인을 몰라 함부로 버릴 수 없어서 운동장과 강당이 지저분해 보인다","correct":true},{"t":"물건에 이름을 쓰지 않았다","mis":"K4-2-u3-X16"},{"t":"자기 물건을 소중히 여기지 않는다","mis":"K4-2-u3-X16"},{"t":"분실물 찾기 게시판을 만든다","mis":"K4-2-u3-X16"}],"explanation":["이름을 쓰지 않은 것은 문제가 생긴 까닭이에요.","그 때문에 운동장과 강당이 지저분해 보이는 것이 영향이에요.","게시판을 만드는 것은 해결을 위한 의견이에요."],"asset":{"type":"passage","lines":["토의 주제 — 운동장이나 강당에 오랫동안 버려져 있는 물건의 주인을 어떻게 찾아 주면 좋을까?","문제가 생긴 까닭 — 물건에 이름을 쓰지 않았기 때문입니다. / 자기 물건을 소중히 여기지 않기 때문입니다.","문제가 우리에게 주는 영향 — 물건 주인이 누구인지 모르기 때문에","함부로 버릴 수 없어서 운동장과 강당이 지저분해 보입니다."],"title":"『국어』 125쪽 — 해결이 필요한 문제 상황 정리하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_basic#4','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C17',1,'ox','auto','『국어』 126쪽 (2)예요. 의견을 마련할 때에는 주제에 알맞은지, 우리 모두가 실천할 수 있는지, 이유가 적절한지, 단점도 생각했는지 살펴요.',ARRAY['K4-2-u3-X10']::text[],false,'{"seq":4,"concept":"K4-2-u3-C17","difficulty":1,"kind":"ox","stem":"『국어』 126쪽 (2)예요. 의견을 마련할 때에는 주제에 알맞은지, 우리 모두가 실천할 수 있는지, 이유가 적절한지, 단점도 생각했는지 살펴요.","answer":"O","reason_options":[{"t":"네 가지를 살펴 의견판에 의견과 이유를 쓰면 좋은 의견을 마련할 수 있어요.","correct":true},{"t":"내 의견의 장점만 생각하면 충분해요.","mis":"K4-2-u3-X10"}],"mis":"K4-2-u3-X10","explanation":["『국어』 126쪽에는 의견을 마련할 때 생각할 점 네 가지가 있어요.","주제·실천·이유·단점을 모두 살펴요.","장점만 보면 실천할 때 문제가 생길 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_basic#5','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C18',2,'mc','auto','『국어』 121쪽 장면 ㉱의 「무조건 실천하기 쉬운 의견을 고릅시다.」라는 말이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K4-2-u3-X17','K4-2-u3-X18']::text[],false,'{"seq":5,"concept":"K4-2-u3-C18","difficulty":2,"kind":"mc","stem":"『국어』 121쪽 장면 ㉱의 「무조건 실천하기 쉬운 의견을 고릅시다.」라는 말이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"쉬워도 문제를 해결하는 데 도움이 되지 않으면 알맞은 의견이 아니기 때문","correct":true},{"t":"쉬운 의견은 언제나 가장 좋은 의견이기 때문","mis":"K4-2-u3-X17"},{"t":"쉬운 의견은 모두 버려야 하기 때문","mis":"K4-2-u3-X18"},{"t":"의견은 어려울수록 좋기 때문","mis":"K4-2-u3-X18"}],"explanation":["실천하기 쉬운지는 중요한 기준 가운데 하나예요.","하지만 문제를 풀지 못하면 쉬워도 소용없어요.","쉬운지와 해결되는지를 함께 따져요."],"asset":{"type":"passage","lines":["㉮ “쉬는 시간을 늘리는 방법에 대하여 이야기해 보면 어떨까요?”","(생각) 우리가 쉬는 시간을 늘리는 게 가능한 일일까?","㉯ “내 의견은 정말 완벽해! 장점밖에 없어.”","㉰ “제 의견은…….”","(생각) 토의 주제와 맞지 않지만 친한 친구가 낸 의견이니 좋다고 해야겠어.","㉱ “무조건 실천하기 쉬운 의견을 고릅시다.”","보기: 단점 · 판단 · 기준 · 해결"],"title":"『국어』 121쪽 4번 — 토의할 때 주의할 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_basic#6','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C19',2,'mc','auto','『국어』 126쪽 말하기 (2)예요. 친구의 의견 「물건 찾아 주기 방송을 하자」에 대해 할 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X12','K4-2-u3-X59','K4-2-u3-X03']::text[],false,'{"seq":6,"concept":"K4-2-u3-C19","difficulty":2,"kind":"mc","stem":"『국어』 126쪽 말하기 (2)예요. 친구의 의견 「물건 찾아 주기 방송을 하자」에 대해 할 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"“물건 찾아 주기 방송은 언제 누가 하나요?”","correct":true},{"t":"“방송을 하자니, 그건 틀린 생각이에요.”","mis":"K4-2-u3-X12"},{"t":"“방송실 문은 무슨 색인가요?”","mis":"K4-2-u3-X59"},{"t":"“네 의견 말고 내 의견으로 하자.”","mis":"K4-2-u3-X03"}],"explanation":["질문은 의견을 실천하는 방법이나 어려움을 묻는 것이 좋아요.","언제 누가 할지 물으면 의견이 더 구체적이 돼요.","깎아내리거나 상관없는 것을 묻지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_basic#7','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C20',2,'mc','auto','친구가 “물건의 주인이 아닌 친구가 물건을 가져가면 어떻게 하나요?”라고 물었어요. 의견을 낸 친구의 태도로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X23','K4-2-u3-X12']::text[],false,'{"seq":7,"concept":"K4-2-u3-C20","difficulty":2,"kind":"mc","stem":"친구가 “물건의 주인이 아닌 친구가 물건을 가져가면 어떻게 하나요?”라고 물었어요. 의견을 낸 친구의 태도로 가장 알맞은 것은 무엇인가요?","options":[{"t":"질문을 생각해 보고 물건을 찾아갈 때 이름을 확인하는 방법을 덧붙여 의견을 다듬는다","correct":true},{"t":"질문을 받았으니 내 의견이 진 것이라고 생각한다","mis":"K4-2-u3-X23"},{"t":"질문한 친구에게 화를 낸다","mis":"K4-2-u3-X12"},{"t":"못 들은 척하고 의견을 그대로 우긴다","mis":"K4-2-u3-X23"}],"explanation":["『국어』 126쪽 질문 예시예요.","질문은 의견의 빈틈을 알려 주는 고마운 말이에요.","답을 생각하며 의견을 고치면 더 나은 의견이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_basic#8','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C21',2,'mc','auto','『국어』 127쪽 (4)예요. 모둠에서 의견을 결정하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X61','K4-2-u3-X19','K4-2-u3-X20']::text[],false,'{"seq":8,"concept":"K4-2-u3-C21","difficulty":2,"kind":"mc","stem":"『국어』 127쪽 (4)예요. 모둠에서 의견을 결정하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"기준에 비추어 하나를 고르거나, 여러 의견의 좋은 점을 모아 새로운 의견을 만든다","correct":true},{"t":"반드시 한 가지 의견만 골라야 하고 의견을 합치면 안 된다","mis":"K4-2-u3-X61"},{"t":"모든 의견을 다 합치면 언제나 가장 좋은 의견이 된다","mis":"K4-2-u3-X19"},{"t":"가위바위보로 이긴 친구의 의견으로 정한다","mis":"K4-2-u3-X20"}],"explanation":["“꼭 한 가지 의견으로 결정할 필요는 없어요.”라고 했어요.","“여러 의견을 모아 새로운 의견을 만들 수도 있어요.”라고도 했어요.","어떻게 하든 문제 해결에 알맞은지 기준으로 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_basic#9','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C23',2,'mc','auto','『국어』 127쪽 (5)예요. 다음 가운데 구체적인 실천 계획은 무엇인가요?',ARRAY['K4-2-u3-X21']::text[],false,'{"seq":9,"concept":"K4-2-u3-C23","difficulty":2,"kind":"mc","stem":"『국어』 127쪽 (5)예요. 다음 가운데 구체적인 실천 계획은 무엇인가요?","options":[{"t":"쉬는 시간을 이용해서 일주일 동안 분실물 찾기 게시판을 만들고 학교 현관에 놓는다.","correct":true},{"t":"분실물을 줄이도록 열심히 노력한다.","mis":"K4-2-u3-X21"},{"t":"언젠가 게시판을 만들어 본다.","mis":"K4-2-u3-X21"},{"t":"분실물 찾기 게시판이 생기면 좋겠다.","mis":"K4-2-u3-X21"}],"explanation":["실천 계획에는 언제, 무엇을, 어디에서 할지가 들어가야 해요.","‘쉬는 시간에, 일주일 동안, 현관에’처럼 분명해요.","‘열심히’, ‘언젠가’는 실천 계획이 아니에요."],"asset":{"type":"passage","lines":["결정한 의견 — 분실물 찾기 게시판 만들기","결정한 까닭 — 모든 학생이 자기가 잃어버린 물건이 맞는지 확인할 수 있기 때문이다.","실천 계획 — 쉬는 시간을 이용해서 일주일 동안 분실물 찾기 게시판을 만들고","학교 현관에 놓는다."],"title":"『국어』 127쪽 — 토의에서 결정한 의견 정리하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_basic#10','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C24',3,'mc','auto','『국어활동』 39쪽 「더 알아보기」예요. 토의에서 결정한 의견이 내 의견과 다를 때 어떻게 해야 하나요?',ARRAY['K4-2-u3-X58','K4-2-u3-X03']::text[],false,'{"seq":10,"concept":"K4-2-u3-C24","difficulty":3,"kind":"mc","stem":"『국어활동』 39쪽 「더 알아보기」예요. 토의에서 결정한 의견이 내 의견과 다를 때 어떻게 해야 하나요?","options":[{"t":"여러 사람이 생각을 모은 결과이므로 적극적으로 실천한다","correct":true},{"t":"내 의견이 아니니 실천하지 않는다","mis":"K4-2-u3-X58"},{"t":"목소리를 높여 내 의견으로 다시 바꾼다","mis":"K4-2-u3-X03"},{"t":"결정을 무르자고 계속 조른다","mis":"K4-2-u3-X58"}],"explanation":["토의의 결정은 여러 사람이 함께 생각을 모은 결과예요.","내 의견과 달라도 함께 실천해야 해요.","그래야 실제로 문제가 해결돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_challenge#1','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C16',2,'mc','auto','『국어』 124쪽 그림 ㉯(복도 바닥의 쓰레기)의 문제 상황을 정리할 때 ‘문제가 생긴 까닭’으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X16','K4-2-u3-X25']::text[],false,'{"seq":1,"concept":"K4-2-u3-C16","difficulty":2,"kind":"mc","stem":"『국어』 124쪽 그림 ㉯(복도 바닥의 쓰레기)의 문제 상황을 정리할 때 ‘문제가 생긴 까닭’으로 알맞은 것은 무엇인가요?","options":[{"t":"쓰레기를 쓰레기통에 버리지 않고 바닥에 버리는 친구들이 있다","correct":true},{"t":"복도가 지저분해 보이고 미끄러질 수 있다","mis":"K4-2-u3-X16"},{"t":"쓰레기 줍기 당번을 정하자","mis":"K4-2-u3-X16"},{"t":"복도에 창문이 많다","mis":"K4-2-u3-X25"}],"explanation":["까닭은 「왜 그런 문제가 생겼나」에 대한 답이에요.","복도가 지저분해 보이는 것은 문제 때문에 생기는 영향이에요.","당번을 정하자는 것은 해결을 위한 의견이에요."],"asset":{"type":"passage","lines":["㉮ [그림] ‘분실물 찾아가세요.’ — 가방·물병·신발·필통이 보관함에 잔뜩 쌓여 있다.","㉯ [그림] 복도 바닥 곳곳에 휴지와 과자 껍질 같은 쓰레기가 떨어져 있다.","㉰ [그림] 놀이터 미끄럼틀과 시소에 낙서가 가득하다."],"title":"『국어』 124쪽 — 학교나 학교 주변의 문제 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_challenge#2','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C17',2,'ox','auto','『국어활동』 38쪽이에요. 소율이의 의견 「독도의 날 기념 피구 대회를 하면 어떨까요?」는 토의 주제에 알맞은 의견이에요.',ARRAY['K4-2-u3-X64']::text[],false,'{"seq":2,"concept":"K4-2-u3-C17","difficulty":2,"kind":"ox","stem":"『국어활동』 38쪽이에요. 소율이의 의견 「독도의 날 기념 피구 대회를 하면 어떨까요?」는 토의 주제에 알맞은 의견이에요.","answer":"X","reason_options":[{"t":"모두가 즐겁게 참여할 수 있어도 독도의 날을 기념하는 것과 관련이 없어 주제에 알맞지 않아요.","correct":true},{"t":"모두가 즐겁게 참여할 수 있으면 어떤 활동이든 주제에 알맞아요.","mis":"K4-2-u3-X64"}],"mis":"K4-2-u3-X64","explanation":["토의 주제는 독도의 날을 기념하는 활동을 정하는 것이에요.","피구 대회는 독도와 관련이 없어요.","의견은 먼저 주제와 관련 있는지 살펴야 해요."],"asset":{"type":"speech","turns":[{"who":"주제","text":"독도의 날을 기념하는 우리 반 활동 정하기"},{"who":"소율","text":"“독도의 날 기념 피구 대회를 하면 어떨까요? 모두가 즐겁게 참여할 수 있을 것 같습니다.”"},{"who":"규빈","text":"“독도의 날을 기념해 ‘독도’로 이행시 짓기 대회를 하면 좋겠습니다. 우리 반 모두가 쉽게 참여할 수 있지 않을까요?”"},{"who":"영우","text":"“독도를 소재로 노래를 만들어 보면 어떨까요? 만든 노래는 노래를 잘 부르는 친구가 대표로 불러 주면 좋겠습니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_challenge#3','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C17',3,'mc','auto','『국어활동』 38~39쪽이에요. 영우의 의견을 ‘우리 모두가 실천할 수 있는가’라는 기준으로 평가한 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X64','K4-2-u3-X17']::text[],false,'{"seq":3,"concept":"K4-2-u3-C17","difficulty":3,"kind":"mc","stem":"『국어활동』 38~39쪽이에요. 영우의 의견을 ‘우리 모두가 실천할 수 있는가’라는 기준으로 평가한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"우리 반에 노래를 만들 수 있는 친구가 없다면 실천하기 어렵다","correct":true},{"t":"독도와 관련이 없어 주제에 알맞지 않다","mis":"K4-2-u3-X64"},{"t":"노래는 누구나 쉽게 만들 수 있으니 문제없다","mis":"K4-2-u3-X17"},{"t":"대표가 부르면 되니 우리 반 모두가 참여하는 셈이다","mis":"K4-2-u3-X17"}],"explanation":["영우의 의견은 독도를 소재로 해서 주제에는 알맞아요.","하지만 노래를 만들 수 있어야 실천할 수 있어요.","대표만 부르면 모두가 참여하기도 어려워요."],"asset":{"type":"speech","turns":[{"who":"주제","text":"독도의 날을 기념하는 우리 반 활동 정하기"},{"who":"소율","text":"“독도의 날 기념 피구 대회를 하면 어떨까요? 모두가 즐겁게 참여할 수 있을 것 같습니다.”"},{"who":"규빈","text":"“독도의 날을 기념해 ‘독도’로 이행시 짓기 대회를 하면 좋겠습니다. 우리 반 모두가 쉽게 참여할 수 있지 않을까요?”"},{"who":"영우","text":"“독도를 소재로 노래를 만들어 보면 어떨까요? 만든 노래는 노래를 잘 부르는 친구가 대표로 불러 주면 좋겠습니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_challenge#4','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C21',3,'mc','auto','『국어활동』 39쪽 2번 (3)이에요. 세 친구의 의견 가운데 가장 적절한 의견과 그 까닭을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u3-X64','K4-2-u3-X17','K4-2-u3-X19']::text[],false,'{"seq":4,"concept":"K4-2-u3-C21","difficulty":3,"kind":"mc","stem":"『국어활동』 39쪽 2번 (3)이에요. 세 친구의 의견 가운데 가장 적절한 의견과 그 까닭을 바르게 말한 것은 무엇인가요?","options":[{"t":"규빈 — 독도의 날을 기념할 수 있으면서 모든 친구가 쉽게 참여할 수 있다","correct":true},{"t":"소율 — 피구 대회가 가장 재미있다","mis":"K4-2-u3-X64"},{"t":"영우 — 노래를 잘 부르는 친구가 대표로 부르면 된다","mis":"K4-2-u3-X17"},{"t":"세 의견을 모두 합치면 언제나 가장 좋다","mis":"K4-2-u3-X19"}],"explanation":["규빈이의 이행시 짓기는 주제에 알맞아요.","우리 반 모두가 쉽게 참여할 수 있어 실천할 수 있어요.","여러 기준에 비추어 가장 알맞은 의견을 골라요."],"asset":{"type":"speech","turns":[{"who":"주제","text":"독도의 날을 기념하는 우리 반 활동 정하기"},{"who":"소율","text":"“독도의 날 기념 피구 대회를 하면 어떨까요? 모두가 즐겁게 참여할 수 있을 것 같습니다.”"},{"who":"규빈","text":"“독도의 날을 기념해 ‘독도’로 이행시 짓기 대회를 하면 좋겠습니다. 우리 반 모두가 쉽게 참여할 수 있지 않을까요?”"},{"who":"영우","text":"“독도를 소재로 노래를 만들어 보면 어떨까요? 만든 노래는 노래를 잘 부르는 친구가 대표로 불러 주면 좋겠습니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_challenge#5','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C22',3,'mc','auto','모둠에서 「학교 주변 인도가 너무 좁아 오가는 사람들이 한 번에 지나가지 못한다」는 문제를 토의했어요. 인도를 넓히는 일은 우리 힘만으로 할 수 없을 때 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X22','K4-2-u3-X09']::text[],false,'{"seq":5,"concept":"K4-2-u3-C22","difficulty":3,"kind":"mc","stem":"모둠에서 「학교 주변 인도가 너무 좁아 오가는 사람들이 한 번에 지나가지 못한다」는 문제를 토의했어요. 인도를 넓히는 일은 우리 힘만으로 할 수 없을 때 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"그 일을 바꿀 수 있는 곳에 제안하는 글을 써서 알린다","correct":true},{"t":"우리끼리 길을 넓히는 공사를 한다","mis":"K4-2-u3-X22"},{"t":"우리가 할 수 없으니 그냥 포기한다","mis":"K4-2-u3-X22"},{"t":"토의를 처음부터 다시 한다","mis":"K4-2-u3-X09"}],"explanation":["우리 힘으로 할 수 없는 일도 있어요.","그럴 때에는 그 일을 바꿀 수 있는 곳에 제안할 수 있어요.","토의의 결과가 제안하는 글로 이어지는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_challenge#6','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C19',3,'error','auto','친구의 의견 「분실물 찾기 게시판 만들기」에 세 친구가 질문했어요. 알맞지 않은 질문을 한 친구는 누구인가요?',ARRAY['K4-2-u3-X12','K4-2-u3-X15','K4-2-u3-X11']::text[],false,'{"seq":6,"concept":"K4-2-u3-C19","difficulty":3,"kind":"error","stem":"친구의 의견 「분실물 찾기 게시판 만들기」에 세 친구가 질문했어요. 알맞지 않은 질문을 한 친구는 누구인가요?","options":[{"t":"수아: “그런 게시판은 아무도 안 볼 텐데 왜 그런 의견을 냈어요?”","correct":true,"mis_target":"K4-2-u3-X12"},{"t":"민호: “게시판은 어디에 놓으면 모두가 잘 볼 수 있을까요?”","mis":"K4-2-u3-X15"},{"t":"지아: “게시판을 만들면 물건 주인을 찾는 데 어떤 점이 좋아질까요?”","mis":"K4-2-u3-X11"}],"explanation":["질문은 친구의 기분을 헤아려 존중하는 말로 해요.","수아의 질문은 의견을 깎아내리고 있어요.","놓을 곳(실천 방법)이나 좋아지는 점(결과)을 묻는 것은 좋은 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_challenge#7','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C23',3,'mc','auto','「분실물이 줄어들도록 우리 모두 노력한다.」를 구체적인 실천 계획으로 고친 것은 무엇인가요?',ARRAY['K4-2-u3-X21']::text[],false,'{"seq":7,"concept":"K4-2-u3-C23","difficulty":3,"kind":"mc","stem":"「분실물이 줄어들도록 우리 모두 노력한다.」를 구체적인 실천 계획으로 고친 것은 무엇인가요?","options":[{"t":"매주 월요일 아침에 모둠별로 돌아가며 분실물 사진을 찍어 게시판에 붙인다.","correct":true},{"t":"분실물을 줄이려고 최선을 다한다.","mis":"K4-2-u3-X21"},{"t":"시간이 날 때 분실물을 살펴본다.","mis":"K4-2-u3-X21"},{"t":"분실물 찾기 게시판을 만들면 좋겠다고 생각한다.","mis":"K4-2-u3-X21"}],"explanation":["실천 계획에는 언제·누가·무엇을 할지가 들어가요.","‘매주 월요일 아침에, 모둠별로, 사진을 찍어 붙인다’처럼 써요.","‘최선을 다한다’는 다짐일 뿐 계획이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_challenge#8','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C17',4,'essay','teacher','『국어』 125쪽 토의 주제 「운동장이나 강당에 오랫동안 버려져 있는 물건의 주인을 어떻게 찾아 주면 좋을까?」에 대한 의견과 이유를 쓰고, 그 의견의 단점과 단점을 줄일 방법을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u3-C17","difficulty":4,"kind":"essay","stem":"『국어』 125쪽 토의 주제 「운동장이나 강당에 오랫동안 버려져 있는 물건의 주인을 어떻게 찾아 주면 좋을까?」에 대한 의견과 이유를 쓰고, 그 의견의 단점과 단점을 줄일 방법을 쓰세요.","answer_guide":{"answer":"예: 의견 — 분실물 찾기 게시판을 만들어 현관에 놓자. 이유 — 모든 학생이 자기가 잃어버린 물건인지 확인할 수 있기 때문이다. 단점 — 게시판을 아무도 챙기지 않으면 금방 지저분해진다. 줄일 방법 — 모둠별로 돌아가며 게시판을 정리한다.","scoring_points":["주제에 알맞은 의견을 썼는가","의견을 뒷받침하는 알맞은 이유를 썼는가","의견의 단점과 그것을 줄일 방법을 썼는가"]},"explanation":["『국어』 126쪽의 생각할 점 네 가지를 떠올려요.","이유는 의견을 실천했을 때 좋아지는 점으로 써요.","단점까지 생각하면 더 믿을 만한 의견이 돼요."],"asset":{"type":"passage","lines":["토의 주제 — 운동장이나 강당에 오랫동안 버려져 있는 물건의 주인을 어떻게 찾아 주면 좋을까?","문제가 생긴 까닭 — 물건에 이름을 쓰지 않았기 때문입니다. / 자기 물건을 소중히 여기지 않기 때문입니다.","문제가 우리에게 주는 영향 — 물건 주인이 누구인지 모르기 때문에","함부로 버릴 수 없어서 운동장과 강당이 지저분해 보입니다."],"title":"『국어』 125쪽 — 해결이 필요한 문제 상황 정리하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_challenge#9','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C24',4,'essay','teacher','토의 활동 동료 평가지 2번처럼, 규빈이의 의견 「복도 가운데에 표지판을 놓아두면 좋겠습니다.」를 평가해 「(  )의 의견은 문제 해결에 (적절하다. / 적절하지 않다.) 왜냐하면 …… 때문이다.」의 꼴로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u3-C24","difficulty":4,"kind":"essay","stem":"토의 활동 동료 평가지 2번처럼, 규빈이의 의견 「복도 가운데에 표지판을 놓아두면 좋겠습니다.」를 평가해 「(  )의 의견은 문제 해결에 (적절하다. / 적절하지 않다.) 왜냐하면 …… 때문이다.」의 꼴로 쓰세요.","answer_guide":{"answer":"예: 규빈이의 의견은 문제 해결에 적절하지 않다. 왜냐하면 친구들이 한쪽으로 다니게 할 수는 있지만, 복도 가운데 표지판에 부딪히는 친구가 생길 수 있어 단점이 크기 때문이다.","scoring_points":["적절한지 적절하지 않은지 하나를 골랐는가","주제·이유·실천·단점 기준 가운데 하나 이상을 들어 까닭을 썼는가","「왜냐하면 …… 때문이다」 꼴로 썼는가"]},"explanation":["동료 평가는 친구의 의견이 문제 해결에 도움이 될지 판단하는 거예요.","기준에 비추어 까닭을 들어 써요.","친한지 아닌지가 아니라 의견의 내용으로 평가해요."],"asset":{"type":"passage","lines":["1 토의 주제에 대한 친구의 의견과 그 이유를 써 봅시다.","2 기준을 생각하며 친구의 의견을 평가해 봅시다.","(주제에 알맞은가 · 이유가 적절한가 · 모두가 실천할 수 있는가 · 단점도 생각했는가)","(  )의 의견은 문제 해결에 (적절하다. / 적절하지 않다.) 왜냐하면 …… 때문이다.","3 적극적으로 참여했나요? · 말차례를 지켰나요? · 친구의 말을 경청했나요?"],"title":"토의 활동 동료 평가지 — 문제 해결을 위한 토의 참여 평가하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L04_challenge#10','kor',4,2,'u3','L04','tb_g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C20',4,'mc','auto','「우현이네 학급 토의 시간」 마지막에 선생님께서 하신 말씀에서 알 수 있는 것은 무엇인가요?',ARRAY['K4-2-u3-X23','K4-2-u3-X14','K4-2-u3-X01']::text[],false,'{"seq":10,"concept":"K4-2-u3-C20","difficulty":4,"kind":"mc","stem":"「우현이네 학급 토의 시간」 마지막에 선생님께서 하신 말씀에서 알 수 있는 것은 무엇인가요?","options":[{"t":"서로 질문하고 답하는 과정에서 의견이 더 구체적이고 나은 의견으로 자란다","correct":true},{"t":"질문을 받은 의견은 결정될 수 없다","mis":"K4-2-u3-X23"},{"t":"질문을 많이 받은 의견이 언제나 뽑힌다","mis":"K4-2-u3-X14"},{"t":"선생님이 의견을 정해 주셨다","mis":"K4-2-u3-X01"}],"explanation":["선생님은 “서로 질문하고 답하며 더 좋은 의견을 만들었습니다.”라고 하셨어요.","질문을 받은 우현이의 의견이 다듬어져 결정되었어요.","질문은 의견을 자라게 해요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"“이제 의견을 결정해 보겠습니다. 어떤 기준으로 의견을 결정하면 좋겠습니까?”"},{"who":"최윤희","text":"“우리가 쉽게 실천할 수 있는 의견으로 결정하면 좋겠습니다.”"},{"who":"박민준","text":"“단점보다는 장점이 큰 의견으로 결정하면 좋겠습니다.”"},{"who":"사회자","text":"“…… 더 많은 학생이 정우현 학생의 의견을 골랐습니다.”"},{"who":"선생님","text":"“여러분이 서로 질문하고 답하며 더 좋은 의견을 만들었습니다. 그러면 다음 미술 시간에는 복도 벽에 붙일 안내문을 만들어 보겠습니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_basic#1','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C26',1,'mc','auto','『국어』 128쪽 1번 (1)이에요. 지산이와 친구들에게 어떤 문제가 있나요?',ARRAY['K4-2-u3-X25']::text[],false,'{"seq":1,"concept":"K4-2-u3-C26","difficulty":1,"kind":"mc","stem":"『국어』 128쪽 1번 (1)이에요. 지산이와 친구들에게 어떤 문제가 있나요?","options":[{"t":"점심시간에 공놀이하는 친구들이 운동장을 다 차지해서 다른 놀이를 하기 어렵다","correct":true},{"t":"운동장에 나무가 너무 많다","mis":"K4-2-u3-X25"},{"t":"줄넘기 줄이 끊어졌다","mis":"K4-2-u3-X25"},{"t":"점심시간이 너무 길다","mis":"K4-2-u3-X25"}],"explanation":["친구들은 공놀이하는 친구가 많아 다른 놀이를 하기 어렵다고 했어요.","줄넘기하고 싶은데 번번이 공간이 없다고도 했어요.","문제 상황은 누가 어디에서 어떤 불편을 겪는지 찾아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“운동장에 공놀이하는 친구가 많아서 다른 놀이를 하기 어려워.”"},{"who":"친구 2","text":"“친구들과 줄넘기하고 싶은데 번번이 공간이 없어.”"},{"who":"지산","text":"“더 많은 친구가 운동장에서 하고 싶은 놀이를 할 수 있으면 좋을 텐데…….”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_basic#2','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C25',1,'mc','auto','『국어』 128쪽 1번 (3)이에요. 지산이가 자신의 생각을 제안하기에 알맞은 사람은 누구인가요?',ARRAY['K4-2-u3-X24']::text[],false,'{"seq":2,"concept":"K4-2-u3-C25","difficulty":1,"kind":"mc","stem":"『국어』 128쪽 1번 (3)이에요. 지산이가 자신의 생각을 제안하기에 알맞은 사람은 누구인가요?","options":[{"t":"담임 선생님이나 교장 선생님","correct":true},{"t":"공놀이하는 친구 한 명","mis":"K4-2-u3-X24"},{"t":"옆 학교 학생들","mis":"K4-2-u3-X24"},{"t":"운동장 옆 가게 주인","mis":"K4-2-u3-X24"}],"explanation":["제안은 그 일을 정하거나 바꿀 수 있는 사람에게 해요.","학교 운동장 사용은 선생님들께서 정하실 수 있어요.","친구 한 명이나 다른 학교 학생은 규칙을 정할 수 없어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“운동장에 공놀이하는 친구가 많아서 다른 놀이를 하기 어려워.”"},{"who":"친구 2","text":"“친구들과 줄넘기하고 싶은데 번번이 공간이 없어.”"},{"who":"지산","text":"“더 많은 친구가 운동장에서 하고 싶은 놀이를 할 수 있으면 좋을 텐데…….”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_basic#3','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C27',1,'blank','auto','『국어』 130쪽 2번 (2)예요. 지산이의 글에서 「요일별로 학년을 정하거나 …… 점심시간 운동장 사용 규칙을 만들면 좋겠습니다.」는 제안하는 글의 어느 부분인가요?',ARRAY['K4-2-u3-X26']::text[],false,'{"seq":3,"concept":"K4-2-u3-C27","difficulty":1,"kind":"blank","stem":"『국어』 130쪽 2번 (2)예요. 지산이의 글에서 「요일별로 학년을 정하거나 …… 점심시간 운동장 사용 규칙을 만들면 좋겠습니다.」는 제안하는 글의 어느 부분인가요?","options":[{"t":"제안하는 내용","correct":true},{"t":"문제 상황","mis":"K4-2-u3-X26"},{"t":"제안하는 이유","mis":"K4-2-u3-X26"}],"explanation":["‘……면 좋겠습니다.’로 바라는 것을 내놓았어요.","무엇을 바라는지가 드러난 부분이 제안하는 내용이에요.","다툼이 줄어든다는 부분은 제안하는 이유예요."],"asset":{"type":"passage","lines":["교장 선생님, 안녕하세요? 저는 4학년 최지산입니다.","요즘 우리 학교에 운동장을 사용하는 것 때문에 다툼이 많습니다.","특히 점심시간에 공놀이하는 친구들이 운동장을 모두 차지하고 있어","줄넘기나 다른 놀이를 하려는 친구들은 운동장을 사용하기가 어렵습니다.","요일별로 학년을 정하거나 운동장을 나누어 사용하는 방식과 같이","점심시간 운동장 사용 규칙을 만들면 좋겠습니다. 이렇게 하면 운동장을 둘러싼 다툼이 줄어들 것입니다.","그리고 더 많은 친구가 운동장에서 즐겁고 신나는 시간을 보낼 수 있을 것입니다.","바쁘시겠지만 제 제안을 잘 살펴봐 주시면 감사하겠습니다."],"title":"「운동장을 다 함께 사용하게 해 주세요」 — 『국어』 129쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_basic#4','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C30',1,'ox','auto','『국어』 131쪽 4번이에요. 제안하는 글을 쓰면 다른 사람들도 문제 상황에 관심을 기울일 수 있어요.',ARRAY['K4-2-u3-X31']::text[],false,'{"seq":4,"concept":"K4-2-u3-C30","difficulty":1,"kind":"ox","stem":"『국어』 131쪽 4번이에요. 제안하는 글을 쓰면 다른 사람들도 문제 상황에 관심을 기울일 수 있어요.","answer":"O","reason_options":[{"t":"제안하는 글을 읽은 사람들도 문제에 관심을 두고, 공감하면 해결에 함께 참여할 수 있어요.","correct":true},{"t":"제안하는 글은 속상한 마음을 쏟아 내는 글이라 다른 사람은 관심을 두지 않아요.","mis":"K4-2-u3-X31"}],"mis":"K4-2-u3-X31","explanation":["제안하는 글은 제안받는 사람만 읽는 것이 아니에요.","다른 사람들도 문제 상황을 알게 돼요.","공감한 사람들이 함께 해결에 나설 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_basic#5','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C27',2,'mc','auto','지산이의 글에서 ‘제안하는 이유’에 해당하는 문장은 무엇인가요?',ARRAY['K4-2-u3-X26']::text[],false,'{"seq":5,"concept":"K4-2-u3-C27","difficulty":2,"kind":"mc","stem":"지산이의 글에서 ‘제안하는 이유’에 해당하는 문장은 무엇인가요?","options":[{"t":"“이렇게 하면 운동장을 둘러싼 다툼이 줄어들 것입니다.”","correct":true},{"t":"“특히 점심시간에 공놀이하는 친구들이 운동장을 모두 차지하고 있어…….”","mis":"K4-2-u3-X26"},{"t":"“교장 선생님, 안녕하세요? 저는 4학년 최지산입니다.”","mis":"K4-2-u3-X26"},{"t":"“바쁘시겠지만 제 제안을 잘 살펴봐 주시면 감사하겠습니다.”","mis":"K4-2-u3-X26"}],"explanation":["제안하는 이유는 제안대로 하면 무엇이 좋아지는지예요.","다툼이 줄고 더 많은 친구가 즐겁게 지낼 수 있다고 했어요.","운동장을 차지하고 있다는 문장은 문제 상황이에요."],"asset":{"type":"passage","lines":["교장 선생님, 안녕하세요? 저는 4학년 최지산입니다.","요즘 우리 학교에 운동장을 사용하는 것 때문에 다툼이 많습니다.","특히 점심시간에 공놀이하는 친구들이 운동장을 모두 차지하고 있어","줄넘기나 다른 놀이를 하려는 친구들은 운동장을 사용하기가 어렵습니다.","요일별로 학년을 정하거나 운동장을 나누어 사용하는 방식과 같이","점심시간 운동장 사용 규칙을 만들면 좋겠습니다. 이렇게 하면 운동장을 둘러싼 다툼이 줄어들 것입니다.","그리고 더 많은 친구가 운동장에서 즐겁고 신나는 시간을 보낼 수 있을 것입니다.","바쁘시겠지만 제 제안을 잘 살펴봐 주시면 감사하겠습니다."],"title":"「운동장을 다 함께 사용하게 해 주세요」 — 『국어』 129쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_basic#6','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C29',2,'mc','auto','『국어』 131쪽 3번이에요. 제안하는 글을 쓸 때 생각해야 할 내용으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X29','K4-2-u3-X26']::text[],false,'{"seq":6,"concept":"K4-2-u3-C29","difficulty":2,"kind":"mc","stem":"『국어』 131쪽 3번이에요. 제안하는 글을 쓸 때 생각해야 할 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"제안하는 내용이 잘 드러나게 제목을 붙인다","correct":true},{"t":"글씨를 최대한 크게 쓴다","mis":"K4-2-u3-X29"},{"t":"읽을 사람이 누구인지는 생각하지 않는다","mis":"K4-2-u3-X29"},{"t":"제안하는 내용은 숨기고 문제만 쓴다","mis":"K4-2-u3-X26"}],"explanation":["먼저 문제 상황이 무엇인지 파악해요.","제안하는 내용과 이유가 들어가야 하고, 이유가 적절해야 해요.","제안이 드러나는 제목과 누구에게 쓸지도 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_basic#7','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C28',2,'mc','auto','「운동장에서 공놀이하지 마세요.」라는 말이 제안하는 글로 부족한 까닭은 무엇인가요?',ARRAY['K4-2-u3-X27','K4-2-u3-X28','K4-2-u3-X24']::text[],false,'{"seq":7,"concept":"K4-2-u3-C28","difficulty":2,"kind":"mc","stem":"「운동장에서 공놀이하지 마세요.」라는 말이 제안하는 글로 부족한 까닭은 무엇인가요?","options":[{"t":"하지 못하게 막기만 하고, 모두가 운동장을 함께 쓸 방법과 그 이유가 없기 때문","correct":true},{"t":"‘~하세요’로 끝나서 제안하는 글로 충분하다","mis":"K4-2-u3-X27"},{"t":"짧게 막을수록 좋은 제안이기 때문","mis":"K4-2-u3-X28"},{"t":"교장 선생님께 쓰지 않았기 때문","mis":"K4-2-u3-X24"}],"explanation":["이 말은 어떤 행동을 하지 못하게 막는 금지에 가까워요.","제안은 문제를 해결할 방법을 의견으로 내놓는 것이에요.","지산이처럼 방법과 이유를 함께 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_basic#8','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C31',2,'mc','auto','문제를 해결하는 방법에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X04','K4-2-u3-X05']::text[],false,'{"seq":8,"concept":"K4-2-u3-C31","difficulty":2,"kind":"mc","stem":"문제를 해결하는 방법에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"토의, 토론, 안내문, 표어, 설문 조사, 캠페인, 제안하는 글 가운데에서 상황에 맞는 방법을 고른다","correct":true},{"t":"문제가 생기면 무조건 제안하는 글을 써야 한다","mis":"K4-2-u3-X04"},{"t":"토의를 했으면 다른 방법은 필요 없다","mis":"K4-2-u3-X05"},{"t":"어떤 방법도 쓰지 않고 저절로 풀리기를 기다린다","mis":"K4-2-u3-X04"}],"explanation":["문제를 해결하는 방법은 여러 가지예요.","제안하는 글 쓰기도 그 가운데 하나예요.","상황에 따라 알맞은 방법을 골라야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_basic#9','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C30',2,'mc','auto','『국어』 131쪽 4번 친구들의 말 가운데 제안하는 글을 쓰면 좋은 점을 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u3-X30','K4-2-u3-X31']::text[],false,'{"seq":9,"concept":"K4-2-u3-C30","difficulty":2,"kind":"mc","stem":"『국어』 131쪽 4번 친구들의 말 가운데 제안하는 글을 쓰면 좋은 점을 알맞게 말한 것은 무엇인가요?","options":[{"t":"직접 만나 제안할 수 없는 사람에게도 제안할 수 있어.","correct":true},{"t":"글로 제안하면 언제나 그대로 받아들여져.","mis":"K4-2-u3-X30"},{"t":"제안하는 글에는 불만을 마음껏 쏟아 낼 수 있어.","mis":"K4-2-u3-X31"},{"t":"글을 쓰면 문제를 해결할 필요가 없어져.","mis":"K4-2-u3-X30"}],"explanation":["제안하는 글은 만나기 어려운 사람에게도 생각을 전할 수 있어요.","하지만 제안이 언제나 받아들여지는 것은 아니에요.","불만을 쏟는 글이 아니라 해결 방법을 내놓는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_basic#10','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C26',3,'mc','auto','『국어활동』 40쪽 조대웅의 글에서 문제 상황에 해당하는 것은 무엇인가요?',ARRAY['K4-2-u3-X26','K4-2-u3-X25']::text[],false,'{"seq":10,"concept":"K4-2-u3-C26","difficulty":3,"kind":"mc","stem":"『국어활동』 40쪽 조대웅의 글에서 문제 상황에 해당하는 것은 무엇인가요?","options":[{"t":"동네 여기저기에 플라스틱 컵, 과자 봉지, 휴지 같은 쓰레기가 버려져 있다","correct":true},{"t":"일주일에 하루를 정해 쓰레기를 줍는 날을 만들자","mis":"K4-2-u3-X26"},{"t":"운동도 하면서 동네를 깨끗하게 만들 수 있다","mis":"K4-2-u3-X26"},{"t":"주민들이 산책을 너무 많이 한다","mis":"K4-2-u3-X25"}],"explanation":["조대웅은 동네 곳곳에 쓰레기가 많다는 문제를 겪었어요.","쓰레기를 줍는 날을 만들자는 것은 제안하는 내용이에요.","운동도 하고 동네도 깨끗해진다는 것은 제안하는 이유예요."],"asset":{"type":"passage","lines":["안녕하세요? 주민 여러분. 저는 ○○동에 사는 초등학교 4학년 조대웅입니다.","요즘 동네를 다니다 보면 여기저기에 버려진 쓰레기가 많습니다.","길가에 놓인 플라스틱 컵, 놀이터에 떨어진 과자 봉지, 화단 구석에 쌓인 휴지까지…….","일주일에 하루를 정해 동네를 산책하면서 쓰레기를 줍는 날을 만들면 어떨까요?","산책하면서 쓰레기를 하나씩 주우면 운동도 하면서 동네를 깨끗하게 만들 수 있어","일석이조의 효과를 볼 수 있기 때문입니다. 또 쓰레기를 길가에 버리지 않는 습관도 생길 것입니다.","주민 여러분, 작은 실천을 모아 우리 동네를 더 깨끗하고 살기 좋은 곳으로 만들어요!"],"title":"「깨끗한 동네를 만들기 위해 함께 노력해요」 — 『국어활동』 40쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_challenge#1','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C25',2,'mc','auto','『국어활동』 40쪽 조대웅이 제안하는 글을 쓴 대상은 누구인가요?',ARRAY['K4-2-u3-X24']::text[],false,'{"seq":1,"concept":"K4-2-u3-C25","difficulty":2,"kind":"mc","stem":"『국어활동』 40쪽 조대웅이 제안하는 글을 쓴 대상은 누구인가요?","options":[{"t":"○○동 주민 여러분","correct":true},{"t":"교장 선생님","mis":"K4-2-u3-X24"},{"t":"과자 회사","mis":"K4-2-u3-X24"},{"t":"조대웅의 담임 선생님","mis":"K4-2-u3-X24"}],"explanation":["글의 첫머리에 “안녕하세요? 주민 여러분.”이라고 썼어요.","동네 쓰레기는 주민들이 함께 실천해야 줄일 수 있어요.","그래서 주민들에게 제안했어요."],"asset":{"type":"passage","lines":["안녕하세요? 주민 여러분. 저는 ○○동에 사는 초등학교 4학년 조대웅입니다.","요즘 동네를 다니다 보면 여기저기에 버려진 쓰레기가 많습니다.","길가에 놓인 플라스틱 컵, 놀이터에 떨어진 과자 봉지, 화단 구석에 쌓인 휴지까지…….","일주일에 하루를 정해 동네를 산책하면서 쓰레기를 줍는 날을 만들면 어떨까요?","산책하면서 쓰레기를 하나씩 주우면 운동도 하면서 동네를 깨끗하게 만들 수 있어","일석이조의 효과를 볼 수 있기 때문입니다. 또 쓰레기를 길가에 버리지 않는 습관도 생길 것입니다.","주민 여러분, 작은 실천을 모아 우리 동네를 더 깨끗하고 살기 좋은 곳으로 만들어요!"],"title":"「깨끗한 동네를 만들기 위해 함께 노력해요」 — 『국어활동』 40쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_challenge#2','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C27',2,'mc','auto','조대웅의 글에서 제안하는 이유를 바르게 찾은 것은 무엇인가요?',ARRAY['K4-2-u3-X26','K4-2-u3-X37']::text[],false,'{"seq":2,"concept":"K4-2-u3-C27","difficulty":2,"kind":"mc","stem":"조대웅의 글에서 제안하는 이유를 바르게 찾은 것은 무엇인가요?","options":[{"t":"운동도 하면서 동네를 깨끗하게 만들 수 있고, 쓰레기를 길가에 버리지 않는 습관도 생긴다","correct":true},{"t":"길가에 플라스틱 컵, 놀이터에 과자 봉지가 버려져 있다","mis":"K4-2-u3-X26"},{"t":"일주일에 하루를 정해 산책하며 쓰레기를 줍자","mis":"K4-2-u3-X26"},{"t":"쓰레기 때문에 내 마음이 속상하다","mis":"K4-2-u3-X37"}],"explanation":["이유는 제안대로 하면 좋아지는 점이에요.","일석이조 — 운동도 하고 동네도 깨끗해진다고 했어요.","버려진 쓰레기는 문제 상황, 줍는 날은 제안하는 내용이에요."],"asset":{"type":"passage","lines":["안녕하세요? 주민 여러분. 저는 ○○동에 사는 초등학교 4학년 조대웅입니다.","요즘 동네를 다니다 보면 여기저기에 버려진 쓰레기가 많습니다.","길가에 놓인 플라스틱 컵, 놀이터에 떨어진 과자 봉지, 화단 구석에 쌓인 휴지까지…….","일주일에 하루를 정해 동네를 산책하면서 쓰레기를 줍는 날을 만들면 어떨까요?","산책하면서 쓰레기를 하나씩 주우면 운동도 하면서 동네를 깨끗하게 만들 수 있어","일석이조의 효과를 볼 수 있기 때문입니다. 또 쓰레기를 길가에 버리지 않는 습관도 생길 것입니다.","주민 여러분, 작은 실천을 모아 우리 동네를 더 깨끗하고 살기 좋은 곳으로 만들어요!"],"title":"「깨끗한 동네를 만들기 위해 함께 노력해요」 — 『국어활동』 40쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_challenge#3','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C27',3,'match','auto','지산이의 글에 있는 문장과 제안하는 글의 짜임을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u3-C27","difficulty":3,"kind":"match","stem":"지산이의 글에 있는 문장과 제안하는 글의 짜임을 알맞게 이으세요.","pairs":[{"l":"“점심시간에 공놀이하는 친구들이 운동장을 모두 차지하고 있어……”","r":"문제 상황"},{"l":"“점심시간 운동장 사용 규칙을 만들면 좋겠습니다.”","r":"제안하는 내용"},{"l":"“더 많은 친구가 운동장에서 즐겁고 신나는 시간을 보낼 수 있을 것입니다.”","r":"제안하는 이유"}],"mis":"K4-2-u3-X26","explanation":["무엇이 불편한가 — 문제 상황이에요.","무엇을 바라는가 — 제안하는 내용이에요.","그러면 무엇이 좋아지는가 — 제안하는 이유예요."],"asset":{"type":"passage","lines":["교장 선생님, 안녕하세요? 저는 4학년 최지산입니다.","요즘 우리 학교에 운동장을 사용하는 것 때문에 다툼이 많습니다.","특히 점심시간에 공놀이하는 친구들이 운동장을 모두 차지하고 있어","줄넘기나 다른 놀이를 하려는 친구들은 운동장을 사용하기가 어렵습니다.","요일별로 학년을 정하거나 운동장을 나누어 사용하는 방식과 같이","점심시간 운동장 사용 규칙을 만들면 좋겠습니다. 이렇게 하면 운동장을 둘러싼 다툼이 줄어들 것입니다.","그리고 더 많은 친구가 운동장에서 즐겁고 신나는 시간을 보낼 수 있을 것입니다.","바쁘시겠지만 제 제안을 잘 살펴봐 주시면 감사하겠습니다."],"title":"「운동장을 다 함께 사용하게 해 주세요」 — 『국어』 129쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_challenge#4','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C31',3,'error','auto','세 친구가 문제를 해결할 방법을 정했어요. 상황에 맞지 않는 방법을 고른 친구는 누구인가요?',ARRAY['K4-2-u3-X04','K4-2-u3-X05']::text[],false,'{"seq":4,"concept":"K4-2-u3-C31","difficulty":3,"kind":"error","stem":"세 친구가 문제를 해결할 방법을 정했어요. 상황에 맞지 않는 방법을 고른 친구는 누구인가요?","options":[{"t":"수아: 짝과 자리 정리 문제로 말다툼을 했으니 교장 선생님께 제안하는 글을 써야겠어.","correct":true,"mis_target":"K4-2-u3-X04"},{"t":"민호: 반 친구 모두가 함께 정할 일이니 학급 회의에서 토의해 보자.","mis":"K4-2-u3-X05"},{"t":"지아: 운동장 사용은 학교 전체의 일이니 교장 선생님께 제안하는 글을 쓰자.","mis":"K4-2-u3-X04"}],"explanation":["제안하는 글은 문제를 해결하는 여러 방법 가운데 하나예요.","짝과의 일은 짝에게 직접 차분히 말하는 것이 알맞아요.","모두의 일은 토의로, 학교의 일은 제안하는 글로 풀 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_challenge#5','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C29',3,'mc','auto','제안하는 글을 쓸 때 문제 상황을 보여 주는 사진이나 그림 자료를 준비하는 까닭은 무엇인가요?',ARRAY['K4-2-u3-X29']::text[],false,'{"seq":5,"concept":"K4-2-u3-C29","difficulty":3,"kind":"mc","stem":"제안하는 글을 쓸 때 문제 상황을 보여 주는 사진이나 그림 자료를 준비하는 까닭은 무엇인가요?","options":[{"t":"문제 상황을 구체적으로 알 수 있게 하려고","correct":true},{"t":"글을 길어 보이게 하려고","mis":"K4-2-u3-X29"},{"t":"제안하는 내용을 숨기려고","mis":"K4-2-u3-X29"},{"t":"글을 읽지 않아도 되게 하려고","mis":"K4-2-u3-X29"}],"explanation":["사진이나 그림을 보면 문제가 얼마나 심각한지 한눈에 알 수 있어요.","읽는 사람이 문제 상황을 더 잘 이해해요.","사진은 글을 대신하는 것이 아니라 돕는 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_challenge#6','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C28',3,'mc','auto','다음 가운데 ‘제안’에 해당하는 말은 무엇인가요?',ARRAY['K4-2-u3-X27','K4-2-u3-X28','K4-2-u3-X57']::text[],false,'{"seq":6,"concept":"K4-2-u3-C28","difficulty":3,"kind":"mc","stem":"다음 가운데 ‘제안’에 해당하는 말은 무엇인가요?","options":[{"t":"“점심시간 운동장 사용 규칙을 만들면 좋겠습니다. 그러면 다툼이 줄어들 것입니다.”","correct":true},{"t":"“운동장에서 공놀이를 하면 안 됩니다.”","mis":"K4-2-u3-X27"},{"t":"“운동장 좀 비켜 주세요.”","mis":"K4-2-u3-X28"},{"t":"“공놀이하는 친구들 때문에 짜증 나요.”","mis":"K4-2-u3-X57"}],"explanation":["제안은 해결 방법을 의견으로 내놓는 거예요.","하지 못하게 막는 것은 금지, 무엇을 해 달라고 청하는 것은 요청이에요.","제안에는 방법과 그 이유가 함께 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_challenge#7','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C30',3,'mc','auto','「푸른 하늘의 날」 이야기에서 알 수 있는 제안의 힘은 무엇인가요?',ARRAY['K4-2-u3-X57','K4-2-u3-X30']::text[],false,'{"seq":7,"concept":"K4-2-u3-C30","difficulty":3,"kind":"mc","stem":"「푸른 하늘의 날」 이야기에서 알 수 있는 제안의 힘은 무엇인가요?","options":[{"t":"국민이 낸 생각도 여러 사람이 공감하면 실제로 세상을 바꿀 수 있다","correct":true},{"t":"제안은 어른만 할 수 있다","mis":"K4-2-u3-X57"},{"t":"제안하면 언제나 바로 받아들여진다","mis":"K4-2-u3-X30"},{"t":"제안은 우리나라 안에서만 할 수 있다","mis":"K4-2-u3-X30"}],"explanation":["일반 국민이 낸 아이디어가 정부의 제안이 되었어요.","여러 나라가 공감해 유엔 기념일이 되었어요.","제안은 문제를 함께 풀도록 사람들을 움직여요."],"asset":{"type":"passage","lines":["(간추림) 해마다 9월 7일은 ‘푸른 하늘을 위한 국제 맑은 공기의 날’이다.","(간추림) 국민 정책 참여단에서 일반 국민이 아이디어를 냈고, 정부가 국제 사회에 제안했다.","(간추림) 대기 오염 문제는 여러 나라가 함께 노력해야 하기 때문이다.","(간추림) 그 뒤 유엔 총회에서 이날을 기념일로 정했다."],"title":"「푸른 하늘의 날」 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_challenge#8','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C27',4,'essay','teacher','『국어』 128쪽 1번 (2)예요. 자신이 지산이라면 문제를 해결하기 위해 무엇을 제안하고 싶은지, 그 이유와 누구에게 제안할지를 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u3-C27","difficulty":4,"kind":"essay","stem":"『국어』 128쪽 1번 (2)예요. 자신이 지산이라면 문제를 해결하기 위해 무엇을 제안하고 싶은지, 그 이유와 누구에게 제안할지를 함께 쓰세요.","answer_guide":{"answer":"예: 더 많은 친구가 운동장을 사용할 수 있도록 운동장 사용 규칙을 만들자고 교장 선생님께 제안하고 싶다. 그러면 공놀이를 하는 친구와 줄넘기를 하는 친구가 다투지 않고 모두 즐겁게 놀 수 있기 때문이다.","scoring_points":["문제 상황(운동장을 다 차지함)을 해결하는 제안을 썼는가","제안대로 하면 좋아지는 점을 이유로 썼는가","규칙을 정할 수 있는 사람을 대상으로 골랐는가"]},"explanation":["먼저 지산이가 겪은 문제를 떠올려요.","그 문제를 바로 해결할 수 있는 방법을 제안해요.","제안을 받아 실제로 바꿀 수 있는 사람에게 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“운동장에 공놀이하는 친구가 많아서 다른 놀이를 하기 어려워.”"},{"who":"친구 2","text":"“친구들과 줄넘기하고 싶은데 번번이 공간이 없어.”"},{"who":"지산","text":"“더 많은 친구가 운동장에서 하고 싶은 놀이를 할 수 있으면 좋을 텐데…….”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_challenge#9','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C31',4,'essay','teacher','「복도에서 서로 부딪치지 않게 오른쪽으로 걸어 다니자」는 생각을 우리 학교 친구들에게 알리고 싶어요. 제안하는 글 말고 쓸 수 있는 방법 하나와, 제안하는 글을 쓰면 좋은 점 하나를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u3-C31","difficulty":4,"kind":"essay","stem":"「복도에서 서로 부딪치지 않게 오른쪽으로 걸어 다니자」는 생각을 우리 학교 친구들에게 알리고 싶어요. 제안하는 글 말고 쓸 수 있는 방법 하나와, 제안하는 글을 쓰면 좋은 점 하나를 쓰세요.","answer_guide":{"answer":"예: 다른 방법 — 복도에 ‘오른쪽으로 걸어요’ 표어를 붙이거나 캠페인을 한다. 제안하는 글의 좋은 점 — 왜 오른쪽으로 걸어야 하는지 이유를 차분히 전할 수 있고, 읽은 친구들도 문제에 관심을 두게 된다.","scoring_points":["제안하는 글 말고 다른 알맞은 방법(표어·안내문·캠페인·토의 등)을 썼는가","제안하는 글을 쓰면 좋은 점을 썼는가","상황에 맞게 방법을 고른다는 생각이 드러나는가"]},"explanation":["문제를 해결하는 방법은 여러 가지예요.","제안하는 글은 그 가운데 하나로, 상황에 맞게 골라요.","제안하는 글은 이유까지 차분히 전할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L06_challenge#10','kor',4,2,'u3','L06','tb_g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C25',4,'mc','auto','지산이는 교장 선생님께, 조대웅은 주민 여러분께 제안했어요. 두 글의 제안 대상이 다른 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X24']::text[],false,'{"seq":10,"concept":"K4-2-u3-C25","difficulty":4,"kind":"mc","stem":"지산이는 교장 선생님께, 조대웅은 주민 여러분께 제안했어요. 두 글의 제안 대상이 다른 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"운동장 사용 규칙은 교장 선생님이 정할 수 있고, 동네 쓰레기는 주민들이 함께 실천해야 줄일 수 있기 때문","correct":true},{"t":"교장 선생님이 주민보다 나이가 많기 때문","mis":"K4-2-u3-X24"},{"t":"두 사람이 각자 친한 사람에게 썼기 때문","mis":"K4-2-u3-X24"},{"t":"제안 대상은 아무렇게나 정해도 되기 때문","mis":"K4-2-u3-X24"}],"explanation":["제안 대상은 그 문제를 해결하거나 바꿀 수 있는 사람이에요.","학교 규칙은 교장 선생님이 정하실 수 있어요.","동네를 깨끗하게 하는 일은 주민 모두가 함께 해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_basic#1','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C32',1,'mc','auto','『국어』 132쪽 1번이에요. 제안하는 글을 쓰는 과정을 차례대로 바르게 나타낸 것은 무엇인가요?',ARRAY['K4-2-u3-X32']::text[],false,'{"seq":1,"concept":"K4-2-u3-C32","difficulty":1,"kind":"mc","stem":"『국어』 132쪽 1번이에요. 제안하는 글을 쓰는 과정을 차례대로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"문제 상황 파악하기 → 누구에게 제안할지 생각하기 → 제안하는 내용을 정하고 이유 설명하기 → 제안하는 글 쓰기","correct":true},{"t":"제안하는 글 쓰기 → 문제 상황 파악하기 → 누구에게 제안할지 생각하기 → 제안하는 내용을 정하고 이유 설명하기","mis":"K4-2-u3-X32"},{"t":"누구에게 제안할지 생각하기 → 제안하는 글 쓰기 → 문제 상황 파악하기 → 제안하는 내용을 정하고 이유 설명하기","mis":"K4-2-u3-X32"},{"t":"제안하는 내용을 정하고 이유 설명하기 → 제안하는 글 쓰기 → 누구에게 제안할지 생각하기 → 문제 상황 파악하기","mis":"K4-2-u3-X32"}],"explanation":["먼저 무엇이 문제인지 파악해요.","그다음 누구에게 제안할지, 무엇을 제안하고 왜 그런지 정해요.","마지막으로 제안하는 글을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_basic#2','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C37',1,'mc','auto','『국어』 133쪽 2번 (1)이에요. 「연우의 일기」에서 연우가 해결하고 싶은 문제 상황은 무엇인가요?',ARRAY['K4-2-u3-X06','K4-2-u3-X42']::text[],false,'{"seq":2,"concept":"K4-2-u3-C37","difficulty":1,"kind":"mc","stem":"『국어』 133쪽 2번 (1)이에요. 「연우의 일기」에서 연우가 해결하고 싶은 문제 상황은 무엇인가요?","options":[{"t":"과학관에 비가 올 때 도시락이나 간식을 먹을 공간이 없다","correct":true},{"t":"공룡알 화석이 기억에 남는다","mis":"K4-2-u3-X06"},{"t":"자율 주행 로봇 수업에 늦을 뻔했다","mis":"K4-2-u3-X42"},{"t":"도시락이 너무 맛있었다","mis":"K4-2-u3-X42"}],"explanation":["연우는 소나기 때문에 바깥 쉼터에서 도시락을 먹지 못했어요.","실내에는 마땅히 먹을 곳이 없었어요.","그래서 “이 상황을 해결할 방법은 없을까?” 하고 생각했어요."],"asset":{"type":"passage","lines":["오늘은 가족과 가람어린이과학관에 다녀왔다.","(간추림) 공룡알 화석과 자전거로 전기를 만드는 체험이 재미있었다.","기다리던 점심시간이 되어 음식을 먹을 공간을 찾아보았다.","실내에는 마땅한 장소가 없어서 바깥 쉼터에서 먹기로 했다.","돗자리를 깔고 있는데 갑자기 소나기가 내렸다.","비가 그쳐서야 자리를 잡고 도시락과 간식을 먹을 수 있었다.","즐거운 하루였지만 점심시간에 조마조마했던 마음이 자꾸 떠오른다.","다른 사람들은 어떻게 점심을 먹었을까? 이 상황을 해결할 방법은 없을까?"],"title":"「연우의 일기」 — 『국어』 132쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_basic#3','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C34',1,'mc','auto','『국어』 133쪽 2번 (2)예요. 연우가 제안하기에 알맞은 대상과 그 까닭을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u3-X24']::text[],false,'{"seq":3,"concept":"K4-2-u3-C34","difficulty":1,"kind":"mc","stem":"『국어』 133쪽 2번 (2)예요. 연우가 제안하기에 알맞은 대상과 그 까닭을 바르게 말한 것은 무엇인가요?","options":[{"t":"과학관 관장님 — 과학관의 공간 변경에 대해 결정을 내릴 수 있는 분이라서","correct":true},{"t":"연우의 가족 — 함께 과학관에 가서","mis":"K4-2-u3-X24"},{"t":"다른 관람객 — 같은 불편을 겪어서","mis":"K4-2-u3-X24"},{"t":"연우의 담임 선생님 — 일기를 읽어 주셔서","mis":"K4-2-u3-X24"}],"explanation":["제안은 그 일을 결정할 수 있는 사람에게 해야 해요.","과학관의 공간을 바꾸는 일은 관장님이 결정할 수 있어요.","대상을 분명히 하면 제안하는 내용도 구체적이 돼요."],"asset":{"type":"passage","lines":["오늘은 가족과 가람어린이과학관에 다녀왔다.","(간추림) 공룡알 화석과 자전거로 전기를 만드는 체험이 재미있었다.","기다리던 점심시간이 되어 음식을 먹을 공간을 찾아보았다.","실내에는 마땅한 장소가 없어서 바깥 쉼터에서 먹기로 했다.","돗자리를 깔고 있는데 갑자기 소나기가 내렸다.","비가 그쳐서야 자리를 잡고 도시락과 간식을 먹을 수 있었다.","즐거운 하루였지만 점심시간에 조마조마했던 마음이 자꾸 떠오른다.","다른 사람들은 어떻게 점심을 먹었을까? 이 상황을 해결할 방법은 없을까?"],"title":"「연우의 일기」 — 『국어』 132쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_basic#4','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C38',1,'ox','auto','『국어』 134쪽이에요. ‘……합시다.’, ‘……하면 어떨까요?’, ‘……하면 좋겠습니다.’는 제안하는 내용을 쓸 때 주로 쓰는 표현이에요.',ARRAY['K4-2-u3-X40']::text[],false,'{"seq":4,"concept":"K4-2-u3-C38","difficulty":1,"kind":"ox","stem":"『국어』 134쪽이에요. ‘……합시다.’, ‘……하면 어떨까요?’, ‘……하면 좋겠습니다.’는 제안하는 내용을 쓸 때 주로 쓰는 표현이에요.","answer":"O","reason_options":[{"t":"바라는 것을 내놓을 때 이런 표현을 주로 써요.","correct":true},{"t":"이 표현들은 제안하는 이유를 쓸 때만 써요.","mis":"K4-2-u3-X40"}],"mis":"K4-2-u3-X40","explanation":["연우는 “공간을 만들어 주시면 좋겠습니다.”라고 썼어요.","이유를 쓸 때에는 ‘왜냐하면 ……하기 때문입니다.’를 주로 써요.","두 갈래 표현을 구별해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_basic#5','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C35',2,'blank','auto','『국어』 133쪽 2번 (3)이에요. 「○ 제안하는 내용을 (     )할 수 있는가?」 빈칸에 알맞은 말을 보기(적절 · 실천 · 장점과 단점)에서 고르세요.',ARRAY['K4-2-u3-X36','K4-2-u3-X34']::text[],false,'{"seq":5,"concept":"K4-2-u3-C35","difficulty":2,"kind":"blank","stem":"『국어』 133쪽 2번 (3)이에요. 「○ 제안하는 내용을 (     )할 수 있는가?」 빈칸에 알맞은 말을 보기(적절 · 실천 · 장점과 단점)에서 고르세요.","options":[{"t":"실천","correct":true},{"t":"적절","mis":"K4-2-u3-X36"},{"t":"장점과 단점","mis":"K4-2-u3-X34"}],"explanation":["제안하는 내용은 실제로 할 수 있어야 해요.","제안하는 내용의 장점과 단점도 생각해요.","제안하는 이유는 적절한지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_basic#6','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C36',2,'mc','auto','연우의 글에서 제안하는 이유를 바르게 정리한 것은 무엇인가요?',ARRAY['K4-2-u3-X37','K4-2-u3-X36','K4-2-u3-X26']::text[],false,'{"seq":6,"concept":"K4-2-u3-C36","difficulty":2,"kind":"mc","stem":"연우의 글에서 제안하는 이유를 바르게 정리한 것은 무엇인가요?","options":[{"t":"날씨와 상관없이 편하게 음식을 먹고, 전시를 더 오래 관람하고, 오후 체험 수업에도 참여할 수 있다","correct":true},{"t":"제가 비를 맞아서 속상했기 때문입니다","mis":"K4-2-u3-X37"},{"t":"왜냐하면 과학관이기 때문입니다","mis":"K4-2-u3-X36"},{"t":"비가 그칠 때까지 기다려야 했습니다","mis":"K4-2-u3-X26"}],"explanation":["연우는 ‘왜냐하면 ……기 때문입니다.’로 이유를 썼어요.","공간이 생기면 많은 관람객에게 좋아지는 점을 들었어요.","비가 그칠 때까지 기다린 것은 문제 상황이에요."],"asset":{"type":"passage","lines":["가람어린이과학관에 도시락이나 간식을 편하게 먹을 수 있는 공간을 만들어 주시면 좋겠습니다.","왜냐하면 그런 공간이 있다면 날씨와 상관없이 편하고 즐겁게 음식을 먹을 수 있기 때문입니다.","또 음식을 먹고 나면 과학관의 전시를 더 오랜 시간 관람할 수 있고","오후 체험 수업에도 참여할 수 있습니다.","과학관을 찾은 관람객들이 불편을 겪지 않고 좋은 추억을 간직할 수 있도록","제 제안을 잘 검토해 주시면 감사하겠습니다."],"title":"「도시락이나 간식 먹을 공간을 만들어 주세요」 뒷부분 — 『국어』 134쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_basic#7','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C39',2,'mc','auto','「이건 당장 바꿔 주세요.」를 제안하는 글에 어울리게 예의 있는 표현으로 고친 것은 무엇인가요?',ARRAY['K4-2-u3-X39','K4-2-u3-X31']::text[],false,'{"seq":7,"concept":"K4-2-u3-C39","difficulty":2,"kind":"mc","stem":"「이건 당장 바꿔 주세요.」를 제안하는 글에 어울리게 예의 있는 표현으로 고친 것은 무엇인가요?","options":[{"t":"이런 점을 개선해 주신다면 더 나은 학교생활이 될 것 같습니다.","correct":true},{"t":"무조건 이번 주 안에 바꿔 주세요.","mis":"K4-2-u3-X39"},{"t":"왜 아직도 안 바꾸시는지 정말 답답합니다.","mis":"K4-2-u3-X31"},{"t":"바꿔 주세요. 바꿔 주세요. 바꿔 주세요.","mis":"K4-2-u3-X39"}],"explanation":["제안하는 글은 상대에게 강요하지 않아요.","불만을 쏟아 내지 않고 예의 있게 써요.","바뀌면 좋아지는 점을 함께 쓰면 받아들이고 싶어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_basic#8','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C33',2,'mc','auto','제안하는 글을 쓰다가 제안하는 이유가 약하다는 것을 알았을 때 어떻게 하면 좋을까요?',ARRAY['K4-2-u3-X33','K4-2-u3-X36']::text[],false,'{"seq":8,"concept":"K4-2-u3-C33","difficulty":2,"kind":"mc","stem":"제안하는 글을 쓰다가 제안하는 이유가 약하다는 것을 알았을 때 어떻게 하면 좋을까요?","options":[{"t":"앞 단계로 돌아가 제안하는 내용과 이유를 다시 생각해도 된다","correct":true},{"t":"차례를 거꾸로 갈 수 없으니 그대로 쓴다","mis":"K4-2-u3-X33"},{"t":"처음부터 전혀 다른 문제로 다시 쓴다","mis":"K4-2-u3-X33"},{"t":"이유는 빼고 제안만 쓴다","mis":"K4-2-u3-X36"}],"explanation":["쓰는 과정의 차례는 길잡이예요.","필요하면 앞 단계로 되돌아가도 괜찮아요.","이유를 다시 생각하면 더 설득력 있는 글이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_basic#9','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C40',2,'mc','auto','제안하는 글을 보냈는데 제안이 받아들여지지 않았을 때 알맞은 태도는 무엇인가요?',ARRAY['K4-2-u3-X41','K4-2-u3-X30']::text[],false,'{"seq":9,"concept":"K4-2-u3-C40","difficulty":2,"kind":"mc","stem":"제안하는 글을 보냈는데 제안이 받아들여지지 않았을 때 알맞은 태도는 무엇인가요?","options":[{"t":"받아들여지지 않은 까닭을 살펴 제안을 고치거나 다른 방법을 찾는다","correct":true},{"t":"다시는 제안하지 않는다","mis":"K4-2-u3-X41"},{"t":"같은 글을 날마다 다시 보낸다","mis":"K4-2-u3-X41"},{"t":"글로 제안했으니 언제나 받아들여질 것이라며 따진다","mis":"K4-2-u3-X30"}],"explanation":["제안하는 글은 대상이 정해져 있어 받아들여지지 않을 수도 있어요.","그 까닭을 살피면 더 나은 제안을 할 수 있어요.","다른 방법을 찾아보는 것도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_basic#10','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C37',3,'mc','auto','『국어』 134쪽이에요. 「도시락이나 간식 먹을 공간을 만들어 주세요」라는 제목에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X42']::text[],false,'{"seq":10,"concept":"K4-2-u3-C37","difficulty":3,"kind":"mc","stem":"『국어』 134쪽이에요. 「도시락이나 간식 먹을 공간을 만들어 주세요」라는 제목에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"제안하는 내용이 잘 드러나고, 글을 다 쓴 뒤에 붙여도 된다","correct":true},{"t":"글쓴이의 이름이 드러나야 좋은 제목이다","mis":"K4-2-u3-X42"},{"t":"과학관의 위치만 드러나면 된다","mis":"K4-2-u3-X42"},{"t":"제목은 내용과 상관없이 아무렇게나 붙여도 된다","mis":"K4-2-u3-X42"}],"explanation":["제목만 보아도 무엇을 제안하는지 알 수 있어요.","제목은 글을 완성하고 나서 붙일 수도 있어요.","제안하는 내용이 드러나게 붙여요."],"asset":{"type":"passage","lines":["가람어린이과학관에 도시락이나 간식을 편하게 먹을 수 있는 공간을 만들어 주시면 좋겠습니다.","왜냐하면 그런 공간이 있다면 날씨와 상관없이 편하고 즐겁게 음식을 먹을 수 있기 때문입니다.","또 음식을 먹고 나면 과학관의 전시를 더 오랜 시간 관람할 수 있고","오후 체험 수업에도 참여할 수 있습니다.","과학관을 찾은 관람객들이 불편을 겪지 않고 좋은 추억을 간직할 수 있도록","제 제안을 잘 검토해 주시면 감사하겠습니다."],"title":"「도시락이나 간식 먹을 공간을 만들어 주세요」 뒷부분 — 『국어』 134쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_challenge#1','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C36',2,'mc','auto','의견에 대해 이유를 드는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X36','K4-2-u3-X37','K4-2-u3-X38']::text[],false,'{"seq":1,"concept":"K4-2-u3-C36","difficulty":2,"kind":"mc","stem":"의견에 대해 이유를 드는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"의견을 따랐을 때의 좋은 점을 알아본다","correct":true},{"t":"‘왜냐하면’만 붙이면 어떤 말이든 이유가 된다","mis":"K4-2-u3-X36"},{"t":"내가 좋아하는 것이라고만 쓴다","mis":"K4-2-u3-X37"},{"t":"확인하지 않은 소문을 사실처럼 쓴다","mis":"K4-2-u3-X38"}],"explanation":["경험이나 배경지식을 떠올려 이유를 찾을 수 있어요.","의견을 따랐을 때의 좋은 점을 알아보아요.","전문가 의견 같은 객관적인 자료도 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_challenge#2','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C38',2,'mc','auto','제안을 받아들이면 좋은 점을 쓸 때 주로 쓰는 표현은 무엇인가요?',ARRAY['K4-2-u3-X40','K4-2-u3-X39']::text[],false,'{"seq":2,"concept":"K4-2-u3-C38","difficulty":2,"kind":"mc","stem":"제안을 받아들이면 좋은 점을 쓸 때 주로 쓰는 표현은 무엇인가요?","options":[{"t":"‘왜냐하면 ……하기 때문입니다.’, ‘……하면 ……할 수 있습니다.’","correct":true},{"t":"‘……합시다.’, ‘……하면 어떨까요?’","mis":"K4-2-u3-X40"},{"t":"‘요즘 ……하고 있다.’","mis":"K4-2-u3-X40"},{"t":"‘무조건 ……하세요.’","mis":"K4-2-u3-X39"}],"explanation":["이유 표현은 좋아지는 점을 설명해요.","‘……합시다.’는 제안하는 내용에 주로 써요.","‘요즘 ……하고 있다.’는 문제 상황에 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_challenge#3','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C38',3,'error','auto','세 친구가 제안하는 글의 표현과 짜임에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X40','K4-2-u3-X62']::text[],false,'{"seq":3,"concept":"K4-2-u3-C38","difficulty":3,"kind":"error","stem":"세 친구가 제안하는 글의 표현과 짜임에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤: 제안하는 글의 표현은 정해져 있으니 외워서 모든 문장에 똑같이 넣어야 해.","correct":true,"mis_target":"K4-2-u3-X40"},{"t":"태오: 제시된 표현 말고도 문맥에 어울리는 표현을 골라 쓸 수 있어.","mis":"K4-2-u3-X40"},{"t":"리아: 제안이 여럿이면 제안마다 알맞은 이유를 따로 써도 돼.","mis":"K4-2-u3-X62"}],"explanation":["표현은 외우는 것이 아니라 상황에 맞게 골라 써요.","억지로 표현을 넣을 필요는 없어요.","제안이 여럿이면 각각 이유를 쓰거나 공통 이유를 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_challenge#4','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C35',3,'mc','auto','「줄넘기 급수제를 실시하면 어떨까요?」라는 제안이 알맞은 제안 내용인 까닭은 무엇인가요?',ARRAY['K4-2-u3-X34','K4-2-u3-X35']::text[],false,'{"seq":4,"concept":"K4-2-u3-C35","difficulty":3,"kind":"mc","stem":"「줄넘기 급수제를 실시하면 어떨까요?」라는 제안이 알맞은 제안 내용인 까닭은 무엇인가요?","options":[{"t":"건강 문제를 해결하는 데 도움이 되고, 줄넘기는 누구나 쉽게 할 수 있어 실천할 수 있기 때문","correct":true},{"t":"줄넘기를 잘하는 친구만 할 수 있기 때문","mis":"K4-2-u3-X34"},{"t":"체육 시간을 없애자는 제안이기 때문","mis":"K4-2-u3-X35"},{"t":"건강과 상관없는 제안이기 때문","mis":"K4-2-u3-X35"}],"explanation":["문제 상황은 초등학생의 건강 상태가 심각하다는 것이에요.","줄넘기 급수제는 그 문제를 바로 해결하는 데 도움이 돼요.","누구나 할 수 있어 실천할 수도 있어요."],"asset":{"type":"passage","lines":["요즈음 초등학생의 건강 상태가 심각합니다.","(간추림) 체육 시간에 운동장 한 바퀴를 달리지 못하는 친구도 꽤 많습니다.","줄넘기 급수제를 실시하면 어떨까요?","건강을 지키기 위해 운동은 꼭 필요한데, 줄넘기는 누구나 쉽게 할 수 있는 운동입니다.","(간추림) 급수제를 하면 높은 등급에 오르려고 목표를 정해 더 열심히 할 것이다."],"title":"제안하는 글 「줄넘기 급수제로 건강을 지켜요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_challenge#5','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C40',3,'mc','auto','「월요일 방송 조회 시간에 분실물 찾기 안내 방송을 하면 좋겠습니다.」라는 제안이 방송 시간이 부족해 받아들여지지 않았어요. 가장 알맞은 다음 행동은 무엇인가요?',ARRAY['K4-2-u3-X41','K4-2-u3-X30']::text[],false,'{"seq":5,"concept":"K4-2-u3-C40","difficulty":3,"kind":"mc","stem":"「월요일 방송 조회 시간에 분실물 찾기 안내 방송을 하면 좋겠습니다.」라는 제안이 방송 시간이 부족해 받아들여지지 않았어요. 가장 알맞은 다음 행동은 무엇인가요?","options":[{"t":"받아들여지지 않은 까닭을 살펴, 게시판에 분실물 사진을 붙이는 것처럼 다른 방법을 제안한다","correct":true},{"t":"제안을 포기하고 분실물을 그냥 둔다","mis":"K4-2-u3-X41"},{"t":"똑같은 글을 매일 다시 낸다","mis":"K4-2-u3-X41"},{"t":"제안하는 글은 원래 다 받아들여져야 한다고 따진다","mis":"K4-2-u3-X30"}],"explanation":["제안이 받아들여지지 않을 때에는 그 까닭이 있어요.","까닭을 살피면 바꿀 수 있는 다른 방법이 보여요.","미리 다른 방법을 생각해 두는 것도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_challenge#6','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C39',3,'mc','auto','제안하는 글의 마무리 부분으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X39','K4-2-u3-X31']::text[],false,'{"seq":6,"concept":"K4-2-u3-C39","difficulty":3,"kind":"mc","stem":"제안하는 글의 마무리 부분으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"바쁘시더라도 제 제안을 검토해 주시면 감사하겠습니다.","correct":true},{"t":"제 말대로 무조건 해 주세요.","mis":"K4-2-u3-X39"},{"t":"안 바꿔 주시면 정말 실망할 거예요.","mis":"K4-2-u3-X31"},{"t":"제가 원하는 대로만 해 주시면 됩니다.","mis":"K4-2-u3-X39"}],"explanation":["마무리에서는 제안을 다시 한번 예의 있게 강조해요.","무조건 반영하라고 요구하지 않아요.","상대를 배려하는 말로 끝맺어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_challenge#7','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C37',3,'mc','auto','연우가 글의 처음에 「저는 ○○초등학교 4학년 김연우라고 합니다.」라고 자신을 밝힌 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X30','K4-2-u3-X63']::text[],false,'{"seq":7,"concept":"K4-2-u3-C37","difficulty":3,"kind":"mc","stem":"연우가 글의 처음에 「저는 ○○초등학교 4학년 김연우라고 합니다.」라고 자신을 밝힌 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"누가 제안했는지 알면 의견을 더 믿을 수 있고 답변을 주고받을 수 있기 때문","correct":true},{"t":"이름을 밝히면 제안이 반드시 받아들여지기 때문","mis":"K4-2-u3-X30"},{"t":"제안하는 사람은 밝히지 않는 것이 예의이기 때문","mis":"K4-2-u3-X63"},{"t":"글자 수를 늘리려고","mis":"K4-2-u3-X63"}],"explanation":["제안하는 사람을 밝히면 의견을 더 믿을 수 있어요.","누가 제안했는지 알아야 답글도 보낼 수 있어요.","이름을 밝히는 만큼 예의 있는 표현을 써요."],"asset":{"type":"passage","lines":["가람어린이과학관 관장님, 안녕하세요? 저는 ○○초등학교 4학년 김연우라고 합니다.","가람어린이과학관에서는 재미있게 과학 원리를 체험할 수 있다고 하여","지난 주말 가족과 함께 방문했습니다.","그런데 과학관에는 비가 올 때 도시락이나 간식을 먹을 만한 공간이 없었습니다.","그래서 비가 그칠 때까지 기다려야 했습니다.","비나 눈이 오는 날뿐만 아니라 미세 먼지 농도가 높은 날에도","관람객들은 이러한 불편을 겪을 것입니다."],"title":"「도시락이나 간식 먹을 공간을 만들어 주세요」 앞부분 — 『국어』 134쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_challenge#8','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C39',4,'essay','teacher','다음 두 문장을 제안하는 글에 어울리게 예의 있는 표현으로 고쳐 쓰세요. ① 「급식이 맛이 없어요.」 ② 「왜 아직도 이렇게 하고 있나요? 너무 불편합니다.」','{}'::text[],false,'{"seq":8,"concept":"K4-2-u3-C39","difficulty":4,"kind":"essay","stem":"다음 두 문장을 제안하는 글에 어울리게 예의 있는 표현으로 고쳐 쓰세요. ① 「급식이 맛이 없어요.」 ② 「왜 아직도 이렇게 하고 있나요? 너무 불편합니다.」","answer_guide":{"answer":"예: ① 급식의 맛과 메뉴가 다양해지면 학생들이 더 잘 먹을 것 같습니다. ② 학생들의 의견을 반영하여 검토해 주시면 감사하겠습니다. 조금만 바뀐다면 모두에게 도움이 될 것 같아 이렇게 제안합니다.","scoring_points":["①을 불만 대신 바라는 점과 좋아지는 점으로 고쳤는가","②를 탓하는 말 대신 예의 있게 부탁하는 말로 고쳤는가","두 문장 모두 강요하지 않는 표현을 썼는가"]},"explanation":["불만을 늘어놓으면 읽는 사람이 받아들이고 싶지 않아요.","바라는 점을 내놓고 좋아지는 점을 함께 써요.","상대를 배려하는 표현을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_challenge#9','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C34',4,'essay','teacher','연우가 제안 대상을 과학관 관장님으로 정한 덕분에 제안하는 내용이 어떻게 구체적이 되었는지 쓰고, 만약 친구에게 이 글을 썼다면 어떤 점이 달라졌을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u3-C34","difficulty":4,"kind":"essay","stem":"연우가 제안 대상을 과학관 관장님으로 정한 덕분에 제안하는 내용이 어떻게 구체적이 되었는지 쓰고, 만약 친구에게 이 글을 썼다면 어떤 점이 달라졌을지 쓰세요.","answer_guide":{"answer":"예: 관장님은 과학관의 공간을 바꿀 수 있는 분이라 ‘도시락이나 간식을 먹을 공간을 만들어 주세요’처럼 실제로 바꿀 일을 분명하게 제안할 수 있었다. 친구에게 썼다면 친구는 공간을 만들 수 없어서 문제가 해결되지 않았을 것이다.","scoring_points":["관장님이 공간 변경을 결정할 수 있는 분임을 썼는가","대상이 분명해져 제안 내용이 구체적이 되었음을 썼는가","친구에게 썼다면 해결되기 어렵다는 점을 썼는가"]},"explanation":["제안하는 글은 대상이 정해져 있는 글이에요.","대상을 분명히 하면 무엇을 해 달라고 할지 또렷해져요.","바꿀 수 없는 사람에게 쓰면 문제가 풀리지 않아요."],"asset":{"type":"passage","lines":["가람어린이과학관 관장님, 안녕하세요? 저는 ○○초등학교 4학년 김연우라고 합니다.","가람어린이과학관에서는 재미있게 과학 원리를 체험할 수 있다고 하여","지난 주말 가족과 함께 방문했습니다.","그런데 과학관에는 비가 올 때 도시락이나 간식을 먹을 만한 공간이 없었습니다.","그래서 비가 그칠 때까지 기다려야 했습니다.","비나 눈이 오는 날뿐만 아니라 미세 먼지 농도가 높은 날에도","관람객들은 이러한 불편을 겪을 것입니다."],"title":"「도시락이나 간식 먹을 공간을 만들어 주세요」 앞부분 — 『국어』 134쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L07_challenge#10','kor',4,2,'u3','L07','tb_g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C32',4,'match','auto','연우가 제안하는 글을 쓴 과정을 단계별로 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u3-C32","difficulty":4,"kind":"match","stem":"연우가 제안하는 글을 쓴 과정을 단계별로 알맞게 이으세요.","pairs":[{"l":"문제 상황 파악하기","r":"비가 올 때 도시락이나 간식을 먹을 공간이 없음"},{"l":"누구에게 제안할지 생각하기","r":"과학관의 공간을 바꿀 수 있는 관장님"},{"l":"제안하는 내용을 정하고 이유 설명하기","r":"먹을 공간 만들기 — 날씨와 상관없이 편하게 먹을 수 있음"},{"l":"제안하는 글 쓰기","r":"제목을 붙여 한 편의 글로 완성함"}],"mis":"K4-2-u3-X32","explanation":["연우는 일기에서 먼저 문제를 찾았어요.","그 문제를 바꿀 수 있는 관장님을 대상으로 정했어요.","제안과 이유를 정한 뒤 한 편의 글로 썼어요."],"asset":{"type":"passage","lines":["오늘은 가족과 가람어린이과학관에 다녀왔다.","(간추림) 공룡알 화석과 자전거로 전기를 만드는 체험이 재미있었다.","기다리던 점심시간이 되어 음식을 먹을 공간을 찾아보았다.","실내에는 마땅한 장소가 없어서 바깥 쉼터에서 먹기로 했다.","돗자리를 깔고 있는데 갑자기 소나기가 내렸다.","비가 그쳐서야 자리를 잡고 도시락과 간식을 먹을 수 있었다.","즐거운 하루였지만 점심시간에 조마조마했던 마음이 자꾸 떠오른다.","다른 사람들은 어떻게 점심을 먹었을까? 이 상황을 해결할 방법은 없을까?"],"title":"「연우의 일기」 — 『국어』 132쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_basic#1','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C42',1,'mc','auto','『국어』 136쪽 계획하기예요. 다음 가운데 제안하는 글로 해결하기에 알맞은 문제 상황은 무엇인가요?',ARRAY['K4-2-u3-X43','K4-2-u3-X37']::text[],false,'{"seq":1,"concept":"K4-2-u3-C42","difficulty":1,"kind":"mc","stem":"『국어』 136쪽 계획하기예요. 다음 가운데 제안하는 글로 해결하기에 알맞은 문제 상황은 무엇인가요?","options":[{"t":"학교 도서관에서 오랜 시간 책을 볼 때 의자가 불편하다","correct":true},{"t":"내일 비가 올까 봐 걱정된다","mis":"K4-2-u3-X43"},{"t":"짝과 말다툼을 해서 속상하다","mis":"K4-2-u3-X43"},{"t":"내가 좋아하는 놀이를 친구가 싫어한다","mis":"K4-2-u3-X37"}],"explanation":["제안하는 글은 바꿀 수 있는 분께 해결 방법을 제안하는 글이에요.","도서관 의자는 교장 선생님이나 사서 선생님께 제안할 수 있어요.","날씨나 두 사람 사이의 일은 제안하는 글로 풀기 어려워요."],"asset":{"type":"passage","lines":["㉮ [그림] 급식실에서 뛰어다니던 두 친구가 부딪힐 뻔하다.","㉯ [그림] 윗집에서 쿵쿵 울리는 소리에 아이가 귀를 막고 있다.","예시 — 문제 상황: 학교 도서관에서 오랜 시간 책을 볼 때 불편하다.","제안하는 대상: 교장 선생님, 사서 선생님","제안하는 내용: 편안하고 다양한 의자로 바꾸기","제안하는 이유: 긴 시간 책을 편안하게 읽고 싶다."],"title":"『국어』 136쪽 계획하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_basic#2','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C41',1,'mc','auto','『국어』 136쪽 의견과 이유 떠올리기예요. 「편안하고 다양한 의자로 바꾸기」라는 제안하는 내용과 짝이 되는 제안하는 이유는 무엇인가요?',ARRAY['K4-2-u3-X06','K4-2-u3-X26','K4-2-u3-X35']::text[],false,'{"seq":2,"concept":"K4-2-u3-C41","difficulty":1,"kind":"mc","stem":"『국어』 136쪽 의견과 이유 떠올리기예요. 「편안하고 다양한 의자로 바꾸기」라는 제안하는 내용과 짝이 되는 제안하는 이유는 무엇인가요?","options":[{"t":"긴 시간 책을 편안하게 읽을 수 있다","correct":true},{"t":"학교 도서관에서 오랜 시간 책을 볼 때 불편하다","mis":"K4-2-u3-X06"},{"t":"교장 선생님, 사서 선생님","mis":"K4-2-u3-X26"},{"t":"도서관을 아예 없애자","mis":"K4-2-u3-X35"}],"explanation":["제안하는 이유는 제안대로 하면 좋아지는 점이에요.","의자를 바꾸면 긴 시간 편안하게 책을 읽을 수 있어요.","불편하다는 것은 문제 상황, 선생님들은 제안하는 대상이에요."],"asset":{"type":"passage","lines":["㉮ [그림] 급식실에서 뛰어다니던 두 친구가 부딪힐 뻔하다.","㉯ [그림] 윗집에서 쿵쿵 울리는 소리에 아이가 귀를 막고 있다.","예시 — 문제 상황: 학교 도서관에서 오랜 시간 책을 볼 때 불편하다.","제안하는 대상: 교장 선생님, 사서 선생님","제안하는 내용: 편안하고 다양한 의자로 바꾸기","제안하는 이유: 긴 시간 책을 편안하게 읽고 싶다."],"title":"『국어』 136쪽 계획하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_basic#3','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C45',1,'mc','auto','『국어』 138쪽이에요. 「많은 친구가 운동장에서 공놀이를 즐깁니다.」는 어떤 짜임의 문장인가요?',ARRAY['K4-2-u3-X45','K4-2-u3-X47']::text[],false,'{"seq":3,"concept":"K4-2-u3-C45","difficulty":1,"kind":"mc","stem":"『국어』 138쪽이에요. 「많은 친구가 운동장에서 공놀이를 즐깁니다.」는 어떤 짜임의 문장인가요?","options":[{"t":"누가/무엇이 + 어찌하다","correct":true},{"t":"누가/무엇이 + 어떠하다","mis":"K4-2-u3-X45"},{"t":"누가/무엇이 + 무엇이다","mis":"K4-2-u3-X45"},{"t":"어찌하다 + 누가/무엇이","mis":"K4-2-u3-X47"}],"explanation":["‘많은 친구가’는 누가에 해당해요.","‘즐깁니다’는 움직임을 나타내는 어찌하다예요.","그래서 누가/무엇이 + 어찌하다 짜임이에요."],"asset":{"type":"passage","lines":["보기 — “많은 친구가 운동장에서 공놀이를 즐겁습니다.” (누가/무엇이 + 어떠하다)","→ 고친 문장 “많은 친구가 운동장에서 공놀이를 즐깁니다.” (누가/무엇이 + 어찌하다)","문제 — “관람객들이 가족과 행복한 추억입니다.” (누가/무엇이 + 무엇이다)","도움말 — 문장을 소리 내어 읽어 보면 어색한 부분을 쉽게 찾을 수 있어요."],"title":"『국어』 138쪽 — 문장의 짜임이 어색한 부분 고치기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_basic#4','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C46',1,'ox','auto','「관람객들이 가족과 행복한 추억입니다.」는 짜임이 자연스러운 문장이에요.',ARRAY['K4-2-u3-X46']::text[],false,'{"seq":4,"concept":"K4-2-u3-C46","difficulty":1,"kind":"ox","stem":"「관람객들이 가족과 행복한 추억입니다.」는 짜임이 자연스러운 문장이에요.","answer":"X","reason_options":[{"t":"‘관람객들이’와 ‘추억입니다’가 어울리지 않아 ‘추억을 만듭니다’로 고쳐야 해요.","correct":true},{"t":"문장이 짧지 않으니 어색해도 그대로 두면 돼요.","mis":"K4-2-u3-X46"}],"mis":"K4-2-u3-X46","explanation":["관람객들이 추억인 것은 아니에요.","‘누가/무엇이’와 뒷부분이 서로 어울려야 해요.","‘관람객들이 가족과 행복한 추억을 만듭니다.’로 고쳐요."],"asset":{"type":"passage","lines":["보기 — “많은 친구가 운동장에서 공놀이를 즐겁습니다.” (누가/무엇이 + 어떠하다)","→ 고친 문장 “많은 친구가 운동장에서 공놀이를 즐깁니다.” (누가/무엇이 + 어찌하다)","문제 — “관람객들이 가족과 행복한 추억입니다.” (누가/무엇이 + 무엇이다)","도움말 — 문장을 소리 내어 읽어 보면 어색한 부분을 쉽게 찾을 수 있어요."],"title":"『국어』 138쪽 — 문장의 짜임이 어색한 부분 고치기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_basic#5','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C46',2,'mc','auto','「많은 친구가 운동장에서 공놀이를 즐겁습니다.」를 바르게 고친 것은 무엇인가요?',ARRAY['K4-2-u3-X46','K4-2-u3-X45']::text[],false,'{"seq":5,"concept":"K4-2-u3-C46","difficulty":2,"kind":"mc","stem":"「많은 친구가 운동장에서 공놀이를 즐겁습니다.」를 바르게 고친 것은 무엇인가요?","options":[{"t":"많은 친구가 운동장에서 공놀이를 즐깁니다.","correct":true},{"t":"많은 친구가 운동장에서 즐겁습니다 공놀이를.","mis":"K4-2-u3-X46"},{"t":"많은 친구가 운동장에서 공놀이입니다.","mis":"K4-2-u3-X45"},{"t":"운동장에서 공놀이를 즐겁습니다.","mis":"K4-2-u3-X46"}],"explanation":["‘공놀이를’ 다음에는 움직임을 나타내는 말이 와야 자연스러워요.","‘즐겁습니다’는 모습을 나타내는 말이라 어울리지 않아요.","‘즐깁니다’로 고치면 누가 + 어찌하다 짜임이 돼요."],"asset":{"type":"passage","lines":["보기 — “많은 친구가 운동장에서 공놀이를 즐겁습니다.” (누가/무엇이 + 어떠하다)","→ 고친 문장 “많은 친구가 운동장에서 공놀이를 즐깁니다.” (누가/무엇이 + 어찌하다)","문제 — “관람객들이 가족과 행복한 추억입니다.” (누가/무엇이 + 무엇이다)","도움말 — 문장을 소리 내어 읽어 보면 어색한 부분을 쉽게 찾을 수 있어요."],"title":"『국어』 138쪽 — 문장의 짜임이 어색한 부분 고치기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_basic#6','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C47',2,'mc','auto','지산이의 글 「이렇게 하면 운동장을 둘러싼 다툼이 줄어들 것입니다.」에서 ‘누가/무엇이’에 해당하는 말은 무엇인가요?',ARRAY['K4-2-u3-X47']::text[],false,'{"seq":6,"concept":"K4-2-u3-C47","difficulty":2,"kind":"mc","stem":"지산이의 글 「이렇게 하면 운동장을 둘러싼 다툼이 줄어들 것입니다.」에서 ‘누가/무엇이’에 해당하는 말은 무엇인가요?","options":[{"t":"다툼이","correct":true},{"t":"운동장을","mis":"K4-2-u3-X47"},{"t":"이렇게","mis":"K4-2-u3-X47"},{"t":"사람만 올 수 있으니 이 문장에는 없다","mis":"K4-2-u3-X47"}],"explanation":["무엇이 줄어드는지 찾아보아요.","줄어드는 것은 ‘다툼’이에요.","‘누가/무엇이’ 자리에는 사람뿐 아니라 일이나 물건도 와요."],"asset":{"type":"passage","lines":["교장 선생님, 안녕하세요? 저는 4학년 최지산입니다.","요즘 우리 학교에 운동장을 사용하는 것 때문에 다툼이 많습니다.","특히 점심시간에 공놀이하는 친구들이 운동장을 모두 차지하고 있어","줄넘기나 다른 놀이를 하려는 친구들은 운동장을 사용하기가 어렵습니다.","요일별로 학년을 정하거나 운동장을 나누어 사용하는 방식과 같이","점심시간 운동장 사용 규칙을 만들면 좋겠습니다. 이렇게 하면 운동장을 둘러싼 다툼이 줄어들 것입니다.","그리고 더 많은 친구가 운동장에서 즐겁고 신나는 시간을 보낼 수 있을 것입니다.","바쁘시겠지만 제 제안을 잘 살펴봐 주시면 감사하겠습니다."],"title":"「운동장을 다 함께 사용하게 해 주세요」 — 『국어』 129쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_basic#7','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C48',2,'mc','auto','『국어』 139쪽 스스로 확인하기 항목에 들어 있는 것은 무엇인가요?',ARRAY['K4-2-u3-X42']::text[],false,'{"seq":7,"concept":"K4-2-u3-C48","difficulty":2,"kind":"mc","stem":"『국어』 139쪽 스스로 확인하기 항목에 들어 있는 것은 무엇인가요?","options":[{"t":"누구에게 제안하는지 밝혔나요?","correct":true},{"t":"글씨를 예쁘게 꾸몄나요?","mis":"K4-2-u3-X42"},{"t":"글이 친구 글보다 길어졌나요?","mis":"K4-2-u3-X42"},{"t":"친구 글과 똑같이 썼나요?","mis":"K4-2-u3-X42"}],"explanation":["제목, 대상, 문제 상황을 확인해요.","제안하는 내용과 이유, 알맞은 표현도 확인해요.","문장의 짜임이 어색하지 않은지도 살펴요."],"asset":{"type":"passage","lines":["제안하는 내용이 잘 드러나게 제목을 붙였나요?","누구에게 제안하는지 밝혔나요?","문제 상황을 구체적으로 썼나요?","제안하는 내용과 그 이유가 잘 드러났나요?","제안하는 글에 알맞은 표현을 사용했나요?","문장의 짜임이 어색하지 않게 문장을 썼나요?"],"title":"『국어』 139쪽 — 스스로 확인하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_basic#8','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C49',2,'mc','auto','『국어』 141쪽 보기예요. 우리 학교 친구들에게 제안하는 글을 전하는 방법을 바르게 묶은 것은 무엇인가요?',ARRAY['K4-2-u3-X48']::text[],false,'{"seq":8,"concept":"K4-2-u3-C49","difficulty":2,"kind":"mc","stem":"『국어』 141쪽 보기예요. 우리 학교 친구들에게 제안하는 글을 전하는 방법을 바르게 묶은 것은 무엇인가요?","options":[{"t":"전교 학생회에 안건 내기 · 학교 누리집에 올리기 · 허락을 받고 알림판에 붙이기","correct":true},{"t":"허락 없이 교장실 문에 붙이기 · 친구 신발장에 넣기","mis":"K4-2-u3-X48"},{"t":"아무에게도 보이지 않게 서랍에 넣어 두기","mis":"K4-2-u3-X48"},{"t":"허락 없이 아파트 엘리베이터에 붙이기","mis":"K4-2-u3-X48"}],"explanation":["글을 읽을 사람에 맞게 전하는 방법을 골라요.","학교 친구들에게는 학생회 안건, 누리집, 알림판이 알맞아요.","어디에 붙이든 허락을 받아야 해요."],"asset":{"type":"passage","lines":["교장 선생님 — 직접 방문하기 · 학교 누리집에 올리기 · 편지 쓰기","우리 학교 친구들 — 전교 학생회에 안건 내기 · 학교 누리집에 올리기","· 허락을 받고 알림판에 붙이기","안건: 토의하거나 조사해야 할 사실."],"title":"『국어』 141쪽 보기 — 제안하는 글을 전달하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_basic#9','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C44',2,'sa','auto','제안하는 글의 내용을 간략하게 구성할 때에는 무엇을 중심으로 짧게 적으면 좋은지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u3-C44","difficulty":2,"kind":"sa","stem":"제안하는 글의 내용을 간략하게 구성할 때에는 무엇을 중심으로 짧게 적으면 좋은지 쓰세요.","answer":["핵심 낱말","핵심낱말","핵심 단어"],"explanation":["글 전체를 미리 다 쓰면 쓰기가 힘들어져요.","핵심 낱말 중심으로 개요를 짧게 정리해요.","쓸 내용의 차례를 번호로 써도 좋아요."],"mis":"K4-2-u3-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_basic#10','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C43',3,'mc','auto','도서관 의자를 바꾸어 달라는 제안의 이유로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X37','K4-2-u3-X38','K4-2-u3-X36']::text[],false,'{"seq":10,"concept":"K4-2-u3-C43","difficulty":3,"kind":"mc","stem":"도서관 의자를 바꾸어 달라는 제안의 이유로 가장 알맞은 것은 무엇인가요?","options":[{"t":"도서관을 이용하는 많은 학생이 오랜 시간 편안하게 책을 읽을 수 있습니다.","correct":true},{"t":"제가 푹신한 의자를 좋아하기 때문입니다.","mis":"K4-2-u3-X37"},{"t":"다른 학교에는 다 좋은 의자가 있을 것 같습니다.","mis":"K4-2-u3-X38"},{"t":"왜냐하면 의자이기 때문입니다.","mis":"K4-2-u3-X36"}],"explanation":["이유는 개인적인 취향보다 여러 사람에게 좋은 점이 설득력 있어요.","확인하지 않은 짐작은 이유로 약해요.","‘왜냐하면’만 붙인다고 이유가 되지는 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_challenge#1','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C42',2,'mc','auto','『국어』 140쪽 사례 ㉮에서 문제 상황과 반영된 모습을 바르게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u3-X26','K4-2-u3-X35']::text[],false,'{"seq":1,"concept":"K4-2-u3-C42","difficulty":2,"kind":"mc","stem":"『국어』 140쪽 사례 ㉮에서 문제 상황과 반영된 모습을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"후문 앞에 횡단보도가 없어 건너기 위험함 → 후문 앞에 횡단보도가 생김","correct":true},{"t":"바다거북이 나오는 영상 → 후문 앞에 횡단보도가 생김","mis":"K4-2-u3-X26"},{"t":"후문 앞에 횡단보도가 없음 → 빨대 없는 음료가 나옴","mis":"K4-2-u3-X26"},{"t":"차가 너무 느림 → 차가 더 빨리 다니게 됨","mis":"K4-2-u3-X35"}],"explanation":["㉮의 친구는 학교 후문 앞에 횡단보도가 필요하다고 제안했어요.","제안에 따라 횡단보도를 설치하기로 했어요.","빨대는 ㉯ 사례의 이야기예요."],"asset":{"type":"passage","lines":["㉮ 문제 상황 — [그림] 학교 후문 앞 찻길에 횡단보도가 없다.","㉮ 제안 — “학교 후문 앞에 횡단보도가 필요합니다.”","㉮ 제안 결과 — “여러분의 제안에 따라 학교 후문 앞에 횡단보도를 설치하기로 했습니다.”","㉯ 문제 상황 — [그림] 교실 화면에 바다거북이 나오는 영상","㉯ 제안 — “음료에 플라스틱 빨대를 붙이지 않으면 어떨까요?”","㉯ 제안 결과 — “우리 회사는 앞으로 여러분의 제안을 반영하겠습니다.”"],"title":"『국어』 140쪽 — 제안이 반영된 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_challenge#2','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C41',2,'mc','auto','『국어』 140쪽 사례 ㉯에서 친구가 음료 회사에 제안한 내용은 무엇인가요?',ARRAY['K4-2-u3-X06','K4-2-u3-X35']::text[],false,'{"seq":2,"concept":"K4-2-u3-C41","difficulty":2,"kind":"mc","stem":"『국어』 140쪽 사례 ㉯에서 친구가 음료 회사에 제안한 내용은 무엇인가요?","options":[{"t":"“음료에 플라스틱 빨대를 붙이지 않으면 어떨까요?”","correct":true},{"t":"“학교 후문 앞에 횡단보도가 필요합니다.”","mis":"K4-2-u3-X06"},{"t":"“우리 회사는 앞으로 여러분의 제안을 반영하겠습니다.”","mis":"K4-2-u3-X06"},{"t":"“바다거북 영상을 더 많이 보여 주세요.”","mis":"K4-2-u3-X35"}],"explanation":["‘……면 어떨까요?’는 제안하는 내용에 쓰는 표현이에요.","회사의 말은 제안의 결과예요.","횡단보도는 ㉮ 사례의 제안이에요."],"asset":{"type":"passage","lines":["㉮ 문제 상황 — [그림] 학교 후문 앞 찻길에 횡단보도가 없다.","㉮ 제안 — “학교 후문 앞에 횡단보도가 필요합니다.”","㉮ 제안 결과 — “여러분의 제안에 따라 학교 후문 앞에 횡단보도를 설치하기로 했습니다.”","㉯ 문제 상황 — [그림] 교실 화면에 바다거북이 나오는 영상","㉯ 제안 — “음료에 플라스틱 빨대를 붙이지 않으면 어떨까요?”","㉯ 제안 결과 — “우리 회사는 앞으로 여러분의 제안을 반영하겠습니다.”"],"title":"『국어』 140쪽 — 제안이 반영된 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_challenge#3','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C47',3,'error','auto','세 친구가 문장에서 ‘누가/무엇이’를 찾았어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X47','K4-2-u3-X45']::text[],false,'{"seq":3,"concept":"K4-2-u3-C47","difficulty":3,"kind":"error","stem":"세 친구가 문장에서 ‘누가/무엇이’를 찾았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람: 「과학관에는 먹을 공간이 없었습니다.」에는 사람이 없으니 ‘누가/무엇이’가 없어.","correct":true,"mis_target":"K4-2-u3-X47"},{"t":"도원: 「다툼이 줄어들 것입니다.」에서는 ‘다툼이’가 ‘무엇이’야.","mis":"K4-2-u3-X45"},{"t":"채은: 「많은 친구가 공놀이를 즐깁니다.」에서는 ‘많은 친구가’가 ‘누가’야.","mis":"K4-2-u3-X45"}],"explanation":["‘누가/무엇이’ 자리에는 사람이 아닌 것도 와요.","「과학관에는 먹을 공간이 없었습니다.」에서는 ‘공간이’가 ‘무엇이’예요.","‘없었습니다’는 어떠하다에 해당해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_challenge#4','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C43',3,'mc','auto','「모두가 읽을 수 있는 간판을 만들어 주세요」를 쓴 학생들이 제안을 믿을 만하게 만들려고 한 일은 무엇인가요?',ARRAY['K4-2-u3-X38','K4-2-u3-X37','K4-2-u3-X36']::text[],false,'{"seq":4,"concept":"K4-2-u3-C43","difficulty":3,"kind":"mc","stem":"「모두가 읽을 수 있는 간판을 만들어 주세요」를 쓴 학생들이 제안을 믿을 만하게 만들려고 한 일은 무엇인가요?","options":[{"t":"가게 간판을 조사하고 설문 조사를 해 확인한 사실을 들었다","correct":true},{"t":"“다른 동네도 다 그럴 것 같다”는 짐작을 사실처럼 썼다","mis":"K4-2-u3-X38"},{"t":"외국어 간판이 마음에 안 든다는 취향만 썼다","mis":"K4-2-u3-X37"},{"t":"‘왜냐하면’을 여러 번 썼다","mis":"K4-2-u3-X36"}],"explanation":["학생들은 마을 가게 간판을 직접 조사했어요.","400명에게 설문 조사를 해 불편을 겪은 사람이 많다는 것을 확인했어요.","확인한 사실은 이유를 튼튼하게 해 줘요."],"asset":{"type":"passage","lines":["그래서 다른 나라 언어로 쓰여 있는 간판 귀퉁이에","한글로 표기하는 법을 만들어 주시면 좋겠습니다.","그러면 무엇을 파는지 알기 쉬울 것입니다.","(간추림) 학생들은 마을 가게 간판을 조사하고 400명에게 설문 조사를 했다.","(간추림) 세 명 중 두 명이 불편을 겪었다고 했고, 학생들의 편지는 실제 법안으로 이어졌다."],"title":"「모두가 읽을 수 있는 간판을 만들어 주세요」 — 4학년 학생들이 국회 의원께 보낸 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_challenge#5','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C44',3,'mc','auto','제안하는 글의 개요를 짤 때 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u3-X44','K4-2-u3-X42']::text[],false,'{"seq":5,"concept":"K4-2-u3-C44","difficulty":3,"kind":"mc","stem":"제안하는 글의 개요를 짤 때 알맞은 방법은 무엇인가요?","options":[{"t":"처음·가운데·끝에 쓸 내용을 핵심 낱말로 짧게 적고 번호로 차례를 정한다","correct":true},{"t":"개요에 글 전체를 미리 다 써 둔다","mis":"K4-2-u3-X44"},{"t":"개요 없이 떠오르는 대로 바로 쓴다","mis":"K4-2-u3-X44"},{"t":"제목만 정하면 개요는 필요 없다","mis":"K4-2-u3-X42"}],"explanation":["개요는 글의 뼈대예요.","핵심 낱말 중심으로 짧게 적어요.","쓸 내용의 차례를 미리 정하면 글이 흐트러지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_challenge#6','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C48',3,'mc','auto','고쳐쓰기를 하다가 친구의 제안이 내 제안보다 더 좋다고 느꼈을 때 어떻게 하면 좋을까요?',ARRAY['K4-2-u3-X23','K4-2-u3-X42']::text[],false,'{"seq":6,"concept":"K4-2-u3-C48","difficulty":3,"kind":"mc","stem":"고쳐쓰기를 하다가 친구의 제안이 내 제안보다 더 좋다고 느꼈을 때 어떻게 하면 좋을까요?","options":[{"t":"친구의 좋은 점을 받아들여 내 제안을 고쳐 더 발전시킨다","correct":true},{"t":"내 제안이니 끝까지 고집한다","mis":"K4-2-u3-X23"},{"t":"고쳐 쓰는 것은 지는 것이라 그대로 낸다","mis":"K4-2-u3-X23"},{"t":"친구 글을 그대로 베껴 낸다","mis":"K4-2-u3-X42"}],"explanation":["자신의 제안만 고집하지 않아요.","다른 사람의 좋은 생각을 받아들이면 제안이 더 나아져요.","베끼는 것이 아니라 내 글을 고쳐 발전시켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_challenge#7','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C42',3,'mc','auto','제안하는 글을 쓸 문제 상황을 찾는 태도로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X37','K4-2-u3-X43']::text[],false,'{"seq":7,"concept":"K4-2-u3-C42","difficulty":3,"kind":"mc","stem":"제안하는 글을 쓸 문제 상황을 찾는 태도로 가장 알맞은 것은 무엇인가요?","options":[{"t":"나만의 불편에서 나아가 학교, 이웃, 지역 사회에서 여러 사람이 겪는 문제를 찾는다","correct":true},{"t":"나 혼자만 불편한 일을 찾는다","mis":"K4-2-u3-X37"},{"t":"날씨처럼 바꿀 수 없는 일을 고른다","mis":"K4-2-u3-X43"},{"t":"친구와 다툰 일을 고른다","mis":"K4-2-u3-X43"}],"explanation":["주변을 넓게 보면 함께 풀어야 할 문제가 보여요.","여러 사람이 겪는 문제일수록 제안할 까닭이 분명해요.","더 나은 사회를 만드는 제안을 할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_challenge#8','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C41',4,'essay','teacher','우리 주변의 문제 상황을 하나 골라 문제 상황, 제안하는 대상, 제안하는 내용, 제안하는 이유가 드러나게 짧은 제안하는 글을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u3-C41","difficulty":4,"kind":"essay","stem":"우리 주변의 문제 상황을 하나 골라 문제 상황, 제안하는 대상, 제안하는 내용, 제안하는 이유가 드러나게 짧은 제안하는 글을 쓰세요.","answer_guide":{"answer":"예: 교장 선생님, 안녕하세요? 저는 4학년 ○○○입니다. 요즘 등하교 때 교문 앞이 너무 복잡해서 위험합니다. 학년마다 등하교 구역을 정하면 좋겠습니다. 왜냐하면 학생들이 한곳에 몰리지 않아 안전하게 다닐 수 있기 때문입니다. 제 제안을 검토해 주시면 감사하겠습니다.","scoring_points":["문제 상황을 구체적으로 썼는가","바꿀 수 있는 대상에게 실천할 수 있는 제안을 했는가","제안하는 이유를 알맞은 표현으로 썼는가"]},"explanation":["먼저 문제 상황을 구체적으로 써요.","바꿀 수 있는 대상에게 실천할 수 있는 제안을 해요.","‘……면 좋겠습니다’, ‘왜냐하면 …… 때문입니다’를 활용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_challenge#9','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C46',4,'essay','teacher','「관람객들이 가족과 행복한 추억입니다.」를 ‘누가/무엇이 + 어찌하다’ 짜임과 ‘누가/무엇이 + 어떠하다’ 짜임으로 각각 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u3-C46","difficulty":4,"kind":"essay","stem":"「관람객들이 가족과 행복한 추억입니다.」를 ‘누가/무엇이 + 어찌하다’ 짜임과 ‘누가/무엇이 + 어떠하다’ 짜임으로 각각 고쳐 쓰세요.","answer_guide":{"answer":"예: 어찌하다 — 관람객들이 가족과 행복한 추억을 만듭니다. / 어떠하다 — 관람객들이 가족과 함께 행복합니다.","scoring_points":["‘누가/무엇이 + 어찌하다’ 짜임으로 바르게 고쳤는가","‘누가/무엇이 + 어떠하다’ 짜임으로 바르게 고쳤는가","두 문장 모두 ‘관람객들이’와 뒷부분이 어울리는가"]},"explanation":["‘어찌하다’는 움직임, ‘어떠하다’는 모습이나 상태를 나타내요.","‘관람객들이’와 어울리는 말을 골라요.","소리 내어 읽어 어색하지 않은지 확인해요."],"asset":{"type":"passage","lines":["보기 — “많은 친구가 운동장에서 공놀이를 즐겁습니다.” (누가/무엇이 + 어떠하다)","→ 고친 문장 “많은 친구가 운동장에서 공놀이를 즐깁니다.” (누가/무엇이 + 어찌하다)","문제 — “관람객들이 가족과 행복한 추억입니다.” (누가/무엇이 + 무엇이다)","도움말 — 문장을 소리 내어 읽어 보면 어색한 부분을 쉽게 찾을 수 있어요."],"title":"『국어』 138쪽 — 문장의 짜임이 어색한 부분 고치기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L09_challenge#10','kor',4,2,'u3','L09','tb_g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C45',4,'mc','auto','세 문장의 짜임을 바르게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u3-X45']::text[],false,'{"seq":10,"concept":"K4-2-u3-C45","difficulty":4,"kind":"mc","stem":"세 문장의 짜임을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"「다툼이 줄어들 것입니다.」 어찌하다 · 「건강 상태가 심각합니다.」 어떠하다 · 「줄넘기는 누구나 할 수 있는 운동입니다.」 무엇이다","correct":true},{"t":"「다툼이 줄어들 것입니다.」 어떠하다 · 「건강 상태가 심각합니다.」 어찌하다 · 「줄넘기는 누구나 할 수 있는 운동입니다.」 무엇이다","mis":"K4-2-u3-X45"},{"t":"「다툼이 줄어들 것입니다.」 무엇이다 · 「건강 상태가 심각합니다.」 어떠하다 · 「줄넘기는 누구나 할 수 있는 운동입니다.」 어찌하다","mis":"K4-2-u3-X45"},{"t":"「다툼이 줄어들 것입니다.」 어찌하다 · 「건강 상태가 심각합니다.」 무엇이다 · 「줄넘기는 누구나 할 수 있는 운동입니다.」 어떠하다","mis":"K4-2-u3-X45"}],"explanation":["줄어든다는 움직임 — 어찌하다예요.","심각하다는 상태 — 어떠하다예요.","운동입니다는 무엇인지 — 무엇이다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_basic#1','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C50',1,'mc','auto','『국어』 142쪽 「붙임쪽지로 질문하며 토의하기」예요. 친구 의견 옆에 질문을 붙인 뒤, 질문을 받은 친구가 할 일은 무엇인가요?',ARRAY['K4-2-u3-X23','K4-2-u3-X12','K4-2-u3-X14']::text[],false,'{"seq":1,"concept":"K4-2-u3-C50","difficulty":1,"kind":"mc","stem":"『국어』 142쪽 「붙임쪽지로 질문하며 토의하기」예요. 친구 의견 옆에 질문을 붙인 뒤, 질문을 받은 친구가 할 일은 무엇인가요?","options":[{"t":"질문한 친구에게 가서 질문에 답해 준다","correct":true},{"t":"질문 쪽지를 떼어 버린다","mis":"K4-2-u3-X23"},{"t":"질문한 친구를 나무란다","mis":"K4-2-u3-X12"},{"t":"질문을 많이 받았으니 내 의견이 가장 좋다고 여긴다","mis":"K4-2-u3-X14"}],"explanation":["붙임쪽지 활동은 ①부터 ⑥까지 차례가 있어요.","④ 질문을 받은 친구는 질문한 친구에게 가서 답해 줘요.","그다음 가장 좋은 의견을 생각하고 우리 반의 방법을 결정해요."],"asset":{"type":"passage","lines":["어제 하굣길에 급식실 옆을 지나면서 많은 양의 음식물 쓰레기를 보았습니다.","우리가 남긴 음식물을 모아 놓은 것인데 생각했던 것보다 무척 많아서 놀랐습니다.","집에 와서 인터넷을 찾아보니 음식물 쓰레기를 처리할 때 비용이 많이 들고","온실가스가 배출되어 환경에 나쁘다고 합니다.","급식에서 음식을 남기지 않으려면 어떻게 해야 할까요?"],"title":"누리집 게시판 「급식에서 남긴 음식 문제를 어떻게 해결할까요?」 — 『국어』 142쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_basic#2','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C52',1,'mc','auto','『국어』 144쪽 예시예요. 「중앙 현관에 우산 대여소 설치하기」는 무엇에 해당하나요?',ARRAY['K4-2-u3-X26']::text[],false,'{"seq":2,"concept":"K4-2-u3-C52","difficulty":1,"kind":"mc","stem":"『국어』 144쪽 예시예요. 「중앙 현관에 우산 대여소 설치하기」는 무엇에 해당하나요?","options":[{"t":"제안하는 내용","correct":true},{"t":"문제 상황","mis":"K4-2-u3-X26"},{"t":"제안하는 이유","mis":"K4-2-u3-X26"},{"t":"제안하는 대상","mis":"K4-2-u3-X26"}],"explanation":["비를 맞고 집에 가는 친구가 많다는 것이 문제 상황이에요.","우산 대여소를 설치하자는 것이 제안하는 내용이에요.","비를 맞지 않고 집에 갈 수 있다는 것이 제안하는 이유예요."],"asset":{"type":"passage","lines":["문제 상황 — 비가 갑자기 오는 날 우산을 가져오지 못한 친구들이 비를 맞고 집에 가야 하는 경우가 많다.","제안하는 내용 — 중앙 현관에 우산 대여소 설치하기","제안하는 이유 — 친구들이 비를 맞지 않고 집에 갈 수 있다.","가족이 우산을 주려고 학교에 오지 않아도 된다."],"title":"『국어』 144쪽 — 전교 학생회에 낼 제안 정리하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_basic#3','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C56',1,'match','auto','『국어』 146쪽 2번이에요. 낱말 짝과 낱말 사이의 관계를 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u3-C56","difficulty":1,"kind":"match","stem":"『국어』 146쪽 2번이에요. 낱말 짝과 낱말 사이의 관계를 알맞게 이으세요.","pairs":[{"l":"뛰다 — 달리다","r":"뜻이 비슷한 관계"},{"l":"작다 — 크다","r":"뜻이 반대인 관계"},{"l":"물고기 — 고등어","r":"뜻을 포함하는 관계"}],"mis":"K4-2-u3-X53","explanation":["뛰다와 달리다는 뜻이 비슷해요.","작다와 크다는 뜻이 반대예요.","물고기는 고등어를 포함하는 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_basic#4','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C54',1,'blank','auto','『국어』 146쪽 1번이에요. 「여럿이 쓰는 물건은 사용을 하고 제자리에 두어야 한다.」에서 ‘사용을 하고’를 하나의 낱말로 바르게 바꾼 것은 무엇인가요?',ARRAY['K4-2-u3-X52','K4-2-u3-X51']::text[],false,'{"seq":4,"concept":"K4-2-u3-C54","difficulty":1,"kind":"blank","stem":"『국어』 146쪽 1번이에요. 「여럿이 쓰는 물건은 사용을 하고 제자리에 두어야 한다.」에서 ‘사용을 하고’를 하나의 낱말로 바르게 바꾼 것은 무엇인가요?","options":[{"t":"사용하고","correct":true},{"t":"사용 하고","mis":"K4-2-u3-X52"},{"t":"사용을하고","mis":"K4-2-u3-X51"}],"explanation":["‘이해를 하다’가 ‘이해하다’가 되듯이 바꾸어요.","두 낱말이 만나 하나의 낱말이 되면 붙여 써요.","그래서 ‘사용하고’로 써요."],"asset":{"type":"passage","lines":["이해를 하다 → 이해하다 · 힘을 쓰다 → 힘쓰다","○ 여럿이 쓰는 물건은 사용을 하고 제자리에 두어야 한다.","○ 책상을 들고 옮기니까 너무 무거워서 힘이 들었다.","○ 어린이들은 위험한 물건에 손을 대지 마세요."],"title":"『국어』 146쪽 기초 다지기 1","hi":["사용을 하고","힘이 들었다","손을 대지"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_basic#5','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C53',2,'mc','auto','전교 학생회에 안건으로 낼 제안을 고르는 기준으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X50']::text[],false,'{"seq":5,"concept":"K4-2-u3-C53","difficulty":2,"kind":"mc","stem":"전교 학생회에 안건으로 낼 제안을 고르는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"많은 친구가 겪는 불편을 해결하고, 실천할 수 있으며, 많은 친구에게 공감을 얻은 제안","correct":true},{"t":"발표 목소리가 가장 큰 친구의 제안","mis":"K4-2-u3-X50"},{"t":"우리 반에만 좋은 제안","mis":"K4-2-u3-X50"},{"t":"글자 수가 가장 적은 제안","mis":"K4-2-u3-X50"}],"explanation":["전교 학생회는 학교 전체의 문제를 다뤄요.","많은 친구에게 공감을 얻은 제안을 골라요.","목소리 크기로 고르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_basic#6','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C54',2,'sa','auto','『국어』 146쪽 1번 「어린이들은 위험한 물건에 손을 대지 마세요.」에서 ‘손을 대지’를 하나의 낱말로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u3-C54","difficulty":2,"kind":"sa","stem":"『국어』 146쪽 1번 「어린이들은 위험한 물건에 손을 대지 마세요.」에서 ‘손을 대지’를 하나의 낱말로 바꾸어 쓰세요.","answer":["손대지"],"explanation":["‘손을 대다’가 하나의 낱말이 되면 ‘손대다’예요.","하나의 낱말은 붙여 써요.","그래서 ‘손대지’로 써요."],"asset":{"type":"passage","lines":["이해를 하다 → 이해하다 · 힘을 쓰다 → 힘쓰다","○ 여럿이 쓰는 물건은 사용을 하고 제자리에 두어야 한다.","○ 책상을 들고 옮기니까 너무 무거워서 힘이 들었다.","○ 어린이들은 위험한 물건에 손을 대지 마세요."],"title":"『국어』 146쪽 기초 다지기 1","hi":["사용을 하고","힘이 들었다","손을 대지"]},"mis":"K4-2-u3-X52"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_basic#7','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C57',2,'mc','auto','한 낱말의 뜻이 비슷한 말이나 반대말에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X54','K4-2-u3-X53']::text[],false,'{"seq":7,"concept":"K4-2-u3-C57","difficulty":2,"kind":"mc","stem":"한 낱말의 뜻이 비슷한 말이나 반대말에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"‘예쁘다’와 뜻이 비슷한 말에 ‘곱다’, ‘아름답다’가 있듯이 한 낱말에도 여러 개가 있을 수 있다","correct":true},{"t":"한 낱말의 반대말은 언제나 하나뿐이다","mis":"K4-2-u3-X54"},{"t":"뜻이 비슷한 말은 소리도 비슷해야 한다","mis":"K4-2-u3-X53"},{"t":"뜻이 비슷한 낱말은 쓰이는 상황도 언제나 똑같다","mis":"K4-2-u3-X53"}],"explanation":["한 낱말에는 비슷한 말이나 반대말이 여러 개 있을 수 있어요.","‘기쁘다’도 ‘즐겁다, 신나다, 행복하다’처럼 여러 낱말과 뜻이 비슷해요.","비슷한 말이라도 쓰이는 상황은 조금씩 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_basic#8','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C58',2,'mc','auto','『국어』 147쪽이에요. 겹받침 ㄺ이 들어간 낱말을 바르게 쓴 것끼리 묶은 것은 무엇인가요?',ARRAY['K4-2-u3-X55']::text[],false,'{"seq":8,"concept":"K4-2-u3-C58","difficulty":2,"kind":"mc","stem":"『국어』 147쪽이에요. 겹받침 ㄺ이 들어간 낱말을 바르게 쓴 것끼리 묶은 것은 무엇인가요?","options":[{"t":"밝기 · 읽다 · 까닭 · 찰흙","correct":true},{"t":"밝기 · 익다 · 까닥 · 찰흙","mis":"K4-2-u3-X55"},{"t":"박기 · 읽다 · 까닭 · 찰흑","mis":"K4-2-u3-X55"},{"t":"밝기 · 잃다 · 까닭 · 찰흙","mis":"K4-2-u3-X55"}],"explanation":["밝기, 읽다, 까닭, 찰흙에는 모두 ㄺ 받침이 있어요.","ㄹ과 ㄱ을 받침 자리에 나란히 써요.","ㄱ이나 ㄹ 하나만 쓰면 다른 말이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_basic#9','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C51',2,'ox','auto','급식에서 음식을 남기지 않으려고 아예 음식을 받지 않기로 하면 문제가 해결된 거예요.',ARRAY['K4-2-u3-X49']::text[],false,'{"seq":9,"concept":"K4-2-u3-C51","difficulty":2,"kind":"ox","stem":"급식에서 음식을 남기지 않으려고 아예 음식을 받지 않기로 하면 문제가 해결된 거예요.","answer":"X","reason_options":[{"t":"남는 음식은 없어져도 골고루 먹으며 건강하게 지내는 바라는 모습을 이루지 못하니 해결이 아니에요.","correct":true},{"t":"남는 음식만 없어지면 어떤 방법이든 해결이에요.","mis":"K4-2-u3-X49"}],"mis":"K4-2-u3-X49","explanation":["게시판 글의 문제는 남긴 음식이 많아 환경에 나쁘다는 것이에요.","음식을 받지 않으면 다른 문제가 생겨요.","먹을 만큼 받아 다 먹는 것처럼 바라는 모습을 이루어야 해요."],"asset":{"type":"passage","lines":["어제 하굣길에 급식실 옆을 지나면서 많은 양의 음식물 쓰레기를 보았습니다.","우리가 남긴 음식물을 모아 놓은 것인데 생각했던 것보다 무척 많아서 놀랐습니다.","집에 와서 인터넷을 찾아보니 음식물 쓰레기를 처리할 때 비용이 많이 들고","온실가스가 배출되어 환경에 나쁘다고 합니다.","급식에서 음식을 남기지 않으려면 어떻게 해야 할까요?"],"title":"누리집 게시판 「급식에서 남긴 음식 문제를 어떻게 해결할까요?」 — 『국어』 142쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_basic#10','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C55',3,'mc','auto','『국어』 147쪽 문장 「규칙을 정해서 꼭 필요할 때만 휴대 전화를 사용합시다!」에서 ‘규칙을 정해서’의 띄어쓰기에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X51','K4-2-u3-X52']::text[],false,'{"seq":10,"concept":"K4-2-u3-C55","difficulty":3,"kind":"mc","stem":"『국어』 147쪽 문장 「규칙을 정해서 꼭 필요할 때만 휴대 전화를 사용합시다!」에서 ‘규칙을 정해서’의 띄어쓰기에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"‘규칙을 정하다’는 하나의 낱말이 된 것이 아니므로 띄어 쓴다","correct":true},{"t":"두 낱말이 이어졌으니 ‘규칙정해서’로 붙여 써야 한다","mis":"K4-2-u3-X51"},{"t":"‘사용을 하고’를 ‘사용하고’로 쓰듯 언제나 붙여 쓴다","mis":"K4-2-u3-X51"},{"t":"‘정해서’를 ‘정 해서’로 띄어 써야 한다","mis":"K4-2-u3-X52"}],"explanation":["하나의 낱말이 된 말만 붙여 써요.","‘규칙을 정하다’는 두 낱말이 그대로 있어요.","이어져 있다고 모두 붙여 쓰는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_challenge#1','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C56',2,'mc','auto','‘부지런하다’와 뜻이 반대인 관계의 낱말은 무엇인가요?',ARRAY['K4-2-u3-X53']::text[],false,'{"seq":1,"concept":"K4-2-u3-C56","difficulty":2,"kind":"mc","stem":"‘부지런하다’와 뜻이 반대인 관계의 낱말은 무엇인가요?","options":[{"t":"게으르다","correct":true},{"t":"성실하다","mis":"K4-2-u3-X53"},{"t":"근면하다","mis":"K4-2-u3-X53"},{"t":"꼼꼼하다","mis":"K4-2-u3-X53"}],"explanation":["‘성실하다’, ‘근면하다’는 부지런하다와 뜻이 비슷해요.","부지런하다와 뜻이 반대인 낱말은 ‘게으르다’예요.","비슷한 관계와 반대인 관계를 구별해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_challenge#2','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C52',2,'mc','auto','『국어』 143~144쪽이에요. 전교 학생회에서 자신의 제안을 발표할 때 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u3-X26','K4-2-u3-X40']::text[],false,'{"seq":2,"concept":"K4-2-u3-C52","difficulty":2,"kind":"mc","stem":"『국어』 143~144쪽이에요. 전교 학생회에서 자신의 제안을 발표할 때 알맞은 방법은 무엇인가요?","options":[{"t":"문제 상황 → 제안하는 내용 → 제안하는 이유가 자연스럽게 이어지게 말한다","correct":true},{"t":"제안하는 이유만 크게 말한다","mis":"K4-2-u3-X26"},{"t":"문제 상황은 빼고 제안하는 내용만 말한다","mis":"K4-2-u3-X26"},{"t":"제안하는 글에 어울리는 표현은 쓰지 않는다","mis":"K4-2-u3-X40"}],"explanation":["발표 내용은 문제 상황, 제안하는 내용, 이유가 이어지게 구성해요.","제안하는 글에 자주 쓰는 표현을 떠올리면 좋아요.","그래야 듣는 친구들이 공감할 수 있어요."],"asset":{"type":"passage","lines":["문제 상황 — 비가 갑자기 오는 날 우산을 가져오지 못한 친구들이 비를 맞고 집에 가야 하는 경우가 많다.","제안하는 내용 — 중앙 현관에 우산 대여소 설치하기","제안하는 이유 — 친구들이 비를 맞지 않고 집에 갈 수 있다.","가족이 우산을 주려고 학교에 오지 않아도 된다."],"title":"『국어』 144쪽 — 전교 학생회에 낼 제안 정리하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_challenge#3','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C50',3,'mc','auto','급식 잔반 토의에서 친구가 「먹을 만큼만 담아서 다 먹자」는 의견을 붙였어요. 그 옆에 붙일 질문 쪽지로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X12','K4-2-u3-X13','K4-2-u3-X59']::text[],false,'{"seq":3,"concept":"K4-2-u3-C50","difficulty":3,"kind":"mc","stem":"급식 잔반 토의에서 친구가 「먹을 만큼만 담아서 다 먹자」는 의견을 붙였어요. 그 옆에 붙일 질문 쪽지로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“좋은 의견이에요. 그런데 먹을 만큼이 얼마인지 어떻게 알 수 있을까요?”","correct":true},{"t":"“이 쪽지는 누가 썼어요? 글씨가 이상해요.”","mis":"K4-2-u3-X12"},{"t":"“좋은 의견이에요. 그런데 붙임쪽지는 무슨 색이 좋을까요?”","mis":"K4-2-u3-X13"},{"t":"“질문 수를 채워야 하니 아무거나 물어볼게요.”","mis":"K4-2-u3-X59"}],"explanation":["질문 쪽지는 의견을 실천할 때의 어려움을 물어요.","존중하는 말과 함께 물으면 친구가 기분 좋게 답해요.","쪽지 색이나 글씨는 의견과 상관없어요."],"asset":{"type":"passage","lines":["어제 하굣길에 급식실 옆을 지나면서 많은 양의 음식물 쓰레기를 보았습니다.","우리가 남긴 음식물을 모아 놓은 것인데 생각했던 것보다 무척 많아서 놀랐습니다.","집에 와서 인터넷을 찾아보니 음식물 쓰레기를 처리할 때 비용이 많이 들고","온실가스가 배출되어 환경에 나쁘다고 합니다.","급식에서 음식을 남기지 않으려면 어떻게 해야 할까요?"],"title":"누리집 게시판 「급식에서 남긴 음식 문제를 어떻게 해결할까요?」 — 『국어』 142쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_challenge#4','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C51',3,'mc','auto','「우리 반 고민 해결 활동」에서 소금쟁이의 고민에 달린 두 댓글에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X49','K4-2-u3-X39','K4-2-u3-X37']::text[],false,'{"seq":4,"concept":"K4-2-u3-C51","difficulty":3,"kind":"mc","stem":"「우리 반 고민 해결 활동」에서 소금쟁이의 고민에 달린 두 댓글에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"고구마는 필요한 물건인지 따져 보자고, 곰돌이는 그래도 부족하면 이유를 준비해 부모님께 제안하는 글을 써 보자고 했다","correct":true},{"t":"두 댓글 모두 용돈을 아예 쓰지 말라고 했다","mis":"K4-2-u3-X49"},{"t":"곰돌이는 이유 없이 무조건 올려 달라고 조르라고 했다","mis":"K4-2-u3-X39"},{"t":"고구마는 친구들이 가진 물건을 따라 사라고 했다","mis":"K4-2-u3-X37"}],"explanation":["두 친구는 소금쟁이가 필요한 것을 살 수 있도록 도우려 했어요.","용돈을 아예 쓰지 않는 것은 바라는 모습이 아니에요.","곰돌이는 배운 대로 이유를 잘 준비하라고 했어요."],"asset":{"type":"speech","turns":[{"who":"소금쟁이","text":"“저는 용돈이 부족해요. 사고 싶은 것은 많지만 용돈이 부족해 살 수 없을 때가 많아 속상해요.”"},{"who":"고구마","text":"“혹시 필요하지 않은 물건을 충동적으로 사는 건가요? 물건을 살 때 나에게 필요한 물건인지 꼼꼼하게 따져 보면 좋겠습니다.”"},{"who":"곰돌이","text":"“꼭 필요한 물건만 사는 데도 용돈이 부족하다면 부모님께 용돈을 더 올려 달라고 제안하는 글을 써 보면 어떨까요? 우리가 수업에서 배운 대로 이유를 잘 준비해서요!”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_challenge#5','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C54',3,'error','auto','세 친구가 붙여 쓰기에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X52','K4-2-u3-X51']::text[],false,'{"seq":5,"concept":"K4-2-u3-C54","difficulty":3,"kind":"error","stem":"세 친구가 붙여 쓰기에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린: ‘손대지’는 두 낱말이 만났으니 ‘손 대지’로 띄어 써야 해.","correct":true,"mis_target":"K4-2-u3-X52"},{"t":"도하: ‘규칙을 정해서’는 하나의 낱말이 아니라서 띄어 써.","mis":"K4-2-u3-X51"},{"t":"예준: ‘힘이 들었다’를 하나의 낱말로 바꾸면 ‘힘들었다’야.","mis":"K4-2-u3-X52"}],"explanation":["두 낱말이 만나 하나의 낱말이 되면 붙여 써요.","‘손대다’는 하나의 낱말이라 ‘손대지’로 붙여 써요.","하나의 낱말이 아닌 ‘규칙을 정해서’는 띄어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_challenge#6','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C58',3,'mc','auto','『국어』 147쪽 글씨 쓰기에서 ‘긁다’를 바르게 쓰는 방법은 무엇인가요?',ARRAY['K4-2-u3-X55']::text[],false,'{"seq":6,"concept":"K4-2-u3-C58","difficulty":3,"kind":"mc","stem":"『국어』 147쪽 글씨 쓰기에서 ‘긁다’를 바르게 쓰는 방법은 무엇인가요?","options":[{"t":"ㄹ과 ㄱ을 받침 자리에 나란히, 한쪽이 너무 크지 않게 쓴다","correct":true},{"t":"ㄱ만 받침으로 써서 ‘극다’로 쓴다","mis":"K4-2-u3-X55"},{"t":"ㄹ만 받침으로 써서 ‘글다’로 쓴다","mis":"K4-2-u3-X55"},{"t":"ㄱ을 ㄹ보다 아주 크게 쓴다","mis":"K4-2-u3-X55"}],"explanation":["긁다의 받침은 겹받침 ㄺ이에요.","두 자음을 받침 칸 안에 나란히 써요.","글자 크기와 모양을 『국어』와 비슷하게 따라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_challenge#7','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C53',3,'mc','auto','「피라미드 토의」(짝 토의 → 모둠 토의 → 학급 토의)를 하면 좋은 점은 무엇인가요?',ARRAY['K4-2-u3-X50','K4-2-u3-X20','K4-2-u3-X61']::text[],false,'{"seq":7,"concept":"K4-2-u3-C53","difficulty":3,"kind":"mc","stem":"「피라미드 토의」(짝 토의 → 모둠 토의 → 학급 토의)를 하면 좋은 점은 무엇인가요?","options":[{"t":"몇몇 친구만 말하거나 다수결로만 정하지 않고, 의견의 장단점을 깊이 따져 볼 수 있다","correct":true},{"t":"목소리 큰 친구의 의견이 빨리 정해진다","mis":"K4-2-u3-X50"},{"t":"의견을 따지지 않고 손을 들어 빨리 정할 수 있다","mis":"K4-2-u3-X20"},{"t":"짝과 정한 의견은 끝까지 바꿀 수 없다","mis":"K4-2-u3-X61"}],"explanation":["짝끼리 두 의견을 견주어 하나를 고르거나 새 의견을 만들어요.","단계마다 검토할 의견이 적어 깊이 생각할 수 있어요.","모두가 참여하고 협력하게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_challenge#8','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C52',4,'essay','teacher','『국어』 143쪽 「전교 학생회에 안건 제안하기」예요. 많은 친구가 불편을 겪는 학교 문제를 하나 골라 문제 상황, 제안하는 내용, 제안하는 이유가 이어지는 발표 글을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u3-C52","difficulty":4,"kind":"essay","stem":"『국어』 143쪽 「전교 학생회에 안건 제안하기」예요. 많은 친구가 불편을 겪는 학교 문제를 하나 골라 문제 상황, 제안하는 내용, 제안하는 이유가 이어지는 발표 글을 쓰세요.","answer_guide":{"answer":"예: 비가 갑자기 오는 날 우산을 가져오지 못한 친구들이 비를 맞고 집에 가야 하는 경우가 많습니다. 그래서 중앙 현관에 우산 대여소를 설치하면 좋겠습니다. 그러면 친구들이 비를 맞지 않고 집에 갈 수 있고, 가족이 우산을 주려고 학교에 오지 않아도 됩니다.","scoring_points":["많은 친구가 겪는 문제 상황을 썼는가","실천할 수 있는 제안하는 내용을 썼는가","제안하는 이유를 이어 써서 자연스럽게 발표할 수 있게 했는가"]},"explanation":["먼저 많은 친구가 불편을 겪는 상황을 떠올려요.","그 문제를 해결할 제안을 이유와 함께 정리해요.","문제 상황 → 제안 → 이유가 자연스럽게 이어지게 말해요."],"asset":{"type":"passage","lines":["문제 상황 — 비가 갑자기 오는 날 우산을 가져오지 못한 친구들이 비를 맞고 집에 가야 하는 경우가 많다.","제안하는 내용 — 중앙 현관에 우산 대여소 설치하기","제안하는 이유 — 친구들이 비를 맞지 않고 집에 갈 수 있다.","가족이 우산을 주려고 학교에 오지 않아도 된다."],"title":"『국어』 144쪽 — 전교 학생회에 낼 제안 정리하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_challenge#9','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C57',4,'essay','teacher','‘기쁘다’와 뜻이 비슷한 낱말을 두 개 이상 쓰고, 한 낱말에 비슷한 말이나 반대말이 하나뿐이라고 생각하면 안 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u3-C57","difficulty":4,"kind":"essay","stem":"‘기쁘다’와 뜻이 비슷한 낱말을 두 개 이상 쓰고, 한 낱말에 비슷한 말이나 반대말이 하나뿐이라고 생각하면 안 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 즐겁다, 신나다, 행복하다. 한 낱말에도 뜻이 비슷한 말이나 반대인 말이 여러 개 있을 수 있고, 상황에 따라 알맞은 낱말을 골라 써야 하기 때문이다.","scoring_points":["‘기쁘다’와 뜻이 비슷한 낱말을 두 개 이상 바르게 썼는가","한 낱말에도 비슷한 말·반대말이 여러 개 있을 수 있음을 썼는가","상황에 맞게 골라 쓴다는 점을 썼는가"]},"explanation":["‘기쁘다’와 비슷한 말에는 ‘즐겁다, 신나다, 행복하다’가 있어요.","한 낱말에 비슷한 말이나 반대말이 여럿일 수 있어요.","여러 낱말을 알면 상황에 맞는 말을 고를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_L11_challenge#10','kor',4,2,'u3','L11','tb_g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C56',4,'mc','auto','『국어』 146쪽 2번의 낱말 관계를 바르게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u3-X53']::text[],false,'{"seq":10,"concept":"K4-2-u3-C56","difficulty":4,"kind":"mc","stem":"『국어』 146쪽 2번의 낱말 관계를 바르게 짝지은 것은 무엇인가요?","options":[{"t":"가끔-이따금(비슷한 관계) · 어둡다-밝다(반대인 관계) · 직업-요리사(포함하는 관계)","correct":true},{"t":"가끔-이따금(반대인 관계) · 어둡다-밝다(비슷한 관계) · 직업-요리사(포함하는 관계)","mis":"K4-2-u3-X53"},{"t":"가끔-이따금(비슷한 관계) · 어둡다-밝다(포함하는 관계) · 직업-요리사(반대인 관계)","mis":"K4-2-u3-X53"},{"t":"가끔-이따금(포함하는 관계) · 어둡다-밝다(반대인 관계) · 직업-요리사(비슷한 관계)","mis":"K4-2-u3-X53"}],"explanation":["가끔과 이따금은 뜻이 비슷해요.","어둡다와 밝다는 뜻이 반대예요.","직업은 요리사, 의사, 가수를 포함해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#1','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C17',1,'ox','auto','『국어』 145쪽 스스로 확인하기 ②예요. 「의견의 장점만 생각하며 의견을 마련한다.」는 색칠할 알맞은 설명이에요.',ARRAY['K4-2-u3-X10']::text[],false,'{"seq":1,"concept":"K4-2-u3-C17","difficulty":1,"kind":"ox","stem":"『국어』 145쪽 스스로 확인하기 ②예요. 「의견의 장점만 생각하며 의견을 마련한다.」는 색칠할 알맞은 설명이에요.","answer":"X","reason_options":[{"t":"의견을 마련할 때에는 단점도 함께 생각해야 해요.","correct":true},{"t":"좋은 의견은 장점만 생각하면 충분해요.","mis":"K4-2-u3-X10"}],"mis":"K4-2-u3-X10","explanation":["『국어』 126쪽에서 의견의 단점도 생각해 보라고 했어요.","장점만 보면 실천할 때 문제가 생길 수 있어요.","그래서 이 구름은 색칠하지 않아요."],"asset":{"type":"passage","lines":["① 문제 상황을 구체적으로 써야 한다.","② 의견의 장점만 생각하며 의견을 마련한다.","③ 친구의 기분을 고려하며 질문한다.","④ 제안하는 이유를 쓰지 않는다.","⑤ 누가 읽을 것인지 생각하지 않는다.","⑥ 주제에 알맞은 의견과 이유를 말한다."],"title":"『국어』 145쪽 스스로 확인하기 — 알맞은 설명을 모두 찾아 색칠하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#2','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C2',1,'mc','auto','토의에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X01']::text[],false,'{"seq":2,"concept":"K4-2-u3-C2","difficulty":1,"kind":"mc","stem":"토의에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"여럿이 의견을 모아 문제를 해결하는 방법을 찾는 것","correct":true},{"t":"한 사람이 해결 방법을 정해 알려 주는 것","mis":"K4-2-u3-X01"},{"t":"여럿이 모여 아무 이야기나 나누는 것","mis":"K4-2-u3-X01"},{"t":"누가 옳은지 이기고 지는 것을 가리는 것","mis":"K4-2-u3-X01"}],"explanation":["토의는 여러 사람이 함께 문제를 풀 방법을 찾는 거예요.","서로 의견을 내고 묻고 답하며 더 나은 방법을 찾아요.","이기고 지는 것을 가리는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#3','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C8',1,'mc','auto','토의 절차에서 가장 먼저 하는 단계는 무엇인가요?',ARRAY['K4-2-u3-X07']::text[],false,'{"seq":3,"concept":"K4-2-u3-C8","difficulty":1,"kind":"mc","stem":"토의 절차에서 가장 먼저 하는 단계는 무엇인가요?","options":[{"t":"토의 주제 정하기","correct":true},{"t":"의견 결정하기","mis":"K4-2-u3-X07"},{"t":"의견 모으기","mis":"K4-2-u3-X07"},{"t":"의견 마련하기","mis":"K4-2-u3-X07"}],"explanation":["무엇에 대해 토의할지부터 정해요.","그다음 의견을 마련하고 모아요.","마지막에 의견을 결정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#4','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C5',1,'blank','auto','『국어』 129쪽이에요. 「어떤 일에 대해 의견을 내는 것을 (     )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u3-X57']::text[],false,'{"seq":4,"concept":"K4-2-u3-C5","difficulty":1,"kind":"blank","stem":"『국어』 129쪽이에요. 「어떤 일에 대해 의견을 내는 것을 (     )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"제안","correct":true},{"t":"명령","mis":"K4-2-u3-X57"},{"t":"불평","mis":"K4-2-u3-X57"},{"t":"금지","mis":"K4-2-u3-X57"}],"explanation":["의견을 내놓는 것을 제안이라고 해요.","제안하는 내용을 넣어 쓴 글이 제안하는 글이에요.","시키거나 불평하는 것과는 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#5','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C27',1,'match','auto','제안하는 글의 세 부분과 그 부분에 쓰는 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u3-C27","difficulty":1,"kind":"match","stem":"제안하는 글의 세 부분과 그 부분에 쓰는 내용을 알맞게 이으세요.","pairs":[{"l":"문제 상황","r":"무엇이 불편한가"},{"l":"제안하는 내용","r":"무엇을 바라는가"},{"l":"제안하는 이유","r":"그러면 무엇이 좋아지는가"}],"mis":"K4-2-u3-X26","explanation":["무엇이 불편한가 — 문제 상황이에요.","무엇을 바라는가 — 제안하는 내용이에요.","그러면 무엇이 좋아지는가 — 제안하는 이유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#6','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C45',1,'mc','auto','「친구들이 비를 맞지 않고 집에 갈 수 있다.」는 어떤 짜임의 문장인가요?',ARRAY['K4-2-u3-X45']::text[],false,'{"seq":6,"concept":"K4-2-u3-C45","difficulty":1,"kind":"mc","stem":"「친구들이 비를 맞지 않고 집에 갈 수 있다.」는 어떤 짜임의 문장인가요?","options":[{"t":"누가/무엇이 + 어찌하다","correct":true},{"t":"누가/무엇이 + 어떠하다","mis":"K4-2-u3-X45"},{"t":"누가/무엇이 + 무엇이다","mis":"K4-2-u3-X45"},{"t":"어떠하다 + 무엇이다","mis":"K4-2-u3-X45"}],"explanation":["‘친구들이’는 누가에 해당해요.","‘갈 수 있다’는 움직임을 나타내요.","그래서 누가 + 어찌하다 짜임이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#7','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C54',1,'sa','auto','『국어』 146쪽 1번이에요. ‘힘을 쓰다’를 하나의 낱말로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K4-2-u3-C54","difficulty":1,"kind":"sa","stem":"『국어』 146쪽 1번이에요. ‘힘을 쓰다’를 하나의 낱말로 바꾸어 쓰세요.","answer":["힘쓰다"],"explanation":["두 낱말이 만나 하나의 낱말이 될 때가 있어요.","그럴 때에는 붙여 써요.","‘힘을 쓰다’는 ‘힘쓰다’가 돼요."],"mis":"K4-2-u3-X52"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#8','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C58',1,'mc','auto','『국어』 147쪽 글씨 쓰기 낱말 가운데 받침을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u3-X55']::text[],false,'{"seq":8,"concept":"K4-2-u3-C58","difficulty":1,"kind":"mc","stem":"『국어』 147쪽 글씨 쓰기 낱말 가운데 받침을 바르게 쓴 것은 무엇인가요?","options":[{"t":"묽다","correct":true},{"t":"묵다","mis":"K4-2-u3-X55"},{"t":"물다","mis":"K4-2-u3-X55"},{"t":"뭃다","mis":"K4-2-u3-X55"}],"explanation":["147쪽 낱말 ‘묽다’의 받침은 ㄺ이에요.","ㄹ과 ㄱ을 나란히 써요.","ㄱ이나 ㄹ 하나만 쓰면 다른 말이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#9','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C11',2,'mc','auto','『국어』 122쪽 5번 친구들의 말 가운데 토의할 때 질문하면 좋은 점을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u3-X11','K4-2-u3-X14']::text[],false,'{"seq":9,"concept":"K4-2-u3-C11","difficulty":2,"kind":"mc","stem":"『국어』 122쪽 5번 친구들의 말 가운데 토의할 때 질문하면 좋은 점을 바르게 말한 것은 무엇인가요?","options":[{"t":"친구의 질문을 생각하며 토의 주제에 더 알맞은 의견을 마련할 수 있어.","correct":true},{"t":"질문으로 친구의 의견을 꺾을 수 있어.","mis":"K4-2-u3-X11"},{"t":"질문을 하면 토의가 길어져서 좋아.","mis":"K4-2-u3-X11"},{"t":"질문을 많이 받은 의견이 가장 좋은 의견이야.","mis":"K4-2-u3-X14"}],"explanation":["질문을 생각하는 과정에서 의견이 더 나아져요.","답을 들으며 친구의 의견을 더 잘 알 수 있어요.","의견과 이유가 알맞은지도 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#10','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C15',2,'mc','auto','모둠 토의 주제를 고를 때 살펴야 할 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X02','K4-2-u3-X09']::text[],false,'{"seq":10,"concept":"K4-2-u3-C15","difficulty":2,"kind":"mc","stem":"모둠 토의 주제를 고를 때 살펴야 할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"우리 모두와 관련 있고, 여러 의견이 나올 수 있으며, 우리가 해결할 수 있는 문제인가","correct":true},{"t":"나 혼자에게만 중요한 문제인가","mis":"K4-2-u3-X02"},{"t":"답이 하나로 정해진 문제인가","mis":"K4-2-u3-X02"},{"t":"우리가 해결할 수 없을 만큼 큰 문제인가","mis":"K4-2-u3-X09"}],"explanation":["토의 주제는 모두와 관련 있어야 해요.","여러 의견이 나올 수 있어야 토의할 수 있어요.","우리가 해결할 수 있는 문제를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#11','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C18',2,'mc','auto','우현이네 학급에서 윤희의 기준 「쉽게 실천할 수 있는 의견」과 민준이의 기준 「단점보다 장점이 큰 의견」을 함께 쓴 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X17','K4-2-u3-X18','K4-2-u3-X20']::text[],false,'{"seq":11,"concept":"K4-2-u3-C18","difficulty":2,"kind":"mc","stem":"우현이네 학급에서 윤희의 기준 「쉽게 실천할 수 있는 의견」과 민준이의 기준 「단점보다 장점이 큰 의견」을 함께 쓴 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"쉬운지만 보지 않고 문제 해결에 도움이 되는지도 따져 보려고","correct":true},{"t":"가장 쉬운 의견이 언제나 가장 좋기 때문","mis":"K4-2-u3-X17"},{"t":"쉬운 의견은 모두 버리려고","mis":"K4-2-u3-X18"},{"t":"기준이 많으면 아무것도 고르지 않아도 돼서","mis":"K4-2-u3-X20"}],"explanation":["실천하기 쉬운지는 중요한 기준이에요.","장점이 단점보다 큰지도 함께 따져요.","여러 기준에 비추어 가장 알맞은 의견을 골라요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"“이제 의견을 결정해 보겠습니다. 어떤 기준으로 의견을 결정하면 좋겠습니까?”"},{"who":"최윤희","text":"“우리가 쉽게 실천할 수 있는 의견으로 결정하면 좋겠습니다.”"},{"who":"박민준","text":"“단점보다는 장점이 큰 의견으로 결정하면 좋겠습니다.”"},{"who":"사회자","text":"“…… 더 많은 학생이 정우현 학생의 의견을 골랐습니다.”"},{"who":"선생님","text":"“여러분이 서로 질문하고 답하며 더 좋은 의견을 만들었습니다. 그러면 다음 미술 시간에는 복도 벽에 붙일 안내문을 만들어 보겠습니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#12','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C28',2,'mc','auto','다음 가운데 제안하는 글로 볼 수 있는 것은 무엇인가요?',ARRAY['K4-2-u3-X27','K4-2-u3-X28']::text[],false,'{"seq":12,"concept":"K4-2-u3-C28","difficulty":2,"kind":"mc","stem":"다음 가운데 제안하는 글로 볼 수 있는 것은 무엇인가요?","options":[{"t":"학교 현관에 분실물 찾기 게시판을 만들면 좋겠습니다. 그러면 모든 학생이 잃어버린 물건을 확인할 수 있습니다.","correct":true},{"t":"물건을 잃어버리지 마세요.","mis":"K4-2-u3-X27"},{"t":"분실물 금지!","mis":"K4-2-u3-X28"},{"t":"물건 좀 잘 챙기세요.","mis":"K4-2-u3-X27"}],"explanation":["제안하는 글에는 해결 방법과 그 이유가 담겨요.","막기만 하는 말은 방법을 알려 주지 않아요.","‘~하세요’로 끝난다고 제안이 되는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#13','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C36',2,'mc','auto','『국어활동』 41쪽 「더 알아보기」예요. 제안하는 이유를 쓸 때 밝혀야 할 것은 무엇인가요?',ARRAY['K4-2-u3-X37','K4-2-u3-X36','K4-2-u3-X38']::text[],false,'{"seq":13,"concept":"K4-2-u3-C36","difficulty":2,"kind":"mc","stem":"『국어활동』 41쪽 「더 알아보기」예요. 제안하는 이유를 쓸 때 밝혀야 할 것은 무엇인가요?","options":[{"t":"제안하는 내용이 문제 상황에 도움이 되며 꼭 필요하다는 것","correct":true},{"t":"내가 그것을 좋아한다는 것","mis":"K4-2-u3-X37"},{"t":"‘왜냐하면’이라는 낱말","mis":"K4-2-u3-X36"},{"t":"확인하지 않은 소문","mis":"K4-2-u3-X38"}],"explanation":["이유는 제안이 왜 필요한지 보여 줘요.","문제 상황을 해결하는 데 도움이 된다는 것을 밝혀요.","내 취향이나 소문은 이유로 약해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#14','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C34',2,'mc','auto','「과자를 사면 양이 너무 적게 들어 있다」는 문제를 해결하려고 제안하는 글을 쓸 대상으로 알맞은 곳은 어디인가요?',ARRAY['K4-2-u3-X24']::text[],false,'{"seq":14,"concept":"K4-2-u3-C34","difficulty":2,"kind":"mc","stem":"「과자를 사면 양이 너무 적게 들어 있다」는 문제를 해결하려고 제안하는 글을 쓸 대상으로 알맞은 곳은 어디인가요?","options":[{"t":"과자 회사","correct":true},{"t":"담임 선생님","mis":"K4-2-u3-X24"},{"t":"아파트 주민","mis":"K4-2-u3-X24"},{"t":"학급 친구","mis":"K4-2-u3-X24"}],"explanation":["과자의 포장은 과자 회사가 정해요.","바꿀 수 있는 곳에 제안해야 해요.","중간 포장을 줄이거나 상자 크기를 조정해 달라고 제안할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#15','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C46',2,'mc','auto','『국어』 138쪽 도움말이에요. 짜임이 어색한 문장을 쉽게 찾는 방법은 무엇인가요?',ARRAY['K4-2-u3-X46','K4-2-u3-X47']::text[],false,'{"seq":15,"concept":"K4-2-u3-C46","difficulty":2,"kind":"mc","stem":"『국어』 138쪽 도움말이에요. 짜임이 어색한 문장을 쉽게 찾는 방법은 무엇인가요?","options":[{"t":"문장을 소리 내어 읽어 본다","correct":true},{"t":"문장을 거꾸로 읽는다","mis":"K4-2-u3-X46"},{"t":"문장을 짧게 잘라 버린다","mis":"K4-2-u3-X47"},{"t":"글씨를 크게 쓴다","mis":"K4-2-u3-X46"}],"explanation":["소리 내어 읽으면 어색한 부분이 귀에 들려요.","‘어떠하다’, ‘어찌하다’, ‘무엇이다’ 부분을 살펴봐요.","그리고 앞부분과 어울리게 고쳐요."],"asset":{"type":"passage","lines":["보기 — “많은 친구가 운동장에서 공놀이를 즐겁습니다.” (누가/무엇이 + 어떠하다)","→ 고친 문장 “많은 친구가 운동장에서 공놀이를 즐깁니다.” (누가/무엇이 + 어찌하다)","문제 — “관람객들이 가족과 행복한 추억입니다.” (누가/무엇이 + 무엇이다)","도움말 — 문장을 소리 내어 읽어 보면 어색한 부분을 쉽게 찾을 수 있어요."],"title":"『국어』 138쪽 — 문장의 짜임이 어색한 부분 고치기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#16','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C23',2,'mc','auto','구체적인 실천 계획에 들어가야 할 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X21']::text[],false,'{"seq":16,"concept":"K4-2-u3-C23","difficulty":2,"kind":"mc","stem":"구체적인 실천 계획에 들어가야 할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"언제, 누가, 무엇을 어떻게 할지","correct":true},{"t":"열심히 하겠다는 다짐만","mis":"K4-2-u3-X21"},{"t":"결정한 의견의 이름만","mis":"K4-2-u3-X21"},{"t":"하고 싶은 마음만","mis":"K4-2-u3-X21"}],"explanation":["실천 계획은 실제로 할 수 있게 구체적이어야 해요.","언제, 누가, 무엇을 할지 분명하게 써요.","다짐만으로는 실천하기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#17','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C6',3,'mc','auto','토의와 제안하는 글의 관계를 바르게 설명한 것은 무엇인가요?',ARRAY['K4-2-u3-X05','K4-2-u3-X04']::text[],false,'{"seq":17,"concept":"K4-2-u3-C6","difficulty":3,"kind":"mc","stem":"토의와 제안하는 글의 관계를 바르게 설명한 것은 무엇인가요?","options":[{"t":"둘 다 문제를 해결하는 방법이며, 토의에서 결정한 내용을 알리려고 제안하는 글을 쓸 수도 있다","correct":true},{"t":"토의를 하면 제안하는 글은 필요 없다","mis":"K4-2-u3-X05"},{"t":"문제가 생기면 언제나 제안하는 글부터 써야 한다","mis":"K4-2-u3-X04"},{"t":"토의와 제안하는 글은 서로 관계가 없다","mis":"K4-2-u3-X05"}],"explanation":["토의와 제안하는 글은 모두 문제 해결 방법이에요.","토의에서 정한 내용을 글로 알릴 수 있어요.","토의 과정은 제안하는 글을 계획하는 데에도 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#18','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C51',3,'mc','auto','『국어』 140쪽 사례 ㉮에서 제안이 반영되어 바라는 모습이 이루어진 장면은 무엇인가요?',ARRAY['K4-2-u3-X49']::text[],false,'{"seq":18,"concept":"K4-2-u3-C51","difficulty":3,"kind":"mc","stem":"『국어』 140쪽 사례 ㉮에서 제안이 반영되어 바라는 모습이 이루어진 장면은 무엇인가요?","options":[{"t":"학교 후문 앞에 횡단보도가 생겨 안전하게 건넌다","correct":true},{"t":"후문을 닫아 아무도 다니지 못하게 했다","mis":"K4-2-u3-X49"},{"t":"학생들이 후문을 피해 멀리 돌아서 다닌다","mis":"K4-2-u3-X49"},{"t":"후문 앞에 차가 다니지 못하게 길을 막았다","mis":"K4-2-u3-X49"}],"explanation":["바라는 모습은 학생들이 후문 앞을 안전하게 다니는 것이에요.","후문을 닫으면 위험은 없어도 바라는 모습까지 사라져요.","횡단보도가 생겨 바라는 모습이 이루어졌어요."],"asset":{"type":"passage","lines":["㉮ 문제 상황 — [그림] 학교 후문 앞 찻길에 횡단보도가 없다.","㉮ 제안 — “학교 후문 앞에 횡단보도가 필요합니다.”","㉮ 제안 결과 — “여러분의 제안에 따라 학교 후문 앞에 횡단보도를 설치하기로 했습니다.”","㉯ 문제 상황 — [그림] 교실 화면에 바다거북이 나오는 영상","㉯ 제안 — “음료에 플라스틱 빨대를 붙이지 않으면 어떨까요?”","㉯ 제안 결과 — “우리 회사는 앞으로 여러분의 제안을 반영하겠습니다.”"],"title":"『국어』 140쪽 — 제안이 반영된 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#19','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C24',3,'mc','auto','토의 활동 동료 평가지 3번에서 친구의 토의 참여 과정을 살펴보는 항목을 바르게 묶은 것은 무엇인가요?',ARRAY['K4-2-u3-X03','K4-2-u3-X60','K4-2-u3-X58']::text[],false,'{"seq":19,"concept":"K4-2-u3-C24","difficulty":3,"kind":"mc","stem":"토의 활동 동료 평가지 3번에서 친구의 토의 참여 과정을 살펴보는 항목을 바르게 묶은 것은 무엇인가요?","options":[{"t":"적극적으로 참여했는가 · 말차례를 지켰는가 · 친구의 말을 경청했는가","correct":true},{"t":"목소리가 컸는가 · 말을 빨리 했는가 · 많이 웃었는가","mis":"K4-2-u3-X03"},{"t":"내 의견에 찬성했는가 · 내 편을 들었는가 · 질문을 안 했는가","mis":"K4-2-u3-X60"},{"t":"결정을 따르지 않았는가 · 끼어들었는가","mis":"K4-2-u3-X58"}],"explanation":["동료 평가지는 친구의 참여 태도를 살펴요.","적극적인 참여, 말차례, 경청을 확인해요.","나와 친한지, 내 편인지는 평가 기준이 아니에요."],"asset":{"type":"passage","lines":["1 토의 주제에 대한 친구의 의견과 그 이유를 써 봅시다.","2 기준을 생각하며 친구의 의견을 평가해 봅시다.","(주제에 알맞은가 · 이유가 적절한가 · 모두가 실천할 수 있는가 · 단점도 생각했는가)","(  )의 의견은 문제 해결에 (적절하다. / 적절하지 않다.) 왜냐하면 …… 때문이다.","3 적극적으로 참여했나요? · 말차례를 지켰나요? · 친구의 말을 경청했나요?"],"title":"토의 활동 동료 평가지 — 문제 해결을 위한 토의 참여 평가하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#20','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C30',3,'mc','auto','『국어』 135쪽 답글을 읽은 친구가 「연우뿐만 아니라 다른 관람객에게도 도움이 되었어.」라고 했어요. 여기에서 알 수 있는 제안하는 글의 좋은 점은 무엇인가요?',ARRAY['K4-2-u3-X30','K4-2-u3-X31']::text[],false,'{"seq":20,"concept":"K4-2-u3-C30","difficulty":3,"kind":"mc","stem":"『국어』 135쪽 답글을 읽은 친구가 「연우뿐만 아니라 다른 관람객에게도 도움이 되었어.」라고 했어요. 여기에서 알 수 있는 제안하는 글의 좋은 점은 무엇인가요?","options":[{"t":"제안으로 여러 사람이 겪던 불편이 해결될 수 있다","correct":true},{"t":"제안하면 언제나 받아들여진다","mis":"K4-2-u3-X30"},{"t":"불만을 마음껏 쏟아 낼 수 있다","mis":"K4-2-u3-X31"},{"t":"글을 쓰면 직접 할 일이 없어진다","mis":"K4-2-u3-X30"}],"explanation":["연우의 제안으로 과학관에 먹을 공간이 생기게 되었어요.","다른 관람객들도 같은 불편을 겪지 않게 되었어요.","제안하는 글은 여러 사람의 생활을 바꿀 수 있어요."],"asset":{"type":"passage","lines":["가람어린이과학관을 찾아 주셔서 진심으로 감사합니다.","먼저, 식사 공간이 부족하여 불편을 겪으신 점에 대해 사과드립니다.","가람어린이과학관은 더 나은 관람 환경을 위해 여러 가지 방법을 논의했습니다.","전시 장소를 제외한 실내나 야외에서 관람객이 편하고 즐겁게","음식을 드실 수 있는 공간을 마련하겠습니다.","소중한 제안을 해 주셔서 감사합니다."],"title":"과학관 관장님의 답글 — 『국어』 135쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#21','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C32',3,'mc','auto','제안하는 글을 쓰는 과정에서 「문제 상황 파악하기」 바로 다음 단계는 무엇인가요?',ARRAY['K4-2-u3-X32','K4-2-u3-X48']::text[],false,'{"seq":21,"concept":"K4-2-u3-C32","difficulty":3,"kind":"mc","stem":"제안하는 글을 쓰는 과정에서 「문제 상황 파악하기」 바로 다음 단계는 무엇인가요?","options":[{"t":"누구에게 제안할지 생각하기","correct":true},{"t":"제안하는 글 쓰기","mis":"K4-2-u3-X32"},{"t":"제안하는 내용을 정하고 이유 설명하기","mis":"K4-2-u3-X32"},{"t":"글을 전달하기","mis":"K4-2-u3-X48"}],"explanation":["문제를 파악한 뒤 누구에게 제안할지 생각해요.","대상을 정하면 제안이 구체적이 돼요.","그다음 내용과 이유를 정하고 글을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#22','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C39',3,'mc','auto','「우리 학교는 할 게 없어요.」를 제안하는 글에 어울리게 고친 것은 무엇인가요?',ARRAY['K4-2-u3-X39','K4-2-u3-X31']::text[],false,'{"seq":22,"concept":"K4-2-u3-C39","difficulty":3,"kind":"mc","stem":"「우리 학교는 할 게 없어요.」를 제안하는 글에 어울리게 고친 것은 무엇인가요?","options":[{"t":"학교에서 즐길 수 있는 활동이 부족해 아쉽습니다. 다양한 놀이 시설이 있으면 좋겠습니다.","correct":true},{"t":"우리 학교는 정말 재미없어요. 당장 바꿔요.","mis":"K4-2-u3-X39"},{"t":"할 게 없는 학교라니 너무 실망이에요.","mis":"K4-2-u3-X31"},{"t":"놀이 시설을 무조건 만들어 주세요.","mis":"K4-2-u3-X39"}],"explanation":["불만을 늘어놓지 않아요.","바라는 점을 예의 있게 내놓아요.","강요하는 말 대신 ‘……면 좋겠습니다’를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#23','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C7',4,'mc','auto','『국어』 115쪽 임다솜의 글에서 글쓴이의 의견과 그 이유를 바르게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u3-X06','K4-2-u3-X35','K4-2-u3-X37']::text[],false,'{"seq":23,"concept":"K4-2-u3-C7","difficulty":4,"kind":"mc","stem":"『국어』 115쪽 임다솜의 글에서 글쓴이의 의견과 그 이유를 바르게 짝지은 것은 무엇인가요?","options":[{"t":"꼭 필요할 때만 휴대 전화를 사용하자 — 친구와 대화할 수 있고 안전하게 이동할 수 있다","correct":true},{"t":"휴대 전화를 쓰는 친구가 많다 — 사고가 날 수 있다","mis":"K4-2-u3-X06"},{"t":"휴대 전화를 모두 버리자 — 화면을 보지 않아도 된다","mis":"K4-2-u3-X35"},{"t":"규칙을 정하자 — 내가 휴대 전화를 싫어해서","mis":"K4-2-u3-X37"}],"explanation":["의견은 ‘……사용합시다!’에 있어요.","이유는 ‘그러면 ……할 수 있습니다’에 있어요.","휴대 전화를 쓰는 친구가 많다는 것은 문제 상황이에요."],"asset":{"type":"passage","lines":["○○초등학교 학생 여러분, 안녕하세요? 저는 4학년 임다솜이라고 합니다.","요즘 친구들과 함께 있을 때나 등하굣길에 휴대 전화를 사용하는 친구가 많습니다.","그런데 휴대 전화를 너무 많이 사용하면 친구들끼리 이야기하는 시간이 줄고,","주변을 신경 쓰지 못해 사고가 날 수 있습니다.","규칙을 정해서 꼭 필요할 때만 휴대 전화를 사용합시다!","그러면 휴대 전화 화면을 보는 대신에 친구와 대화할 수 있고,","걸을 때도 주변을 살피며 안전하게 이동할 수 있습니다.","더 즐겁고 안전한 학교생활을 위해 함께 노력하면 좋겠습니다. 감사합니다."],"title":"「휴대 전화는 꼭 필요할 때만 사용합시다」 — 『국어』 115쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#24','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C41',4,'essay','teacher','의견과 이유가 드러나게 제안하는 글을 쓰세요. 『국어』 136쪽 예시(학교 도서관에서 오랜 시간 책을 볼 때 불편하다)를 바탕으로 처음(인사·소개), 가운데(문제 상황·제안·이유), 끝(마무리)이 드러나게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u3-C41","difficulty":4,"kind":"essay","stem":"의견과 이유가 드러나게 제안하는 글을 쓰세요. 『국어』 136쪽 예시(학교 도서관에서 오랜 시간 책을 볼 때 불편하다)를 바탕으로 처음(인사·소개), 가운데(문제 상황·제안·이유), 끝(마무리)이 드러나게 쓰세요.","answer_guide":{"answer":"예: 교장 선생님, 안녕하세요? 저는 4학년 ○○○입니다. 요즘 학교 도서관에서 오랜 시간 책을 보면 의자가 딱딱해서 불편하다는 친구가 많습니다. 도서관 의자를 편안하고 다양한 의자로 바꾸어 주시면 좋겠습니다. 왜냐하면 많은 학생이 긴 시간 편안하게 책을 읽을 수 있기 때문입니다. 바쁘시겠지만 제 제안을 검토해 주시면 감사하겠습니다.","scoring_points":["문제 상황을 구체적으로 썼는가","제안하는 내용과 그 이유가 잘 드러나는가","처음·가운데·끝을 갖추고 알맞은 표현과 예의 있는 마무리를 썼는가"]},"explanation":["처음에는 대상에게 인사하고 자신을 밝혀요.","가운데에는 문제 상황, 제안하는 내용, 이유를 써요.","끝에는 예의 있게 제안을 다시 강조해요."],"asset":{"type":"passage","lines":["㉮ [그림] 급식실에서 뛰어다니던 두 친구가 부딪힐 뻔하다.","㉯ [그림] 윗집에서 쿵쿵 울리는 소리에 아이가 귀를 막고 있다.","예시 — 문제 상황: 학교 도서관에서 오랜 시간 책을 볼 때 불편하다.","제안하는 대상: 교장 선생님, 사서 선생님","제안하는 내용: 편안하고 다양한 의자로 바꾸기","제안하는 이유: 긴 시간 책을 편안하게 읽고 싶다."],"title":"『국어』 136쪽 계획하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_a#25','kor',4,2,'u3','','tb_g4_2_kor_u3_review_a','unit_review','K4-2-u3-C1',4,'essay','teacher','『국어』 145쪽 「생활 속으로」예요. 이 단원에서 배운 토의와 제안하는 글 쓰기를 생활 속에서 어떻게 실천할지 구체적인 계획을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u3-C1","difficulty":4,"kind":"essay","stem":"『국어』 145쪽 「생활 속으로」예요. 이 단원에서 배운 토의와 제안하는 글 쓰기를 생활 속에서 어떻게 실천할지 구체적인 계획을 쓰세요.","answer_guide":{"answer":"예: 우리 반 분실물 문제를 학급 회의에서 토의할 때 친구의 의견에 실천 방법을 묻는 질문을 하겠다. 토의에서 정한 분실물 찾기 게시판에 대해 교장 선생님께 의견과 이유가 드러나게 제안하는 글을 써서 학교 누리집에 올리겠다.","scoring_points":["토의할 때 실천할 내용(질문하기·주제에 알맞은 의견 등)을 썼는가","제안하는 글을 쓰는 실천 내용을 썼는가","언제·어디에서 할지 구체적으로 썼는가"]},"explanation":["토의할 때 필요한 질문을 생각해요.","제안하는 글을 읽고 내용과 이유를 찾아봐요.","우리 주변의 문제를 찾아 토의하고 제안해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#1','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C36',1,'ox','auto','스스로 확인하기 ④예요. 「제안하는 이유를 쓰지 않는다.」는 색칠할 알맞은 설명이에요.',ARRAY['K4-2-u3-X36']::text[],false,'{"seq":1,"concept":"K4-2-u3-C36","difficulty":1,"kind":"ox","stem":"스스로 확인하기 ④예요. 「제안하는 이유를 쓰지 않는다.」는 색칠할 알맞은 설명이에요.","answer":"X","reason_options":[{"t":"제안을 받아들이면 무엇이 좋아지는지 이유를 써야 설득할 수 있어요.","correct":true},{"t":"제안하는 내용만 분명하면 이유는 없어도 돼요.","mis":"K4-2-u3-X36"}],"mis":"K4-2-u3-X36","explanation":["제안하는 글은 문제 상황, 제안하는 내용, 제안하는 이유로 짜여요.","이유가 없으면 왜 바꿔야 하는지 알 수 없어요.","그래서 이 구름은 색칠하지 않아요."],"asset":{"type":"passage","lines":["① 문제 상황을 구체적으로 써야 한다.","② 의견의 장점만 생각하며 의견을 마련한다.","③ 친구의 기분을 고려하며 질문한다.","④ 제안하는 이유를 쓰지 않는다.","⑤ 누가 읽을 것인지 생각하지 않는다.","⑥ 주제에 알맞은 의견과 이유를 말한다."],"title":"『국어』 145쪽 스스로 확인하기 — 알맞은 설명을 모두 찾아 색칠하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#2','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C3',1,'mc','auto','다음 가운데 학급 회의에서 토의 주제로 정하기에 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X02']::text[],false,'{"seq":2,"concept":"K4-2-u3-C3","difficulty":1,"kind":"mc","stem":"다음 가운데 학급 회의에서 토의 주제로 정하기에 알맞은 것은 무엇인가요?","options":[{"t":"대청소 때 청소 구역과 담당 학생을 어떻게 정할까?","correct":true},{"t":"3 곱하기 4는 얼마일까?","mis":"K4-2-u3-X02"},{"t":"내 생일에 무엇을 먹고 싶을까?","mis":"K4-2-u3-X02"},{"t":"오늘은 며칠일까?","mis":"K4-2-u3-X02"}],"explanation":["청소 구역은 반 친구 모두와 관련 있어요.","여러 의견이 나올 수 있어 토의하기 좋아요.","답이 정해진 것이나 나 혼자의 일은 토의할 까닭이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#3','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C8',1,'mc','auto','「토의 주제에 알맞은 의견과 그 의견을 뒷받침하는 이유를 마련한다.」는 토의 절차의 어느 단계인가요?',ARRAY['K4-2-u3-X07']::text[],false,'{"seq":3,"concept":"K4-2-u3-C8","difficulty":1,"kind":"mc","stem":"「토의 주제에 알맞은 의견과 그 의견을 뒷받침하는 이유를 마련한다.」는 토의 절차의 어느 단계인가요?","options":[{"t":"의견 마련하기","correct":true},{"t":"토의 주제 정하기","mis":"K4-2-u3-X07"},{"t":"의견 모으기","mis":"K4-2-u3-X07"},{"t":"의견 결정하기","mis":"K4-2-u3-X07"}],"explanation":["주제가 정해지면 각자 의견과 이유를 준비해요.","이 단계가 의견 마련하기예요.","우현이네 사회자도 의견을 마련할 시간을 주었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#4','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C25',1,'mc','auto','제안하는 글을 누구에게 쓸지 정할 때 가장 먼저 생각할 것은 무엇인가요?',ARRAY['K4-2-u3-X24']::text[],false,'{"seq":4,"concept":"K4-2-u3-C25","difficulty":1,"kind":"mc","stem":"제안하는 글을 누구에게 쓸지 정할 때 가장 먼저 생각할 것은 무엇인가요?","options":[{"t":"그 문제를 정하거나 바꿀 수 있는 사람인가","correct":true},{"t":"나와 친한 사람인가","mis":"K4-2-u3-X24"},{"t":"글을 빨리 읽는 사람인가","mis":"K4-2-u3-X24"},{"t":"나이가 가장 많은 사람인가","mis":"K4-2-u3-X24"}],"explanation":["제안은 받아들여져야 문제가 해결돼요.","그래서 그 일을 정하거나 바꿀 수 있는 사람에게 해요.","친한지, 나이가 많은지는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#5','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C27',1,'blank','auto','조대웅의 글에서 「일주일에 하루를 정해 동네를 산책하면서 쓰레기를 줍는 날을 만들면 어떨까요?」는 제안하는 글의 어느 부분인가요?',ARRAY['K4-2-u3-X26']::text[],false,'{"seq":5,"concept":"K4-2-u3-C27","difficulty":1,"kind":"blank","stem":"조대웅의 글에서 「일주일에 하루를 정해 동네를 산책하면서 쓰레기를 줍는 날을 만들면 어떨까요?」는 제안하는 글의 어느 부분인가요?","options":[{"t":"제안하는 내용","correct":true},{"t":"문제 상황","mis":"K4-2-u3-X26"},{"t":"제안하는 이유","mis":"K4-2-u3-X26"}],"explanation":["‘……면 어떨까요?’로 바라는 것을 내놓았어요.","이것이 제안하는 내용이에요.","버려진 쓰레기가 많다는 것은 문제 상황이에요."],"asset":{"type":"passage","lines":["안녕하세요? 주민 여러분. 저는 ○○동에 사는 초등학교 4학년 조대웅입니다.","요즘 동네를 다니다 보면 여기저기에 버려진 쓰레기가 많습니다.","길가에 놓인 플라스틱 컵, 놀이터에 떨어진 과자 봉지, 화단 구석에 쌓인 휴지까지…….","일주일에 하루를 정해 동네를 산책하면서 쓰레기를 줍는 날을 만들면 어떨까요?","산책하면서 쓰레기를 하나씩 주우면 운동도 하면서 동네를 깨끗하게 만들 수 있어","일석이조의 효과를 볼 수 있기 때문입니다. 또 쓰레기를 길가에 버리지 않는 습관도 생길 것입니다.","주민 여러분, 작은 실천을 모아 우리 동네를 더 깨끗하고 살기 좋은 곳으로 만들어요!"],"title":"「깨끗한 동네를 만들기 위해 함께 노력해요」 — 『국어활동』 40쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#6','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C45',1,'mc','auto','「요즈음 초등학생의 건강 상태가 심각합니다.」는 어떤 짜임의 문장인가요?',ARRAY['K4-2-u3-X45']::text[],false,'{"seq":6,"concept":"K4-2-u3-C45","difficulty":1,"kind":"mc","stem":"「요즈음 초등학생의 건강 상태가 심각합니다.」는 어떤 짜임의 문장인가요?","options":[{"t":"누가/무엇이 + 어떠하다","correct":true},{"t":"누가/무엇이 + 어찌하다","mis":"K4-2-u3-X45"},{"t":"누가/무엇이 + 무엇이다","mis":"K4-2-u3-X45"},{"t":"무엇이다 + 어찌하다","mis":"K4-2-u3-X45"}],"explanation":["‘건강 상태가’는 무엇이에 해당해요.","‘심각합니다’는 상태를 나타내요.","그래서 무엇이 + 어떠하다 짜임이에요."],"asset":{"type":"passage","lines":["요즈음 초등학생의 건강 상태가 심각합니다.","(간추림) 체육 시간에 운동장 한 바퀴를 달리지 못하는 친구도 꽤 많습니다.","줄넘기 급수제를 실시하면 어떨까요?","건강을 지키기 위해 운동은 꼭 필요한데, 줄넘기는 누구나 쉽게 할 수 있는 운동입니다.","(간추림) 급수제를 하면 높은 등급에 오르려고 목표를 정해 더 열심히 할 것이다."],"title":"제안하는 글 「줄넘기 급수제로 건강을 지켜요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#7','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C54',1,'blank','auto','「책상을 들고 옮기니까 너무 무거워서 힘이 들었다.」에서 ‘힘이 들었다’를 하나의 낱말로 바르게 바꾼 것은 무엇인가요?',ARRAY['K4-2-u3-X52','K4-2-u3-X51']::text[],false,'{"seq":7,"concept":"K4-2-u3-C54","difficulty":1,"kind":"blank","stem":"「책상을 들고 옮기니까 너무 무거워서 힘이 들었다.」에서 ‘힘이 들었다’를 하나의 낱말로 바르게 바꾼 것은 무엇인가요?","options":[{"t":"힘들었다","correct":true},{"t":"힘 들었다","mis":"K4-2-u3-X52"},{"t":"힘이들었다","mis":"K4-2-u3-X51"}],"explanation":["‘힘이 들다’가 하나의 낱말이 되면 ‘힘들다’예요.","하나의 낱말은 붙여 써요.","그래서 ‘힘들었다’로 써요."],"asset":{"type":"passage","lines":["이해를 하다 → 이해하다 · 힘을 쓰다 → 힘쓰다","○ 여럿이 쓰는 물건은 사용을 하고 제자리에 두어야 한다.","○ 책상을 들고 옮기니까 너무 무거워서 힘이 들었다.","○ 어린이들은 위험한 물건에 손을 대지 마세요."],"title":"『국어』 146쪽 기초 다지기 1","hi":["사용을 하고","힘이 들었다","손을 대지"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#8','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C58',1,'sa','auto','『국어』 147쪽 낱말 ‘찰흙’에서 겹받침 ㄺ이 들어간 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u3-C58","difficulty":1,"kind":"sa","stem":"『국어』 147쪽 낱말 ‘찰흙’에서 겹받침 ㄺ이 들어간 글자를 쓰세요.","answer":["흙"],"explanation":["찰흙은 ‘찰’과 ‘흙’으로 되어 있어요.","‘흙’의 받침이 ㄺ이에요.","ㄹ과 ㄱ을 받침 칸 안에 나란히 써요."],"mis":"K4-2-u3-X55"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#9','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C14',2,'match','auto','토의에서 더 나은 의견을 만드는 질문과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u3-C14","difficulty":2,"kind":"match","stem":"토의에서 더 나은 의견을 만드는 질문과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"“의견을 실천하면 어떤 결과가 나타날까요?”","r":"결과를 묻는 질문"},{"l":"“의견을 실천했을 때 생기는 문제는 없나요?”","r":"단점을 묻는 질문"},{"l":"“어떻게 하면 그 의견을 우리가 실천할 수 있을까요?”","r":"실천 방법을 묻는 질문"}],"mis":"K4-2-u3-X15","explanation":["결과를 묻는 질문은 달라지는 점이나 장점을 물어요.","생기는 문제를 묻는 것은 단점 질문이에요.","방법을 묻는 것은 실천 방법 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#10','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C16',2,'mc','auto','「물건에 이름을 쓰지 않았기 때문입니다.」는 『국어』 125쪽 문제 상황 정리표의 어느 칸에 들어가나요?',ARRAY['K4-2-u3-X16','K4-2-u3-X21']::text[],false,'{"seq":10,"concept":"K4-2-u3-C16","difficulty":2,"kind":"mc","stem":"「물건에 이름을 쓰지 않았기 때문입니다.」는 『국어』 125쪽 문제 상황 정리표의 어느 칸에 들어가나요?","options":[{"t":"문제가 생긴 까닭","correct":true},{"t":"문제가 우리에게 주는 영향","mis":"K4-2-u3-X16"},{"t":"결정한 의견","mis":"K4-2-u3-X16"},{"t":"실천 계획","mis":"K4-2-u3-X21"}],"explanation":["‘……기 때문입니다’는 왜 그런지를 말해요.","물건 주인을 찾지 못하는 까닭이에요.","운동장이 지저분해 보이는 것은 영향이에요."],"asset":{"type":"passage","lines":["토의 주제 — 운동장이나 강당에 오랫동안 버려져 있는 물건의 주인을 어떻게 찾아 주면 좋을까?","문제가 생긴 까닭 — 물건에 이름을 쓰지 않았기 때문입니다. / 자기 물건을 소중히 여기지 않기 때문입니다.","문제가 우리에게 주는 영향 — 물건 주인이 누구인지 모르기 때문에","함부로 버릴 수 없어서 운동장과 강당이 지저분해 보입니다."],"title":"『국어』 125쪽 — 해결이 필요한 문제 상황 정리하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#11','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C21',2,'mc','auto','의견을 결정하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X20','K4-2-u3-X19','K4-2-u3-X08']::text[],false,'{"seq":11,"concept":"K4-2-u3-C21","difficulty":2,"kind":"mc","stem":"의견을 결정하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"정한 기준에 비추어 의견들을 견주어 보고 가장 알맞은 의견을 고른다","correct":true},{"t":"가위바위보로 정한다","mis":"K4-2-u3-X20"},{"t":"나온 의견을 모두 합친다","mis":"K4-2-u3-X19"},{"t":"먼저 말한 친구의 의견으로 정한다","mis":"K4-2-u3-X08"}],"explanation":["결정할 때에는 기준이 필요해요.","기준에 비추어 의견을 견주어 봐요.","운이나 순서로 정하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#12','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C28',2,'ox','auto','‘~하세요’로 끝나는 말이면 모두 제안하는 글이에요.',ARRAY['K4-2-u3-X27']::text[],false,'{"seq":12,"concept":"K4-2-u3-C28","difficulty":2,"kind":"ox","stem":"‘~하세요’로 끝나는 말이면 모두 제안하는 글이에요.","answer":"X","reason_options":[{"t":"하지 못하게 막기만 하고 해결 방법과 이유가 없으면 제안하는 글로 부족해요.","correct":true},{"t":"‘~하세요’로 끝나면 해결 방법이 없어도 제안이에요.","mis":"K4-2-u3-X27"}],"mis":"K4-2-u3-X27","explanation":["제안은 해결 방법을 의견으로 내놓는 거예요.","‘~하지 마세요’는 금지에 가까워요.","방법과 이유가 함께 있어야 제안하는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#13','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C43',2,'mc','auto','외국어 간판 문제를 제안할 때 이유로 가장 믿을 만한 것은 무엇인가요?',ARRAY['K4-2-u3-X37','K4-2-u3-X38','K4-2-u3-X36']::text[],false,'{"seq":13,"concept":"K4-2-u3-C43","difficulty":2,"kind":"mc","stem":"외국어 간판 문제를 제안할 때 이유로 가장 믿을 만한 것은 무엇인가요?","options":[{"t":"설문 조사로 확인해 보니 세 명 중 두 명이 간판 때문에 불편을 겪었다는 사실","correct":true},{"t":"외국어 간판이 그냥 싫다는 내 느낌","mis":"K4-2-u3-X37"},{"t":"아마 모든 사람이 불편할 것이라는 짐작","mis":"K4-2-u3-X38"},{"t":"왜냐하면 간판이기 때문","mis":"K4-2-u3-X36"}],"explanation":["확인한 사실은 이유를 믿을 만하게 해요.","내 느낌이나 짐작만으로는 설득하기 어려워요.","조사한 결과를 이유로 들면 좋아요."],"asset":{"type":"passage","lines":["그래서 다른 나라 언어로 쓰여 있는 간판 귀퉁이에","한글로 표기하는 법을 만들어 주시면 좋겠습니다.","그러면 무엇을 파는지 알기 쉬울 것입니다.","(간추림) 학생들은 마을 가게 간판을 조사하고 400명에게 설문 조사를 했다.","(간추림) 세 명 중 두 명이 불편을 겪었다고 했고, 학생들의 편지는 실제 법안으로 이어졌다."],"title":"「모두가 읽을 수 있는 간판을 만들어 주세요」 — 4학년 학생들이 국회 의원께 보낸 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#14','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C35',2,'mc','auto','「등하교 때 교문 앞이 너무 복잡해서 위험하다」는 문제에 알맞은 제안 내용은 무엇인가요?',ARRAY['K4-2-u3-X35','K4-2-u3-X34']::text[],false,'{"seq":14,"concept":"K4-2-u3-C35","difficulty":2,"kind":"mc","stem":"「등하교 때 교문 앞이 너무 복잡해서 위험하다」는 문제에 알맞은 제안 내용은 무엇인가요?","options":[{"t":"학년마다 등하교 구역을 정하자","correct":true},{"t":"학교를 없애자","mis":"K4-2-u3-X35"},{"t":"하루 종일 교문 앞에 어른 백 명을 세우자","mis":"K4-2-u3-X34"},{"t":"교문 앞을 지날 때 눈을 감자","mis":"K4-2-u3-X35"}],"explanation":["알맞은 제안은 문제를 바로 해결해요.","실제로 실천할 수 있어야 해요.","학년마다 구역을 정하면 교문 앞이 덜 복잡해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#15','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C47',2,'mc','auto','조대웅의 글 「요즘 동네를 다니다 보면 여기저기에 버려진 쓰레기가 많습니다.」에서 ‘무엇이 + 어떠하다’를 바르게 찾은 것은 무엇인가요?',ARRAY['K4-2-u3-X47','K4-2-u3-X45']::text[],false,'{"seq":15,"concept":"K4-2-u3-C47","difficulty":2,"kind":"mc","stem":"조대웅의 글 「요즘 동네를 다니다 보면 여기저기에 버려진 쓰레기가 많습니다.」에서 ‘무엇이 + 어떠하다’를 바르게 찾은 것은 무엇인가요?","options":[{"t":"쓰레기가 + 많습니다","correct":true},{"t":"동네를 + 다니다","mis":"K4-2-u3-X47"},{"t":"‘누가’ 자리에는 사람만 오니 이 문장에는 없다","mis":"K4-2-u3-X47"},{"t":"여기저기에 + 버려진","mis":"K4-2-u3-X45"}],"explanation":["무엇이 많은지 찾아보아요.","많은 것은 쓰레기예요.","‘누가/무엇이’ 자리에는 물건도 와요."],"asset":{"type":"passage","lines":["안녕하세요? 주민 여러분. 저는 ○○동에 사는 초등학교 4학년 조대웅입니다.","요즘 동네를 다니다 보면 여기저기에 버려진 쓰레기가 많습니다.","길가에 놓인 플라스틱 컵, 놀이터에 떨어진 과자 봉지, 화단 구석에 쌓인 휴지까지…….","일주일에 하루를 정해 동네를 산책하면서 쓰레기를 줍는 날을 만들면 어떨까요?","산책하면서 쓰레기를 하나씩 주우면 운동도 하면서 동네를 깨끗하게 만들 수 있어","일석이조의 효과를 볼 수 있기 때문입니다. 또 쓰레기를 길가에 버리지 않는 습관도 생길 것입니다.","주민 여러분, 작은 실천을 모아 우리 동네를 더 깨끗하고 살기 좋은 곳으로 만들어요!"],"title":"「깨끗한 동네를 만들기 위해 함께 노력해요」 — 『국어활동』 40쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#16','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C38',2,'mc','auto','제안하는 글에서 문제 상황을 나타낼 때 쓰기 좋은 표현은 무엇인가요?',ARRAY['K4-2-u3-X40','K4-2-u3-X39']::text[],false,'{"seq":16,"concept":"K4-2-u3-C38","difficulty":2,"kind":"mc","stem":"제안하는 글에서 문제 상황을 나타낼 때 쓰기 좋은 표현은 무엇인가요?","options":[{"t":"‘요즘 ……하고 있다.’, ‘……이/가 심각해지고 있다.’","correct":true},{"t":"‘……하면 어떨까요?’","mis":"K4-2-u3-X40"},{"t":"‘왜냐하면 ……하기 때문입니다.’","mis":"K4-2-u3-X40"},{"t":"‘무조건 ……하세요.’","mis":"K4-2-u3-X39"}],"explanation":["문제 상황 표현에는 ‘가장 큰 문제점은 ……이다.’도 있어요.","‘……하면 어떨까요?’는 제안하는 내용 표현이에요.","‘왜냐하면’은 이유 표현이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#17','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C31',3,'mc','auto','「교통안전 캠페인」 이야기처럼 학교 주변 교통사고를 막고 싶을 때 쓸 수 있는 방법에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X04','K4-2-u3-X22','K4-2-u3-X05']::text[],false,'{"seq":17,"concept":"K4-2-u3-C31","difficulty":3,"kind":"mc","stem":"「교통안전 캠페인」 이야기처럼 학교 주변 교통사고를 막고 싶을 때 쓸 수 있는 방법에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"캠페인처럼 많은 사람이 함께 알고 실천하게 하는 방법도 쓸 수 있다","correct":true},{"t":"문제는 제안하는 글로만 해결할 수 있다","mis":"K4-2-u3-X04"},{"t":"어린이는 이런 문제에 나설 수 없다","mis":"K4-2-u3-X22"},{"t":"토의를 했으면 다른 활동은 필요 없다","mis":"K4-2-u3-X05"}],"explanation":["한 학생의 제안으로 시작된 캠페인에 많은 학생이 참여했어요.","문제를 해결하는 방법은 여러 가지예요.","상황에 맞는 방법을 고르면 돼요."],"asset":{"type":"passage","lines":["(간추림) 학교 주변에 놀 만한 곳이 없던 초등학교에 놀이터가 새로 생겼다.","(간추림) 학생들이 직접 의견을 내고 만드는 과정에 참여했다.","(간추림) 교통사고로 동생을 잃은 한 학생의 제안으로 교통안전 캠페인이 시작되었다.","(간추림) 많은 학생이 위험을 알고 스스로 캠페인에 참여하고 있다."],"title":"문제를 해결한 학생들 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#18','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C24',3,'ox','auto','토의에서 결정한 의견이 내 의견과 다르면 실천하지 않아도 돼요.',ARRAY['K4-2-u3-X58']::text[],false,'{"seq":18,"concept":"K4-2-u3-C24","difficulty":3,"kind":"ox","stem":"토의에서 결정한 의견이 내 의견과 다르면 실천하지 않아도 돼요.","answer":"X","reason_options":[{"t":"여러 사람이 생각을 모은 결과이므로 적극적으로 실천해요.","correct":true},{"t":"내 의견이 뽑히지 않았으니 지키지 않아도 돼요.","mis":"K4-2-u3-X58"}],"mis":"K4-2-u3-X58","explanation":["『국어활동』 39쪽에서 결정한 의견은 함께 실천하라고 했어요.","내 의견과 달라도 모두의 결정이에요.","함께 실천해야 문제가 풀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#19','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C17',3,'mc','auto','동료 평가지 2번 기준으로 소율이의 의견 「독도의 날 기념 피구 대회」를 평가한 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X64','K4-2-u3-X10','K4-2-u3-X60']::text[],false,'{"seq":19,"concept":"K4-2-u3-C17","difficulty":3,"kind":"mc","stem":"동료 평가지 2번 기준으로 소율이의 의견 「독도의 날 기념 피구 대회」를 평가한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"토의 주제(독도의 날 기념)에 알맞지 않다","correct":true},{"t":"모두 즐겁게 참여할 수 있으니 가장 알맞다","mis":"K4-2-u3-X64"},{"t":"단점이 하나도 없으니 완벽하다","mis":"K4-2-u3-X10"},{"t":"친한 친구의 의견이니 적절하다","mis":"K4-2-u3-X60"}],"explanation":["먼저 주제에 알맞은 의견인지 살펴요.","피구 대회는 독도의 날과 관련이 없어요.","즐겁게 참여할 수 있어도 주제에 맞아야 해요."],"asset":{"type":"speech","turns":[{"who":"주제","text":"독도의 날을 기념하는 우리 반 활동 정하기"},{"who":"소율","text":"“독도의 날 기념 피구 대회를 하면 어떨까요? 모두가 즐겁게 참여할 수 있을 것 같습니다.”"},{"who":"규빈","text":"“독도의 날을 기념해 ‘독도’로 이행시 짓기 대회를 하면 좋겠습니다. 우리 반 모두가 쉽게 참여할 수 있지 않을까요?”"},{"who":"영우","text":"“독도를 소재로 노래를 만들어 보면 어떨까요? 만든 노래는 노래를 잘 부르는 친구가 대표로 불러 주면 좋겠습니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#20','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C40',3,'mc','auto','제안하는 글을 쓸 때 미리 생각해 두면 좋은 것은 무엇인가요?',ARRAY['K4-2-u3-X30','K4-2-u3-X41']::text[],false,'{"seq":20,"concept":"K4-2-u3-C40","difficulty":3,"kind":"mc","stem":"제안하는 글을 쓸 때 미리 생각해 두면 좋은 것은 무엇인가요?","options":[{"t":"제안이 받아들여지지 않을 경우를 생각해 다른 방법도 생각해 본다","correct":true},{"t":"받아들여질 것이 확실하니 다른 방법은 생각하지 않는다","mis":"K4-2-u3-X30"},{"t":"받아들여지지 않으면 포기한다","mis":"K4-2-u3-X41"},{"t":"같은 글을 여러 번 보낼 준비를 한다","mis":"K4-2-u3-X41"}],"explanation":["제안은 받아들여지지 않을 수도 있어요.","그 경우를 생각해 다른 방법을 마련해 두어요.","글을 어떻게 전할지도 함께 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#21','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C48',3,'mc','auto','『국어』 139쪽처럼 자신이 쓴 글을 점검할 때 확인할 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X42']::text[],false,'{"seq":21,"concept":"K4-2-u3-C48","difficulty":3,"kind":"mc","stem":"『국어』 139쪽처럼 자신이 쓴 글을 점검할 때 확인할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"문장의 짜임이 어색하지 않게 문장을 썼나요?","correct":true},{"t":"글자 수가 친구보다 많나요?","mis":"K4-2-u3-X42"},{"t":"어려운 낱말을 많이 썼나요?","mis":"K4-2-u3-X42"},{"t":"제목을 빼고 썼나요?","mis":"K4-2-u3-X42"}],"explanation":["점검표에는 여섯 가지 항목이 있어요.","제목, 대상, 문제 상황, 내용과 이유, 표현, 문장의 짜임이에요.","글의 길이나 어려운 낱말은 기준이 아니에요."],"asset":{"type":"passage","lines":["제안하는 내용이 잘 드러나게 제목을 붙였나요?","누구에게 제안하는지 밝혔나요?","문제 상황을 구체적으로 썼나요?","제안하는 내용과 그 이유가 잘 드러났나요?","제안하는 글에 알맞은 표현을 사용했나요?","문장의 짜임이 어색하지 않게 문장을 썼나요?"],"title":"『국어』 139쪽 — 스스로 확인하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#22','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C53',3,'mc','auto','전교 학생회에 낼 안건을 고르는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X50','K4-2-u3-X08']::text[],false,'{"seq":22,"concept":"K4-2-u3-C53","difficulty":3,"kind":"mc","stem":"전교 학생회에 낼 안건을 고르는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"많은 친구에게 공감을 얻은 제안을 고른다","correct":true},{"t":"우리 반에만 좋은 제안을 고른다","mis":"K4-2-u3-X50"},{"t":"발표 목소리가 큰 친구의 제안을 고른다","mis":"K4-2-u3-X50"},{"t":"가장 먼저 낸 제안을 고른다","mis":"K4-2-u3-X08"}],"explanation":["전교 학생회 안건은 학교 전체와 관련 있어요.","많은 친구가 공감한 제안을 골라요.","직접 방문, 누리집, 편지로 전달할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#23','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C42',4,'mc','auto','제안하는 글로 해결하기에 알맞은 문제와 제안 대상을 바르게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u3-X43','K4-2-u3-X24']::text[],false,'{"seq":23,"concept":"K4-2-u3-C42","difficulty":4,"kind":"mc","stem":"제안하는 글로 해결하기에 알맞은 문제와 제안 대상을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"외국어 간판이라 무엇을 하는 곳인지 모르는 사람이 많다 — 법을 만드는 국회 의원","correct":true},{"t":"내일 비가 올 것 같다 — 우리 반 친구들","mis":"K4-2-u3-X43"},{"t":"짝과 다툰 일 — 교장 선생님","mis":"K4-2-u3-X43"},{"t":"간판 글씨가 작다 — 내 동생","mis":"K4-2-u3-X24"}],"explanation":["제안하는 글은 여러 사람이 겪고 바꿀 수 있는 문제에 써요.","대상은 그 일을 바꿀 수 있는 사람이어야 해요.","날씨나 두 사람 사이의 일은 제안하는 글로 풀기 어려워요."],"asset":{"type":"passage","lines":["그래서 다른 나라 언어로 쓰여 있는 간판 귀퉁이에","한글로 표기하는 법을 만들어 주시면 좋겠습니다.","그러면 무엇을 파는지 알기 쉬울 것입니다.","(간추림) 학생들은 마을 가게 간판을 조사하고 400명에게 설문 조사를 했다.","(간추림) 세 명 중 두 명이 불편을 겪었다고 했고, 학생들의 편지는 실제 법안으로 이어졌다."],"title":"「모두가 읽을 수 있는 간판을 만들어 주세요」 — 4학년 학생들이 국회 의원께 보낸 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#24','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C48',4,'essay','teacher','친구가 「급식이 맛이 없어요」라는 제목으로 제안하는 글을 썼어요. 『국어』 139쪽 스스로 확인하기 항목에 비추어 고칠 점 두 가지와 고치는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u3-C48","difficulty":4,"kind":"essay","stem":"친구가 「급식이 맛이 없어요」라는 제목으로 제안하는 글을 썼어요. 『국어』 139쪽 스스로 확인하기 항목에 비추어 고칠 점 두 가지와 고치는 까닭을 쓰세요.","answer_guide":{"answer":"예: ① 제목이 불만만 드러내고 제안하는 내용이 드러나지 않는다 — ‘급식 메뉴를 다양하게 해 주세요’처럼 제안이 드러나게 고친다. ② 누구에게 제안하는지 밝히지 않았다 — 급식을 맡으신 영양 선생님께 쓰는 글임을 처음에 밝힌다.","scoring_points":["점검표 항목에 맞는 고칠 점을 두 가지 썼는가","고치는 까닭을 썼는가","어떻게 고칠지 알맞게 제시했는가"]},"explanation":["제목은 제안하는 내용이 잘 드러나게 붙여요.","누구에게 제안하는지 밝혀야 해요.","불만이 아니라 해결 방법을 내놓아야 해요."],"asset":{"type":"passage","lines":["제안하는 내용이 잘 드러나게 제목을 붙였나요?","누구에게 제안하는지 밝혔나요?","문제 상황을 구체적으로 썼나요?","제안하는 내용과 그 이유가 잘 드러났나요?","제안하는 글에 알맞은 표현을 사용했나요?","문장의 짜임이 어색하지 않게 문장을 썼나요?"],"title":"『국어』 139쪽 — 스스로 확인하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_b#25','kor',4,2,'u3','','tb_g4_2_kor_u3_review_b','unit_review','K4-2-u3-C6',4,'essay','teacher','분실물 문제를 예로 들어, 토의에서 결정한 내용을 제안하는 글로 알리는 과정을 차례대로 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u3-C6","difficulty":4,"kind":"essay","stem":"분실물 문제를 예로 들어, 토의에서 결정한 내용을 제안하는 글로 알리는 과정을 차례대로 설명하세요.","answer_guide":{"answer":"예: 먼저 모둠에서 ‘물건의 주인을 어떻게 찾아 주면 좋을까?’를 주제로 정하고 의견을 마련해 서로 질문하며 모은 뒤 ‘분실물 찾기 게시판 만들기’로 결정한다. 그다음 게시판을 놓을 곳을 정할 수 있는 교장 선생님께 문제 상황, 제안하는 내용, 이유가 드러나게 제안하는 글을 쓴다.","scoring_points":["토의 절차(주제·마련·모으기·결정)를 썼는가","토의 결과를 제안하는 글로 이어 쓴다는 점을 썼는가","제안하는 글의 대상과 짜임을 알맞게 썼는가"]},"explanation":["토의와 제안하는 글은 모두 문제를 해결하는 방법이에요.","토의에서 정한 것을 많은 사람에게 알리려고 글을 쓸 수 있어요.","토의 과정은 글을 계획하는 데에도 도움이 돼요."],"asset":{"type":"passage","lines":["결정한 의견 — 분실물 찾기 게시판 만들기","결정한 까닭 — 모든 학생이 자기가 잃어버린 물건이 맞는지 확인할 수 있기 때문이다.","실천 계획 — 쉬는 시간을 이용해서 일주일 동안 분실물 찾기 게시판을 만들고","학교 현관에 놓는다."],"title":"『국어』 127쪽 — 토의에서 결정한 의견 정리하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#1','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C34',1,'ox','auto','스스로 확인하기 ⑤예요. 「누가 읽을 것인지 생각하지 않는다.」는 색칠할 알맞은 설명이에요.',ARRAY['K4-2-u3-X24']::text[],false,'{"seq":1,"concept":"K4-2-u3-C34","difficulty":1,"kind":"ox","stem":"스스로 확인하기 ⑤예요. 「누가 읽을 것인지 생각하지 않는다.」는 색칠할 알맞은 설명이에요.","answer":"X","reason_options":[{"t":"누구에게 제안할지 생각해야 그 사람에게 알맞은 내용과 표현을 쓸 수 있어요.","correct":true},{"t":"제안하는 글은 아무나 읽으니 읽을 사람을 생각할 필요가 없어요.","mis":"K4-2-u3-X24"}],"mis":"K4-2-u3-X24","explanation":["제안하는 글은 대상이 정해져 있는 글이에요.","읽을 사람을 생각하면 제안이 구체적이 돼요.","그래서 이 구름은 색칠하지 않아요."],"asset":{"type":"passage","lines":["① 문제 상황을 구체적으로 써야 한다.","② 의견의 장점만 생각하며 의견을 마련한다.","③ 친구의 기분을 고려하며 질문한다.","④ 제안하는 이유를 쓰지 않는다.","⑤ 누가 읽을 것인지 생각하지 않는다.","⑥ 주제에 알맞은 의견과 이유를 말한다."],"title":"『국어』 145쪽 스스로 확인하기 — 알맞은 설명을 모두 찾아 색칠하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#2','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C2',1,'mc','auto','『국어』 113쪽 「생각 열기」에서 학생들은 무엇을 하고 있나요?',ARRAY['K4-2-u3-X01']::text[],false,'{"seq":2,"concept":"K4-2-u3-C2","difficulty":1,"kind":"mc","stem":"『국어』 113쪽 「생각 열기」에서 학생들은 무엇을 하고 있나요?","options":[{"t":"학급 회의를 하며 함께 토의하고 있다","correct":true},{"t":"한 친구가 혼자 정한 규칙을 알려 주기만 하고 있다","mis":"K4-2-u3-X01"},{"t":"모두 각자 책을 읽고 있다","mis":"K4-2-u3-X01"},{"t":"운동장에서 놀이를 하고 있다","mis":"K4-2-u3-X01"}],"explanation":["학생들은 학급 회의를 하고 있어요.","앞에 나온 친구는 청소에 대한 의견을 말하고 있어요.","앉아 있는 친구는 결정한 내용을 학교 학생들에게 알리고 싶어 해요."],"asset":{"type":"passage","lines":["[그림] 교실에서 학급 회의를 하는 모습","앞에 나온 친구 — “각자 맡은 구역을 꼼꼼하게 청소해야 합니다.”","앉아 있는 친구의 생각 — “학급 회의에서 결정한 내용을 우리 학교 학생들에게 알리고 싶어.”","물음 — 우리 주변의 문제를 해결하기 위해 어떤 제안을 하고 싶나요?"],"title":"『국어』 113쪽 생각 열기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#3','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C8',1,'sa','auto','토의 절차에서 ‘의견 모으기’ 다음에 오는 단계를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u3-C8","difficulty":1,"kind":"sa","stem":"토의 절차에서 ‘의견 모으기’ 다음에 오는 단계를 쓰세요.","answer":["의견 결정하기","의견결정하기","의견 결정"],"explanation":["의견을 모아 서로 따져 본 뒤에는 결정해요.","기준에 따라 가장 알맞은 의견을 골라요.","이 단계가 의견 결정하기예요."],"mis":"K4-2-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#4','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C5',1,'ox','auto','제안하는 내용을 넣어 쓴 글을 제안하는 글이라고 해요.',ARRAY['K4-2-u3-X57']::text[],false,'{"seq":4,"concept":"K4-2-u3-C5","difficulty":1,"kind":"ox","stem":"제안하는 내용을 넣어 쓴 글을 제안하는 글이라고 해요.","answer":"O","reason_options":[{"t":"『국어』 129쪽에서 제안하는 내용을 넣어 제안하는 글을 쓸 수 있다고 했어요.","correct":true},{"t":"제안하는 글은 상대에게 명령하는 글이에요.","mis":"K4-2-u3-X57"}],"mis":"K4-2-u3-X57","explanation":["제안은 의견을 내놓는 것이에요.","그 내용을 담아 쓴 글이 제안하는 글이에요.","명령하거나 불평하는 글이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#5','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C27',1,'mc','auto','연우의 글에서 「그런데 과학관에는 비가 올 때 도시락이나 간식을 먹을 만한 공간이 없었습니다.」는 어느 부분인가요?',ARRAY['K4-2-u3-X26','K4-2-u3-X42']::text[],false,'{"seq":5,"concept":"K4-2-u3-C27","difficulty":1,"kind":"mc","stem":"연우의 글에서 「그런데 과학관에는 비가 올 때 도시락이나 간식을 먹을 만한 공간이 없었습니다.」는 어느 부분인가요?","options":[{"t":"문제 상황","correct":true},{"t":"제안하는 내용","mis":"K4-2-u3-X26"},{"t":"제안하는 이유","mis":"K4-2-u3-X26"},{"t":"글의 제목","mis":"K4-2-u3-X42"}],"explanation":["연우가 겪은 불편이 드러난 문장이에요.","무엇이 불편한지는 문제 상황이에요.","문제 상황은 구체적으로 써요."],"asset":{"type":"passage","lines":["가람어린이과학관 관장님, 안녕하세요? 저는 ○○초등학교 4학년 김연우라고 합니다.","가람어린이과학관에서는 재미있게 과학 원리를 체험할 수 있다고 하여","지난 주말 가족과 함께 방문했습니다.","그런데 과학관에는 비가 올 때 도시락이나 간식을 먹을 만한 공간이 없었습니다.","그래서 비가 그칠 때까지 기다려야 했습니다.","비나 눈이 오는 날뿐만 아니라 미세 먼지 농도가 높은 날에도","관람객들은 이러한 불편을 겪을 것입니다."],"title":"「도시락이나 간식 먹을 공간을 만들어 주세요」 앞부분 — 『국어』 134쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#6','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C45',1,'blank','auto','「줄넘기는 누구나 쉽게 할 수 있는 운동입니다.」는 ‘누가/무엇이 + (     )’ 짜임의 문장이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u3-X45']::text[],false,'{"seq":6,"concept":"K4-2-u3-C45","difficulty":1,"kind":"blank","stem":"「줄넘기는 누구나 쉽게 할 수 있는 운동입니다.」는 ‘누가/무엇이 + (     )’ 짜임의 문장이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"무엇이다","correct":true},{"t":"어찌하다","mis":"K4-2-u3-X45"},{"t":"어떠하다","mis":"K4-2-u3-X45"}],"explanation":["‘줄넘기는’이 무엇이에 해당해요.","‘운동입니다’는 줄넘기가 무엇인지 나타내요.","그래서 무엇이 + 무엇이다 짜임이에요."],"asset":{"type":"passage","lines":["요즈음 초등학생의 건강 상태가 심각합니다.","(간추림) 체육 시간에 운동장 한 바퀴를 달리지 못하는 친구도 꽤 많습니다.","줄넘기 급수제를 실시하면 어떨까요?","건강을 지키기 위해 운동은 꼭 필요한데, 줄넘기는 누구나 쉽게 할 수 있는 운동입니다.","(간추림) 급수제를 하면 높은 등급에 오르려고 목표를 정해 더 열심히 할 것이다."],"title":"제안하는 글 「줄넘기 급수제로 건강을 지켜요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#7','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C56',1,'ox','auto','‘뛰다’와 ‘달리다’는 뜻이 반대인 관계예요.',ARRAY['K4-2-u3-X53']::text[],false,'{"seq":7,"concept":"K4-2-u3-C56","difficulty":1,"kind":"ox","stem":"‘뛰다’와 ‘달리다’는 뜻이 반대인 관계예요.","answer":"X","reason_options":[{"t":"두 낱말은 비슷한 움직임을 나타내므로 뜻이 비슷한 관계예요.","correct":true},{"t":"두 낱말은 생김새가 다르니 뜻이 반대인 관계예요.","mis":"K4-2-u3-X53"}],"mis":"K4-2-u3-X53","explanation":["뛰다와 달리다는 비슷한 움직임을 나타내요.","그래서 뜻이 비슷한 관계예요.","『국어』 146쪽에서 파란색으로 칠하는 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#8','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C4',1,'ox','auto','토의할 때 말차례를 지키며 친구의 말을 경청하는 것은 바른 태도예요.',ARRAY['K4-2-u3-X03']::text[],false,'{"seq":8,"concept":"K4-2-u3-C4","difficulty":1,"kind":"ox","stem":"토의할 때 말차례를 지키며 친구의 말을 경청하는 것은 바른 태도예요.","answer":"O","reason_options":[{"t":"말차례를 지키고 경청하면 모두의 의견을 고르게 들을 수 있어요.","correct":true},{"t":"내 생각이 더 좋으면 말차례를 지키지 않아도 돼요.","mis":"K4-2-u3-X03"}],"mis":"K4-2-u3-X03","explanation":["동료 평가지에도 말차례와 경청을 확인하는 칸이 있어요.","차례를 지키면 모두가 말할 기회를 얻어요.","끝까지 들어야 의견을 제대로 따질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#9','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C13',2,'mc','auto','토의에서 질문에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X14','K4-2-u3-X13','K4-2-u3-X59']::text[],false,'{"seq":9,"concept":"K4-2-u3-C13","difficulty":2,"kind":"mc","stem":"토의에서 질문에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"궁금하거나 의견과 이유가 알맞은지 확인할 필요가 있을 때 질문하고, 억지로 질문을 만들어 내지 않는다","correct":true},{"t":"질문은 많이 할수록 무조건 좋다","mis":"K4-2-u3-X14"},{"t":"공손한 말만 붙이면 무엇을 물어도 좋은 질문이다","mis":"K4-2-u3-X13"},{"t":"대답하기 어려운 질문을 해야 토의가 잘된다","mis":"K4-2-u3-X59"}],"explanation":["질문은 더 나은 해결 방법을 찾으려고 해요.","목적에 맞지 않는 질문을 의무로 만들지 않아요.","말투와 내용이 모두 알맞아야 좋은 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#10','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C15',2,'mc','auto','『국어』 124쪽 그림 ㉰(놀이터 기구의 낙서)로 토의 주제를 만들 때 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X49','K4-2-u3-X02','K4-2-u3-X09']::text[],false,'{"seq":10,"concept":"K4-2-u3-C15","difficulty":2,"kind":"mc","stem":"『국어』 124쪽 그림 ㉰(놀이터 기구의 낙서)로 토의 주제를 만들 때 가장 알맞은 것은 무엇인가요?","options":[{"t":"놀이터 기구를 깨끗하게 쓰려면 어떻게 해야 할까?","correct":true},{"t":"놀이터를 아예 없애야 할까?","mis":"K4-2-u3-X49"},{"t":"놀이터 기구는 몇 개일까?","mis":"K4-2-u3-X02"},{"t":"놀이터를 다른 나라로 옮길까?","mis":"K4-2-u3-X09"}],"explanation":["여러 의견이 나올 수 있는 질문 꼴로 주제를 만들어요.","우리가 실천할 수 있는 문제여야 해요.","놀이터를 없애면 놀 곳까지 사라져요."],"asset":{"type":"passage","lines":["㉮ [그림] ‘분실물 찾아가세요.’ — 가방·물병·신발·필통이 보관함에 잔뜩 쌓여 있다.","㉯ [그림] 복도 바닥 곳곳에 휴지와 과자 껍질 같은 쓰레기가 떨어져 있다.","㉰ [그림] 놀이터 미끄럼틀과 시소에 낙서가 가득하다."],"title":"『국어』 124쪽 — 학교나 학교 주변의 문제 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#11','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C21',2,'ox','auto','모둠에서 의견을 결정할 때에는 꼭 한 가지 의견만 골라야 해요.',ARRAY['K4-2-u3-X61']::text[],false,'{"seq":11,"concept":"K4-2-u3-C21","difficulty":2,"kind":"ox","stem":"모둠에서 의견을 결정할 때에는 꼭 한 가지 의견만 골라야 해요.","answer":"X","reason_options":[{"t":"여러 의견을 모아 새로운 의견을 만들 수도 있어요.","correct":true},{"t":"의견을 합치면 안 되니 반드시 하나만 골라야 해요.","mis":"K4-2-u3-X61"}],"mis":"K4-2-u3-X61","explanation":["『국어』 127쪽에 “꼭 한 가지 의견으로 결정할 필요는 없어요.”라고 했어요.","여러 의견의 좋은 점을 모아 새 의견을 만들 수 있어요.","어떻게 하든 기준에 비추어 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#12','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C28',2,'mc','auto','‘금지’와 ‘제안’의 차이를 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u3-X27','K4-2-u3-X28','K4-2-u3-X57']::text[],false,'{"seq":12,"concept":"K4-2-u3-C28","difficulty":2,"kind":"mc","stem":"‘금지’와 ‘제안’의 차이를 바르게 말한 것은 무엇인가요?","options":[{"t":"금지는 어떤 행동을 하지 못하도록 막는 것이고, 제안은 의견을 내놓는 것이다","correct":true},{"t":"둘은 같은 뜻이다","mis":"K4-2-u3-X27"},{"t":"짧게 막을수록 좋은 제안이다","mis":"K4-2-u3-X28"},{"t":"제안은 상대에게 명령하는 것이다","mis":"K4-2-u3-X57"}],"explanation":["금지는 하지 못하게 하는 거예요.","제안은 안이나 의견을 내놓는 거예요.","문제 상황에 맞게 해결 방법을 제안해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#13','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C36',2,'ox','auto','「왜냐하면 ……때문입니다.」를 쓰기만 하면 알맞은 이유가 돼요.',ARRAY['K4-2-u3-X36']::text[],false,'{"seq":13,"concept":"K4-2-u3-C36","difficulty":2,"kind":"ox","stem":"「왜냐하면 ……때문입니다.」를 쓰기만 하면 알맞은 이유가 돼요.","answer":"X","reason_options":[{"t":"제안대로 하면 무엇이 좋아지는지가 담겨야 알맞은 이유예요.","correct":true},{"t":"‘왜냐하면’을 쓰면 무엇이든 이유가 돼요.","mis":"K4-2-u3-X36"}],"mis":"K4-2-u3-X36","explanation":["‘왜냐하면’은 이유를 쓸 때 쓰는 표현일 뿐이에요.","그 안에 좋아지는 점이 들어가야 해요.","표현보다 내용이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#14','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C34',2,'mc','auto','「윗집에서 쿵쿵거리는 소리가 너무 시끄럽다」는 문제를 제안할 대상으로 알맞은 사람은 누구인가요?',ARRAY['K4-2-u3-X24']::text[],false,'{"seq":14,"concept":"K4-2-u3-C34","difficulty":2,"kind":"mc","stem":"「윗집에서 쿵쿵거리는 소리가 너무 시끄럽다」는 문제를 제안할 대상으로 알맞은 사람은 누구인가요?","options":[{"t":"아파트 주민","correct":true},{"t":"영양 선생님","mis":"K4-2-u3-X24"},{"t":"과자 회사","mis":"K4-2-u3-X24"},{"t":"학교 친구들","mis":"K4-2-u3-X24"}],"explanation":["층간 소음은 아파트에 사는 사람들이 함께 줄여야 해요.","그래서 아파트 주민에게 제안할 수 있어요.","문제와 관련 있는 사람에게 제안해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#15','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C46',2,'mc','auto','「관람객들이 가족과 행복한 추억입니다.」를 바르게 고친 문장은 무엇인가요?',ARRAY['K4-2-u3-X46','K4-2-u3-X45']::text[],false,'{"seq":15,"concept":"K4-2-u3-C46","difficulty":2,"kind":"mc","stem":"「관람객들이 가족과 행복한 추억입니다.」를 바르게 고친 문장은 무엇인가요?","options":[{"t":"관람객들이 가족과 행복한 추억을 만듭니다.","correct":true},{"t":"관람객들이 가족과 행복합니다 추억을.","mis":"K4-2-u3-X46"},{"t":"추억입니다 관람객들이 가족과.","mis":"K4-2-u3-X45"},{"t":"관람객들이 가족과 추억입니다.","mis":"K4-2-u3-X46"}],"explanation":["관람객들이 추억인 것은 아니에요.","관람객들이 추억을 만드는 것이에요.","그래서 ‘추억을 만듭니다’로 고쳐요."],"asset":{"type":"passage","lines":["보기 — “많은 친구가 운동장에서 공놀이를 즐겁습니다.” (누가/무엇이 + 어떠하다)","→ 고친 문장 “많은 친구가 운동장에서 공놀이를 즐깁니다.” (누가/무엇이 + 어찌하다)","문제 — “관람객들이 가족과 행복한 추억입니다.” (누가/무엇이 + 무엇이다)","도움말 — 문장을 소리 내어 읽어 보면 어색한 부분을 쉽게 찾을 수 있어요."],"title":"『국어』 138쪽 — 문장의 짜임이 어색한 부분 고치기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#16','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C23',2,'mc','auto','분실물 문제에 대한 실천 계획으로 가장 구체적인 것은 무엇인가요?',ARRAY['K4-2-u3-X21']::text[],false,'{"seq":16,"concept":"K4-2-u3-C23","difficulty":2,"kind":"mc","stem":"분실물 문제에 대한 실천 계획으로 가장 구체적인 것은 무엇인가요?","options":[{"t":"이번 주 쉬는 시간마다 모둠별로 돌아가며 분실물 찾기 게시판에 새 물건을 올린다.","correct":true},{"t":"분실물이 줄어들게 노력하자.","mis":"K4-2-u3-X21"},{"t":"분실물에 관심을 갖자.","mis":"K4-2-u3-X21"},{"t":"언젠가 게시판을 만들자.","mis":"K4-2-u3-X21"}],"explanation":["‘이번 주 쉬는 시간마다’는 언제예요.","‘모둠별로 돌아가며’는 누가예요.","‘게시판에 새 물건을 올린다’는 무엇을이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#17','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C6',3,'mc','auto','『국어』 114쪽 2번에서 친구들이 토의 결과를 알리려고 떠올린 방법을 바르게 묶은 것은 무엇인가요?',ARRAY['K4-2-u3-X05','K4-2-u3-X04']::text[],false,'{"seq":17,"concept":"K4-2-u3-C6","difficulty":3,"kind":"mc","stem":"『국어』 114쪽 2번에서 친구들이 토의 결과를 알리려고 떠올린 방법을 바르게 묶은 것은 무엇인가요?","options":[{"t":"학교 신문에 제안하는 글 쓰기 · 선생님과 상의해 학교 누리집에 올리기","correct":true},{"t":"토의를 처음부터 다시 하기 · 결정을 비밀로 하기","mis":"K4-2-u3-X05"},{"t":"아무에게도 알리지 않기 · 잊어버리기","mis":"K4-2-u3-X05"},{"t":"무조건 교장 선생님께만 쓰기 · 다른 방법은 쓰지 않기","mis":"K4-2-u3-X04"}],"explanation":["친구들은 결정한 내용을 학교 학생들에게 알리고 싶어 했어요.","학교 신문과 학교 누리집을 떠올렸어요.","토의 결과를 제안하는 글로 알리는 거예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“지난번 토의에서 결정한 내용을 우리 학교 학생들에게도 알리자.”"},{"who":"친구 2","text":"“학교 신문에 제안하는 글을 써서 알리면 어떨까?”"},{"who":"친구 3","text":"“오늘도 등굣길에 휴대 전화를 보면서 길을 건너는 학생을 봤어.”"},{"who":"친구 4","text":"“선생님과 상의해 학교 누리집에 올려도 좋을 것 같아.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#18','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C51',3,'mc','auto','급식 잔반 문제를 해결하는 의견 가운데 바라는 모습을 이루는 것은 무엇인가요?',ARRAY['K4-2-u3-X49']::text[],false,'{"seq":18,"concept":"K4-2-u3-C51","difficulty":3,"kind":"mc","stem":"급식 잔반 문제를 해결하는 의견 가운데 바라는 모습을 이루는 것은 무엇인가요?","options":[{"t":"먹을 만큼만 담아 다 먹는 날을 정해 실천한다","correct":true},{"t":"급식을 아예 받지 않는다","mis":"K4-2-u3-X49"},{"t":"남은 음식을 몰래 버린다","mis":"K4-2-u3-X49"},{"t":"급식 시간을 없앤다","mis":"K4-2-u3-X49"}],"explanation":["바라는 모습은 음식을 남기지 않고 골고루 먹는 것이에요.","급식을 받지 않으면 남는 음식은 없어도 바람이 사라져요.","먹을 만큼 담아 다 먹으면 환경도 지킬 수 있어요."],"asset":{"type":"passage","lines":["어제 하굣길에 급식실 옆을 지나면서 많은 양의 음식물 쓰레기를 보았습니다.","우리가 남긴 음식물을 모아 놓은 것인데 생각했던 것보다 무척 많아서 놀랐습니다.","집에 와서 인터넷을 찾아보니 음식물 쓰레기를 처리할 때 비용이 많이 들고","온실가스가 배출되어 환경에 나쁘다고 합니다.","급식에서 음식을 남기지 않으려면 어떻게 해야 할까요?"],"title":"누리집 게시판 「급식에서 남긴 음식 문제를 어떻게 해결할까요?」 — 『국어』 142쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#19','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C24',3,'mc','auto','동료 평가를 할 때 친구의 의견을 듣는 태도로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X03','K4-2-u3-X60','K4-2-u3-X58']::text[],false,'{"seq":19,"concept":"K4-2-u3-C24","difficulty":3,"kind":"mc","stem":"동료 평가를 할 때 친구의 의견을 듣는 태도로 알맞은 것은 무엇인가요?","options":[{"t":"친구의 의견과 이유가 문제 해결에 도움이 될지 판단하며 듣는다","correct":true},{"t":"친구가 얼마나 오래 말했는지만 센다","mis":"K4-2-u3-X03"},{"t":"나와 친한 친구에게 점수를 더 준다","mis":"K4-2-u3-X60"},{"t":"내 의견과 다르면 적절하지 않다고 쓴다","mis":"K4-2-u3-X58"}],"explanation":["문제 해결을 위한 토의이므로 도움이 될지 판단하며 들어요.","친한 정도로 평가하지 않아요.","나와 달라도 내용이 알맞으면 적절하다고 평가해요."],"asset":{"type":"passage","lines":["1 토의 주제에 대한 친구의 의견과 그 이유를 써 봅시다.","2 기준을 생각하며 친구의 의견을 평가해 봅시다.","(주제에 알맞은가 · 이유가 적절한가 · 모두가 실천할 수 있는가 · 단점도 생각했는가)","(  )의 의견은 문제 해결에 (적절하다. / 적절하지 않다.) 왜냐하면 …… 때문이다.","3 적극적으로 참여했나요? · 말차례를 지켰나요? · 친구의 말을 경청했나요?"],"title":"토의 활동 동료 평가지 — 문제 해결을 위한 토의 참여 평가하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#20','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C30',3,'mc','auto','『국어』 135쪽 답글에서 과학관이 연우의 제안에 따라 하겠다고 한 일은 무엇인가요?',ARRAY['K4-2-u3-X41','K4-2-u3-X49','K4-2-u3-X22']::text[],false,'{"seq":20,"concept":"K4-2-u3-C30","difficulty":3,"kind":"mc","stem":"『국어』 135쪽 답글에서 과학관이 연우의 제안에 따라 하겠다고 한 일은 무엇인가요?","options":[{"t":"전시 장소를 뺀 실내나 야외에 음식을 먹을 수 있는 공간을 마련한다","correct":true},{"t":"제안을 무시하고 아무것도 하지 않는다","mis":"K4-2-u3-X41"},{"t":"과학관 문을 닫는다","mis":"K4-2-u3-X49"},{"t":"연우에게 직접 공간을 만들라고 한다","mis":"K4-2-u3-X22"}],"explanation":["과학관은 여러 가지 방법을 논의했다고 했어요.","관람객이 편하게 음식을 먹을 공간을 마련하겠다고 했어요.","연우의 제안이 받아들여진 거예요."],"asset":{"type":"passage","lines":["가람어린이과학관을 찾아 주셔서 진심으로 감사합니다.","먼저, 식사 공간이 부족하여 불편을 겪으신 점에 대해 사과드립니다.","가람어린이과학관은 더 나은 관람 환경을 위해 여러 가지 방법을 논의했습니다.","전시 장소를 제외한 실내나 야외에서 관람객이 편하고 즐겁게","음식을 드실 수 있는 공간을 마련하겠습니다.","소중한 제안을 해 주셔서 감사합니다."],"title":"과학관 관장님의 답글 — 『국어』 135쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#21','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C49',3,'mc','auto','『국어』 141쪽 보기에서 교장 선생님께 제안하는 글을 전하는 방법을 바르게 묶은 것은 무엇인가요?',ARRAY['K4-2-u3-X48','K4-2-u3-X31']::text[],false,'{"seq":21,"concept":"K4-2-u3-C49","difficulty":3,"kind":"mc","stem":"『국어』 141쪽 보기에서 교장 선생님께 제안하는 글을 전하는 방법을 바르게 묶은 것은 무엇인가요?","options":[{"t":"직접 방문하기 · 학교 누리집에 올리기 · 편지 쓰기","correct":true},{"t":"허락 없이 교장실 문에 붙이기","mis":"K4-2-u3-X48"},{"t":"친구에게만 보여 주기","mis":"K4-2-u3-X48"},{"t":"전교생 앞에서 큰 소리로 불평하기","mis":"K4-2-u3-X31"}],"explanation":["읽을 사람에 맞게 전하는 방법을 골라요.","교장 선생님께는 직접 방문하거나 편지를 쓸 수 있어요.","학교 누리집에 올리는 방법도 있어요."],"asset":{"type":"passage","lines":["교장 선생님 — 직접 방문하기 · 학교 누리집에 올리기 · 편지 쓰기","우리 학교 친구들 — 전교 학생회에 안건 내기 · 학교 누리집에 올리기","· 허락을 받고 알림판에 붙이기","안건: 토의하거나 조사해야 할 사실."],"title":"『국어』 141쪽 보기 — 제안하는 글을 전달하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#22','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C30',3,'mc','auto','스스로 읽기 「붕붕 도서관을 지켜 주세요」에서 아이들이 도서관을 지키려고 한 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X22','K4-2-u3-X31','K4-2-u3-X41']::text[],false,'{"seq":22,"concept":"K4-2-u3-C30","difficulty":3,"kind":"mc","stem":"스스로 읽기 「붕붕 도서관을 지켜 주세요」에서 아이들이 도서관을 지키려고 한 일로 알맞은 것은 무엇인가요?","options":[{"t":"퀴즈 대회에 나가고, 전단지를 돌리고, 공청회에서 의견을 발표하는 등 여러 방법으로 의견을 제안했다","correct":true},{"t":"아무 노력도 하지 않고 기다렸다","mis":"K4-2-u3-X22"},{"t":"불만만 쏟아 냈다","mis":"K4-2-u3-X31"},{"t":"한 번 실패하자 바로 포기했다","mis":"K4-2-u3-X41"}],"explanation":["아이들은 도서관이 독서실로 바뀌는 것을 막고 싶었어요.","여러 방법으로 의견을 제안했어요.","제안은 사람들의 마음을 움직일 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 책 읽기를 좋아하는 ‘나’와 친구들은 동네의 하나뿐인 붕붕 도서관 자원봉사자이다.","(간추림) 어른들이 입시 공부가 더 중요하다며 도서관을 독서실로 바꾸려 한다.","(간추림) 아이들은 퀴즈 대회에 나가고, 전단지를 돌리고, 공청회에서 의견을 발표한다.","(간추림) 민장이가 도서관이 꼭 있어야 하는 까닭을 말해 사람들의 마음을 움직인다."],"title":"「붕붕 도서관을 지켜 주세요」(조은진 글) — 『국어활동』 42~53쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#23','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C37',4,'mc','auto','제안하는 글에서 가장 중요한 부분과 그 까닭을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u3-X42','K4-2-u3-X30','K4-2-u3-X63']::text[],false,'{"seq":23,"concept":"K4-2-u3-C37","difficulty":4,"kind":"mc","stem":"제안하는 글에서 가장 중요한 부분과 그 까닭을 바르게 말한 것은 무엇인가요?","options":[{"t":"현재의 문제 상황 — 왜 문제인지 분명하면 읽는 사람이 바꾸어야겠다고 생각하기 때문","correct":true},{"t":"제목 — 제목만 좋으면 내용은 상관없어서","mis":"K4-2-u3-X42"},{"t":"끝인사 — 인사가 길수록 받아들여져서","mis":"K4-2-u3-X30"},{"t":"글쓴이 이름 — 이름만 있으면 되어서","mis":"K4-2-u3-X63"}],"explanation":["문제 상황이 분명해야 바꿀 까닭이 생겨요.","그래서 문제 상황을 구체적으로 써요.","제목·인사·이름도 필요하지만 문제 상황이 바탕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#24','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C35',4,'essay','teacher','「과자를 사면 양이 너무 적게 들어 있어 기분이 안 좋을 때가 많다」는 문제 상황으로 과자 회사에 보낼 제안하는 글의 가운데 부분(제안하는 내용과 이유)을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u3-C35","difficulty":4,"kind":"essay","stem":"「과자를 사면 양이 너무 적게 들어 있어 기분이 안 좋을 때가 많다」는 문제 상황으로 과자 회사에 보낼 제안하는 글의 가운데 부분(제안하는 내용과 이유)을 쓰세요.","answer_guide":{"answer":"예: 과자 봉지 속의 불필요한 중간 포장을 줄이거나 상자 크기를 내용물에 맞게 조정하면 좋겠습니다. 왜냐하면 사는 사람이 실망하지 않고, 버려지는 포장 쓰레기도 줄어 환경을 지킬 수 있기 때문입니다.","scoring_points":["과자 회사가 실천할 수 있는 제안을 썼는가","제안하는 이유를 여러 사람에게 좋은 점으로 썼는가","제안과 이유에 알맞은 표현을 썼는가"]},"explanation":["제안은 받는 곳이 실천할 수 있어야 해요.","이유는 여러 사람에게 좋아지는 점으로 써요.","‘……면 좋겠습니다’, ‘왜냐하면 …… 때문입니다’를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_c#25','kor',4,2,'u3','','tb_g4_2_kor_u3_review_c','unit_review','K4-2-u3-C50',4,'essay','teacher','『국어』 142쪽 「붙임쪽지로 질문하며 토의하기」의 차례를 설명하고, 질문 쪽지를 쓸 때 주의할 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u3-C50","difficulty":4,"kind":"essay","stem":"『국어』 142쪽 「붙임쪽지로 질문하며 토의하기」의 차례를 설명하고, 질문 쪽지를 쓸 때 주의할 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 게시판 글을 읽고 문제 상황을 이야기한 뒤, 자신의 의견과 이유를 붙임쪽지에 써서 칠판에 붙인다. 친구 의견 옆에 질문 쪽지를 붙이고, 질문을 받은 친구가 답해 준다. 가장 좋은 의견을 생각해 우리 반의 해결 방법을 결정한다. 주의할 점 — 존중하는 말로 쓴다. 의견을 실천할 때의 어려움이나 단점처럼 의견에 도움이 되는 것을 묻는다.","scoring_points":["활동 차례(의견 붙이기 → 질문 붙이기 → 답하기 → 결정하기)를 썼는가","존중하는 말로 써야 한다는 점을 썼는가","의견에 도움이 되는 내용을 물어야 한다는 점을 썼는가"]},"explanation":["붙임쪽지 활동은 모두가 질문하고 답할 수 있어요.","질문은 친구의 기분을 헤아려 써요.","의견을 더 낫게 만드는 내용을 물어요."],"asset":{"type":"passage","lines":["어제 하굣길에 급식실 옆을 지나면서 많은 양의 음식물 쓰레기를 보았습니다.","우리가 남긴 음식물을 모아 놓은 것인데 생각했던 것보다 무척 많아서 놀랐습니다.","집에 와서 인터넷을 찾아보니 음식물 쓰레기를 처리할 때 비용이 많이 들고","온실가스가 배출되어 환경에 나쁘다고 합니다.","급식에서 음식을 남기지 않으려면 어떻게 해야 할까요?"],"title":"누리집 게시판 「급식에서 남긴 음식 문제를 어떻게 해결할까요?」 — 『국어』 142쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#1','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C12',1,'ox','auto','스스로 확인하기 ③이에요. 「친구의 기분을 고려하며 질문한다.」는 색칠할 알맞은 설명이에요.',ARRAY['K4-2-u3-X12']::text[],false,'{"seq":1,"concept":"K4-2-u3-C12","difficulty":1,"kind":"ox","stem":"스스로 확인하기 ③이에요. 「친구의 기분을 고려하며 질문한다.」는 색칠할 알맞은 설명이에요.","answer":"O","reason_options":[{"t":"친구의 의견을 존중하는 말을 한 뒤 궁금한 점을 물으면 기분 좋게 답할 수 있어요.","correct":true},{"t":"질문할 때에는 친구의 기분보다 틀린 점을 먼저 짚는 것이 중요해요.","mis":"K4-2-u3-X12"}],"mis":"K4-2-u3-X12","explanation":["윤희처럼 먼저 공감한 뒤 질문해요.","친구가 기꺼이 답하고 싶은 질문이 좋아요.","그래서 이 구름은 색칠해요."],"asset":{"type":"passage","lines":["① 문제 상황을 구체적으로 써야 한다.","② 의견의 장점만 생각하며 의견을 마련한다.","③ 친구의 기분을 고려하며 질문한다.","④ 제안하는 이유를 쓰지 않는다.","⑤ 누가 읽을 것인지 생각하지 않는다.","⑥ 주제에 알맞은 의견과 이유를 말한다."],"title":"『국어』 145쪽 스스로 확인하기 — 알맞은 설명을 모두 찾아 색칠하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#2','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C2',1,'ox','auto','토의는 친구들끼리 놀이를 정하거나 놀이 규칙을 새로 만들 때처럼 생활 속 여러 곳에서 쓰여요.',ARRAY['K4-2-u3-X01']::text[],false,'{"seq":2,"concept":"K4-2-u3-C2","difficulty":1,"kind":"ox","stem":"토의는 친구들끼리 놀이를 정하거나 놀이 규칙을 새로 만들 때처럼 생활 속 여러 곳에서 쓰여요.","answer":"O","reason_options":[{"t":"여럿이 의견을 모아 함께 정해야 하는 일은 생활 속에 많아요.","correct":true},{"t":"토의는 국어 시간에 한 사람이 정해 주는 것을 듣는 공부예요.","mis":"K4-2-u3-X01"}],"mis":"K4-2-u3-X01","explanation":["학습 시간이 아니어도 우리는 여러 차례 토의를 해요.","놀이, 규칙, 청소 구역처럼 함께 정할 일을 토의해요.","토의는 여럿이 해결 방법을 찾는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#3','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C8',1,'blank','auto','우현이네 학급 사회자가 「어떤 기준으로 의견을 결정하면 좋겠습니까?」라고 물은 것은 토의 절차의 어느 단계인가요?',ARRAY['K4-2-u3-X07']::text[],false,'{"seq":3,"concept":"K4-2-u3-C8","difficulty":1,"kind":"blank","stem":"우현이네 학급 사회자가 「어떤 기준으로 의견을 결정하면 좋겠습니까?」라고 물은 것은 토의 절차의 어느 단계인가요?","options":[{"t":"의견 결정하기","correct":true},{"t":"토의 주제 정하기","mis":"K4-2-u3-X07"},{"t":"의견 마련하기","mis":"K4-2-u3-X07"},{"t":"의견 모으기","mis":"K4-2-u3-X07"}],"explanation":["기준을 정하는 것은 의견을 결정하기 위해서예요.","윤희와 민준이가 기준을 말했어요.","기준에 따라 우현이의 의견이 골라졌어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"“이제 의견을 결정해 보겠습니다. 어떤 기준으로 의견을 결정하면 좋겠습니까?”"},{"who":"최윤희","text":"“우리가 쉽게 실천할 수 있는 의견으로 결정하면 좋겠습니다.”"},{"who":"박민준","text":"“단점보다는 장점이 큰 의견으로 결정하면 좋겠습니다.”"},{"who":"사회자","text":"“…… 더 많은 학생이 정우현 학생의 의견을 골랐습니다.”"},{"who":"선생님","text":"“여러분이 서로 질문하고 답하며 더 좋은 의견을 만들었습니다. 그러면 다음 미술 시간에는 복도 벽에 붙일 안내문을 만들어 보겠습니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#4','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C25',1,'mc','auto','「급식을 너무 많이 남겨서 버린다」는 문제를 해결하려고 제안하는 글을 쓸 때 대상으로 알맞은 분은 누구인가요?',ARRAY['K4-2-u3-X24']::text[],false,'{"seq":4,"concept":"K4-2-u3-C25","difficulty":1,"kind":"mc","stem":"「급식을 너무 많이 남겨서 버린다」는 문제를 해결하려고 제안하는 글을 쓸 때 대상으로 알맞은 분은 누구인가요?","options":[{"t":"영양 선생님","correct":true},{"t":"과자 회사","mis":"K4-2-u3-X24"},{"t":"아파트 주민","mis":"K4-2-u3-X24"},{"t":"옆 반 친구 한 명","mis":"K4-2-u3-X24"}],"explanation":["급식은 영양 선생님께서 맡아 준비하세요.","급식에 대한 제안은 영양 선생님께 할 수 있어요.","문제와 관련 있고 바꿀 수 있는 분에게 제안해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#5','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C27',1,'mc','auto','연우의 글에서 「왜냐하면 그런 공간이 있다면 날씨와 상관없이 편하고 즐겁게 음식을 먹을 수 있기 때문입니다.」는 어느 부분인가요?',ARRAY['K4-2-u3-X26']::text[],false,'{"seq":5,"concept":"K4-2-u3-C27","difficulty":1,"kind":"mc","stem":"연우의 글에서 「왜냐하면 그런 공간이 있다면 날씨와 상관없이 편하고 즐겁게 음식을 먹을 수 있기 때문입니다.」는 어느 부분인가요?","options":[{"t":"제안하는 이유","correct":true},{"t":"문제 상황","mis":"K4-2-u3-X26"},{"t":"제안하는 내용","mis":"K4-2-u3-X26"},{"t":"끝인사","mis":"K4-2-u3-X26"}],"explanation":["‘왜냐하면 ……기 때문입니다.’는 이유를 쓰는 표현이에요.","공간이 생기면 좋아지는 점을 말했어요.","이것이 제안하는 이유예요."],"asset":{"type":"passage","lines":["가람어린이과학관에 도시락이나 간식을 편하게 먹을 수 있는 공간을 만들어 주시면 좋겠습니다.","왜냐하면 그런 공간이 있다면 날씨와 상관없이 편하고 즐겁게 음식을 먹을 수 있기 때문입니다.","또 음식을 먹고 나면 과학관의 전시를 더 오랜 시간 관람할 수 있고","오후 체험 수업에도 참여할 수 있습니다.","과학관을 찾은 관람객들이 불편을 겪지 않고 좋은 추억을 간직할 수 있도록","제 제안을 잘 검토해 주시면 감사하겠습니다."],"title":"「도시락이나 간식 먹을 공간을 만들어 주세요」 뒷부분 — 『국어』 134쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#6','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C45',1,'mc','auto','다음 가운데 ‘누가/무엇이 + 어떠하다’ 짜임의 문장은 무엇인가요?',ARRAY['K4-2-u3-X45']::text[],false,'{"seq":6,"concept":"K4-2-u3-C45","difficulty":1,"kind":"mc","stem":"다음 가운데 ‘누가/무엇이 + 어떠하다’ 짜임의 문장은 무엇인가요?","options":[{"t":"과학관에는 먹을 만한 공간이 없었습니다.","correct":true},{"t":"많은 친구가 공놀이를 즐깁니다.","mis":"K4-2-u3-X45"},{"t":"관람객들이 가족과 행복한 추억을 만듭니다.","mis":"K4-2-u3-X45"},{"t":"줄넘기는 누구나 할 수 있는 운동입니다.","mis":"K4-2-u3-X45"}],"explanation":["‘공간이’는 무엇이에 해당해요.","‘없었습니다’는 상태를 나타내는 어떠하다예요.","즐깁니다·만듭니다는 어찌하다, 운동입니다는 무엇이다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#7','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C56',1,'mc','auto','‘책’과 ‘그림책’은 어떤 관계인가요?',ARRAY['K4-2-u3-X53']::text[],false,'{"seq":7,"concept":"K4-2-u3-C56","difficulty":1,"kind":"mc","stem":"‘책’과 ‘그림책’은 어떤 관계인가요?","options":[{"t":"뜻을 포함하거나 뜻에 포함되는 관계","correct":true},{"t":"뜻이 비슷한 관계","mis":"K4-2-u3-X53"},{"t":"뜻이 반대인 관계","mis":"K4-2-u3-X53"},{"t":"아무 관계가 없다","mis":"K4-2-u3-X53"}],"explanation":["그림책은 책의 한 가지예요.","책은 그림책, 동화책, 교과서를 포함해요.","그래서 뜻을 포함하는 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#8','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C4',1,'mc','auto','토의할 때의 바른 태도로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X03','K4-2-u3-X60']::text[],false,'{"seq":8,"concept":"K4-2-u3-C4","difficulty":1,"kind":"mc","stem":"토의할 때의 바른 태도로 알맞은 것은 무엇인가요?","options":[{"t":"사회자에게 말할 기회를 얻어 말하고, 나와 다른 의견도 존중하며 끝까지 듣는다","correct":true},{"t":"목소리 큰 친구의 의견을 그대로 따른다","mis":"K4-2-u3-X03"},{"t":"친구가 말할 때 끼어들어 내 의견을 먼저 말한다","mis":"K4-2-u3-X03"},{"t":"친한 친구의 의견에만 손을 든다","mis":"K4-2-u3-X60"}],"explanation":["토의에서는 차례를 지켜 말해요.","나와 다른 의견도 존중하며 들어요.","누가 냈는지보다 의견의 내용을 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#9','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C12',2,'mc','auto','짝의 의견 「복도 안전 지킴이를 정하면 좋겠습니다.」에 대해 상대의 기분을 헤아린 질문은 무엇인가요?',ARRAY['K4-2-u3-X12','K4-2-u3-X13']::text[],false,'{"seq":9,"concept":"K4-2-u3-C12","difficulty":2,"kind":"mc","stem":"짝의 의견 「복도 안전 지킴이를 정하면 좋겠습니다.」에 대해 상대의 기분을 헤아린 질문은 무엇인가요?","options":[{"t":"“좋은 의견이에요. 그런데 복도 안전 지킴이는 어떻게 뽑으면 좋을까요?”","correct":true},{"t":"“지킴이라니, 그런 건 아무도 안 할 거예요.”","mis":"K4-2-u3-X12"},{"t":"“왜 그렇게 이상한 의견을 냈어요?”","mis":"K4-2-u3-X12"},{"t":"“좋은 의견이에요. 그런데 지킴이는 무슨 옷을 입나요?”","mis":"K4-2-u3-X13"}],"explanation":["먼저 친구의 의견을 인정하는 말을 해요.","그다음 실천 방법처럼 의견에 도움이 되는 것을 물어요.","깎아내리거나 상관없는 것을 묻지 않아요."],"asset":{"type":"speech","turns":[{"who":"짝 의견","text":"“복도 안전 지킴이를 정하면 좋겠습니다.”"},{"who":"그 이유","text":"“복도에서 뛰어다니는 친구가 있으면 경고하거나 멈추게 할 수 있기 때문입니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#10','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C16',2,'mc','auto','그림 ㉰처럼 놀이터 기구에 낙서가 가득한 문제가 우리에게 주는 영향으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X16','K4-2-u3-X25']::text[],false,'{"seq":10,"concept":"K4-2-u3-C16","difficulty":2,"kind":"mc","stem":"그림 ㉰처럼 놀이터 기구에 낙서가 가득한 문제가 우리에게 주는 영향으로 알맞은 것은 무엇인가요?","options":[{"t":"놀이터가 지저분해 보여 즐겁게 놀기 어렵다","correct":true},{"t":"누군가 기구에 낙서를 했다","mis":"K4-2-u3-X16"},{"t":"낙서를 지우는 당번을 정하자","mis":"K4-2-u3-X16"},{"t":"놀이터는 운동장 옆에 있다","mis":"K4-2-u3-X25"}],"explanation":["영향은 문제 때문에 우리가 겪는 일이에요.","낙서를 한 것은 문제가 생긴 까닭이에요.","당번을 정하자는 것은 해결 의견이에요."],"asset":{"type":"passage","lines":["㉮ [그림] ‘분실물 찾아가세요.’ — 가방·물병·신발·필통이 보관함에 잔뜩 쌓여 있다.","㉯ [그림] 복도 바닥 곳곳에 휴지와 과자 껍질 같은 쓰레기가 떨어져 있다.","㉰ [그림] 놀이터 미끄럼틀과 시소에 낙서가 가득하다."],"title":"『국어』 124쪽 — 학교나 학교 주변의 문제 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#11','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C18',2,'mc','auto','‘쉬운 의견’에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X17','K4-2-u3-X18']::text[],false,'{"seq":11,"concept":"K4-2-u3-C18","difficulty":2,"kind":"mc","stem":"‘쉬운 의견’에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"쉽게 실천할 수 있어도 문제를 해결하는지 함께 따져 본다","correct":true},{"t":"쉬우면 무조건 좋은 의견이다","mis":"K4-2-u3-X17"},{"t":"쉬운 의견은 해결에 도움이 되어도 버린다","mis":"K4-2-u3-X18"},{"t":"어려운 의견만 좋은 의견이다","mis":"K4-2-u3-X18"}],"explanation":["쉬운 의견이 문제를 풀면 아주 좋은 의견이에요.","쉬워도 문제를 풀지 못하면 알맞지 않아요.","쉬운지와 해결되는지를 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#12','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C28',2,'mc','auto','「급식 남기지 마세요!」를 제안하는 글에 어울리게 바꾼 것은 무엇인가요?',ARRAY['K4-2-u3-X28','K4-2-u3-X27','K4-2-u3-X31']::text[],false,'{"seq":12,"concept":"K4-2-u3-C28","difficulty":2,"kind":"mc","stem":"「급식 남기지 마세요!」를 제안하는 글에 어울리게 바꾼 것은 무엇인가요?","options":[{"t":"먹을 만큼만 담아서 다 먹으면 좋겠습니다. 그러면 버리는 음식이 줄어 환경을 지킬 수 있습니다.","correct":true},{"t":"급식 남기지 마세요! 남기지 마세요!","mis":"K4-2-u3-X28"},{"t":"급식을 남기면 안 됩니다.","mis":"K4-2-u3-X27"},{"t":"급식을 남기는 사람은 나빠요.","mis":"K4-2-u3-X31"}],"explanation":["막는 말 대신 할 수 있는 방법을 내놓아요.","그렇게 하면 좋아지는 점을 이유로 써요.","탓하는 말은 제안하는 글에 어울리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#13','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C43',2,'mc','auto','제안하는 이유를 쓰는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X37','K4-2-u3-X38','K4-2-u3-X36']::text[],false,'{"seq":13,"concept":"K4-2-u3-C43","difficulty":2,"kind":"mc","stem":"제안하는 이유를 쓰는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"여러 사람에게 좋은 점이나 객관적인 자료를 들어 쓴다","correct":true},{"t":"내 기분만 쓴다","mis":"K4-2-u3-X37"},{"t":"다른 곳도 다 그럴 것 같다고 쓴다","mis":"K4-2-u3-X38"},{"t":"이유는 짧을수록 좋으니 한 낱말로 쓴다","mis":"K4-2-u3-X36"}],"explanation":["이유를 개인적인 것으로만 쓰면 설득하기 어려워요.","여러 사람에게 좋은 점을 찾아 써요.","전문가 의견 같은 객관적인 자료도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#14','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C35',2,'mc','auto','알맞은 제안 내용의 조건을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u3-X34','K4-2-u3-X35']::text[],false,'{"seq":14,"concept":"K4-2-u3-C35","difficulty":2,"kind":"mc","stem":"알맞은 제안 내용의 조건을 바르게 말한 것은 무엇인가요?","options":[{"t":"문제를 해결하는 데 도움이 되고 실제로 실천할 수 있는 내용","correct":true},{"t":"해결은 되지만 실천할 수 없는 내용","mis":"K4-2-u3-X34"},{"t":"문제와 상관없는 새로운 내용","mis":"K4-2-u3-X35"},{"t":"듣는 사람이 놀랄 만큼 큰 내용","mis":"K4-2-u3-X34"}],"explanation":["제안하는 내용은 실천할 수 있어야 해요.","문제를 바로 해결하는 데 도움이 되어야 해요.","장점과 단점도 함께 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#15','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C47',2,'ox','auto','「다툼이 줄어들 것입니다.」처럼 ‘누가/무엇이’ 자리에는 일이나 물건도 올 수 있어요.',ARRAY['K4-2-u3-X47']::text[],false,'{"seq":15,"concept":"K4-2-u3-C47","difficulty":2,"kind":"ox","stem":"「다툼이 줄어들 것입니다.」처럼 ‘누가/무엇이’ 자리에는 일이나 물건도 올 수 있어요.","answer":"O","reason_options":[{"t":"‘다툼이’처럼 사람이 아닌 것도 ‘무엇이’ 자리에 와요.","correct":true},{"t":"‘누가/무엇이’ 자리에는 사람만 올 수 있어요.","mis":"K4-2-u3-X47"}],"mis":"K4-2-u3-X47","explanation":["‘무엇이’라는 말에 이미 물건이나 일이 들어 있어요.","다툼이 줄어드는 것이에요.","사람만 오는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#16','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C38',2,'mc','auto','‘……해 봅시다.’는 제안하는 글의 어느 부분에 어울리는 표현인가요?',ARRAY['K4-2-u3-X40','K4-2-u3-X63']::text[],false,'{"seq":16,"concept":"K4-2-u3-C38","difficulty":2,"kind":"mc","stem":"‘……해 봅시다.’는 제안하는 글의 어느 부분에 어울리는 표현인가요?","options":[{"t":"제안하는 내용","correct":true},{"t":"문제 상황","mis":"K4-2-u3-X40"},{"t":"제안하는 이유","mis":"K4-2-u3-X40"},{"t":"글쓴이 소개","mis":"K4-2-u3-X63"}],"explanation":["‘……해 봅시다.’는 함께 하자고 의견을 내놓는 말이에요.","‘……합시다.’, ‘……하면 좋겠습니다.’와 같은 갈래예요.","그래서 제안하는 내용에 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#17','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C31',3,'mc','auto','「문제를 해결하려면 무조건 제안하는 글을 써야 한다」는 생각을 바로잡은 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X04','K4-2-u3-X05','K4-2-u3-X30']::text[],false,'{"seq":17,"concept":"K4-2-u3-C31","difficulty":3,"kind":"mc","stem":"「문제를 해결하려면 무조건 제안하는 글을 써야 한다」는 생각을 바로잡은 말로 알맞은 것은 무엇인가요?","options":[{"t":"제안하는 글은 여러 해결 방법 가운데 하나이니 상황에 맞게 고른다","correct":true},{"t":"맞다, 제안하는 글만이 해결 방법이다","mis":"K4-2-u3-X04"},{"t":"제안하는 글은 쓸모가 없다","mis":"K4-2-u3-X05"},{"t":"글로 쓰면 언제나 받아들여진다","mis":"K4-2-u3-X30"}],"explanation":["토의, 토론, 안내문, 표어, 설문 조사, 캠페인도 해결 방법이에요.","제안하는 글은 그 가운데 하나예요.","상황에 따라 알맞은 방법을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#18','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C24',3,'mc','auto','『국어』 127쪽 「점검하기」에서 토의에 참여한 자신의 태도를 확인하는 항목은 무엇인가요?',ARRAY['K4-2-u3-X03','K4-2-u3-X58','K4-2-u3-X60']::text[],false,'{"seq":18,"concept":"K4-2-u3-C24","difficulty":3,"kind":"mc","stem":"『국어』 127쪽 「점검하기」에서 토의에 참여한 자신의 태도를 확인하는 항목은 무엇인가요?","options":[{"t":"의견과 그 이유에 대하여 질문하며 토의에 참여했나요?","correct":true},{"t":"목소리를 가장 크게 냈나요?","mis":"K4-2-u3-X03"},{"t":"내 의견이 뽑혔나요?","mis":"K4-2-u3-X58"},{"t":"친한 친구 편을 들었나요?","mis":"K4-2-u3-X60"}],"explanation":["주제에 알맞은 의견과 이유를 말했는지 확인해요.","질문하며 참여했는지, 귀 기울였는지도 확인해요.","내 의견이 뽑혔는지는 점검할 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#19','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C19',3,'mc','auto','토의 주제 「등교 시간에 학교 주변에 정차하는 차를 어떻게 줄일까?」에서 친구가 「학교에 걸어서 등교하자.」고 했어요. 의견의 어려움을 묻는 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X10','K4-2-u3-X59','K4-2-u3-X13']::text[],false,'{"seq":19,"concept":"K4-2-u3-C19","difficulty":3,"kind":"mc","stem":"토의 주제 「등교 시간에 학교 주변에 정차하는 차를 어떻게 줄일까?」에서 친구가 「학교에 걸어서 등교하자.」고 했어요. 의견의 어려움을 묻는 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"“집이 너무 먼 친구는 걸어서 오면 시간이 더 걸리지 않을까요?”","correct":true},{"t":"“걸어서 등교하면 무조건 좋으니 질문할 것이 없어요.”","mis":"K4-2-u3-X10"},{"t":"“‘등교’는 무슨 뜻인가요?”","mis":"K4-2-u3-X59"},{"t":"“좋은 의견이에요. 그런데 신발은 무슨 색이 좋을까요?”","mis":"K4-2-u3-X13"}],"explanation":["실천할 때의 어려움을 물으면 의견이 더 다듬어져요.","집이 먼 친구를 생각한 질문이에요.","낱말 뜻이나 상관없는 것을 묻는 질문은 도움이 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#20','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C40',3,'ox','auto','제안하는 글은 대상이 정해져 있어 받아들여질 수도, 받아들여지지 않을 수도 있어요.',ARRAY['K4-2-u3-X30']::text[],false,'{"seq":20,"concept":"K4-2-u3-C40","difficulty":3,"kind":"ox","stem":"제안하는 글은 대상이 정해져 있어 받아들여질 수도, 받아들여지지 않을 수도 있어요.","answer":"O","reason_options":[{"t":"그래서 대상을 분명히 알고 알맞은 표현으로 써야 해요.","correct":true},{"t":"정성껏 쓴 제안하는 글은 반드시 받아들여져요.","mis":"K4-2-u3-X30"}],"mis":"K4-2-u3-X30","explanation":["제안을 받은 사람에게도 사정이 있어요.","받아들여지지 않을 때에는 까닭을 살펴요.","대상에 맞는 표현을 쓰면 받아들여질 가능성이 높아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#21','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C48',3,'mc','auto','점검한 뒤 글을 고쳐 쓸 때의 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X42','K4-2-u3-X33']::text[],false,'{"seq":21,"concept":"K4-2-u3-C48","difficulty":3,"kind":"mc","stem":"점검한 뒤 글을 고쳐 쓸 때의 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"고칠 점과 고치는 까닭을 정리한 뒤 처음 쓴 글을 고쳐 쓴다","correct":true},{"t":"점검만 하고 고치지 않는다","mis":"K4-2-u3-X42"},{"t":"처음부터 전혀 다른 주제로 쓴다","mis":"K4-2-u3-X33"},{"t":"친구 글을 그대로 옮겨 쓴다","mis":"K4-2-u3-X42"}],"explanation":["『국어』 139쪽 (3)에서 고칠 점과 까닭을 정리해요.","그것을 바탕으로 137쪽에 쓴 글을 고쳐 써요.","점검은 고쳐 쓰기로 이어져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#22','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C53',3,'mc','auto','『국어』 141쪽 낱말 풀이에서 ‘안건’의 뜻은 무엇인가요?',ARRAY['K4-2-u3-X50','K4-2-u3-X57']::text[],false,'{"seq":22,"concept":"K4-2-u3-C53","difficulty":3,"kind":"mc","stem":"『국어』 141쪽 낱말 풀이에서 ‘안건’의 뜻은 무엇인가요?","options":[{"t":"토의하거나 조사해야 할 사실","correct":true},{"t":"이미 결정되어 바꿀 수 없는 일","mis":"K4-2-u3-X50"},{"t":"한 사람이 정한 명령","mis":"K4-2-u3-X57"},{"t":"쉬는 시간에 하는 놀이","mis":"K4-2-u3-X50"}],"explanation":["안건은 함께 토의할 거리예요.","전교 학생회에 안건을 내면 학생들이 함께 토의해요.","제안하는 글을 전하는 방법 가운데 하나예요."],"asset":{"type":"passage","lines":["교장 선생님 — 직접 방문하기 · 학교 누리집에 올리기 · 편지 쓰기","우리 학교 친구들 — 전교 학생회에 안건 내기 · 학교 누리집에 올리기","· 허락을 받고 알림판에 붙이기","안건: 토의하거나 조사해야 할 사실."],"title":"『국어』 141쪽 보기 — 제안하는 글을 전달하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#23','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C41',4,'mc','auto','지산이의 글에서 제안하는 내용과 이유를 바르게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u3-X06','K4-2-u3-X37','K4-2-u3-X36']::text[],false,'{"seq":23,"concept":"K4-2-u3-C41","difficulty":4,"kind":"mc","stem":"지산이의 글에서 제안하는 내용과 이유를 바르게 짝지은 것은 무엇인가요?","options":[{"t":"점심시간 운동장 사용 규칙 만들기 — 다툼이 줄고 더 많은 친구가 즐겁게 지낼 수 있다","correct":true},{"t":"공놀이하는 친구들이 운동장을 다 차지한다 — 줄넘기를 못 한다","mis":"K4-2-u3-X06"},{"t":"공놀이를 금지하자 — 내가 줄넘기를 좋아해서","mis":"K4-2-u3-X37"},{"t":"운동장 사용 규칙 만들기 — 교장 선생님이 바쁘셔서","mis":"K4-2-u3-X36"}],"explanation":["제안하는 내용은 ‘……면 좋겠습니다’에 있어요.","이유는 그렇게 하면 좋아지는 점이에요.","운동장을 차지하는 것은 문제 상황이에요."],"asset":{"type":"passage","lines":["교장 선생님, 안녕하세요? 저는 4학년 최지산입니다.","요즘 우리 학교에 운동장을 사용하는 것 때문에 다툼이 많습니다.","특히 점심시간에 공놀이하는 친구들이 운동장을 모두 차지하고 있어","줄넘기나 다른 놀이를 하려는 친구들은 운동장을 사용하기가 어렵습니다.","요일별로 학년을 정하거나 운동장을 나누어 사용하는 방식과 같이","점심시간 운동장 사용 규칙을 만들면 좋겠습니다. 이렇게 하면 운동장을 둘러싼 다툼이 줄어들 것입니다.","그리고 더 많은 친구가 운동장에서 즐겁고 신나는 시간을 보낼 수 있을 것입니다.","바쁘시겠지만 제 제안을 잘 살펴봐 주시면 감사하겠습니다."],"title":"「운동장을 다 함께 사용하게 해 주세요」 — 『국어』 129쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#24','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C43',4,'essay','teacher','『국어활동』 41쪽처럼 우리 마을 주민들에게 제안하고 싶은 내용을 생각해 문제 상황, 제안하는 내용, 제안하는 이유를 쓰세요. 이유에는 제안이 문제 상황에 도움이 되며 꼭 필요하다는 것을 밝히세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u3-C43","difficulty":4,"kind":"essay","stem":"『국어활동』 41쪽처럼 우리 마을 주민들에게 제안하고 싶은 내용을 생각해 문제 상황, 제안하는 내용, 제안하는 이유를 쓰세요. 이유에는 제안이 문제 상황에 도움이 되며 꼭 필요하다는 것을 밝히세요.","answer_guide":{"answer":"예: 문제 상황 — 우리 동네에 여기저기 버려진 쓰레기가 많다. 제안하는 내용 — 일주일에 하루를 정해 동네를 산책하며 쓰레기를 줍는 날을 만들자. 이유 — 운동도 하면서 동네를 깨끗하게 만들 수 있고, 쓰레기를 버리지 않는 습관도 생긴다.","scoring_points":["마을의 문제 상황을 구체적으로 썼는가","주민들이 실천할 수 있는 제안을 썼는가","제안이 문제 해결에 도움이 되고 필요하다는 이유를 썼는가"]},"explanation":["마을 사람들이 함께 겪는 문제를 찾아요.","주민 모두가 실천할 수 있는 제안을 해요.","이유에는 제안이 꼭 필요하다는 점을 밝혀요."],"asset":{"type":"passage","lines":["안녕하세요? 주민 여러분. 저는 ○○동에 사는 초등학교 4학년 조대웅입니다.","요즘 동네를 다니다 보면 여기저기에 버려진 쓰레기가 많습니다.","길가에 놓인 플라스틱 컵, 놀이터에 떨어진 과자 봉지, 화단 구석에 쌓인 휴지까지…….","일주일에 하루를 정해 동네를 산책하면서 쓰레기를 줍는 날을 만들면 어떨까요?","산책하면서 쓰레기를 하나씩 주우면 운동도 하면서 동네를 깨끗하게 만들 수 있어","일석이조의 효과를 볼 수 있기 때문입니다. 또 쓰레기를 길가에 버리지 않는 습관도 생길 것입니다.","주민 여러분, 작은 실천을 모아 우리 동네를 더 깨끗하고 살기 좋은 곳으로 만들어요!"],"title":"「깨끗한 동네를 만들기 위해 함께 노력해요」 — 『국어활동』 40쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u3_review_d#25','kor',4,2,'u3','','tb_g4_2_kor_u3_review_d','unit_review','K4-2-u3-C20',4,'essay','teacher','「우현이네 학급 토의 시간」에서 질문이 의견을 어떻게 바꾸었는지 설명하고, 토의할 때 질문하는 사람과 답하는 사람이 지켜야 할 점을 각각 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u3-C20","difficulty":4,"kind":"essay","stem":"「우현이네 학급 토의 시간」에서 질문이 의견을 어떻게 바꾸었는지 설명하고, 토의할 때 질문하는 사람과 답하는 사람이 지켜야 할 점을 각각 쓰세요.","answer_guide":{"answer":"예: 윤희가 안내문이 잘 안 보일 수 있다고 묻자, 우현이는 안내문을 입체적으로 만들자고 답해 의견이 더 구체적이 되었다. 질문하는 사람은 먼저 친구의 의견을 존중한 뒤 궁금한 점을 물어야 하고, 답하는 사람은 질문을 생각해 보고 필요하면 의견을 고쳐 더 낫게 만들어야 한다.","scoring_points":["질문 뒤 의견이 구체적으로 바뀐 내용을 썼는가","질문하는 사람이 지킬 점을 썼는가","답하는 사람이 지킬 점을 썼는가"]},"explanation":["질문은 의견을 다듬어 더 낫게 만들어요.","질문할 때에는 상대의 기분을 헤아려요.","답할 때에는 질문을 받아들여 의견을 고쳐도 괜찮아요."],"asset":{"type":"speech","turns":[{"who":"김규빈","text":"“복도 가운데에 표지판을 놓아두면 좋겠습니다. 왜냐하면 표지판이 복도 가운데에 있으면 옆으로 피해 한쪽으로만 다니게 할 수 있기 때문입니다.”"},{"who":"박민준","text":"“그런데 복도 가운데에 표지판이 있으면 거기에 부딪히는 친구도 있지 않을까요?”"},{"who":"정우현","text":"“복도 벽에 뛰어다니지 말라는 안내문을 붙이면 좋겠습니다. 왜냐하면 학생들이 안내문을 보면서 다시 한번 뛰어다니면 안 된다고 생각할 수 있기 때문입니다.”"},{"who":"최윤희","text":"“좋은 의견입니다. 그런데 안내문을 벽에 붙여 놓으면 복도를 다닐 때 잘 안 보일 수도 있지 않을까요?”"},{"who":"정우현","text":"“안내문을 조금 입체적으로 만들어 보면 어떨까요? 그러면 복도를 다닐 때 잘 볼 수 있을 것 같습니다.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
